local request, getToken, setToken, jsonEncode, getLastLatencyMs, pingHealth
do
local lastLatencyMs = 0
local etagCache = {}

jsonEncode = function(value)
	return Services.HttpService:JSONEncode(value)
end

local function jsonDecode(value)
	return Services.HttpService:JSONDecode(value)
end

-- RequestAsync error bodies are decoded when they contain JSON. Keep that
-- structured data internally, but never let Roblox's `table: 0x...` rendering
-- escape into the UI.
local function requestErrorMessage(value, depth)
	if type(value) == "string" and value ~= "" then
		return value
	end
	if type(value) ~= "table" then
		return tostring(value or "Request failed")
	end

	depth = tonumber(depth) or 0
	if depth < 2 then
		for _, key in ipairs({ "message", "error", "detail", "code" }) do
			local candidate = value[key]
			if type(candidate) == "string" and candidate ~= "" then
				return candidate
			end
			if type(candidate) == "table" then
				local nested = requestErrorMessage(candidate, depth + 1)
				if nested ~= "Request failed" then
					return nested
				end
			end
		end
	end

	return "Request failed"
end

local function getBackendUrl()
	if plugin:GetSetting("nexusrbxDevMode") == true then
		local override = plugin:GetSetting("nexusrbxBackendUrl")
		if type(override) == "string" and override ~= "" then
			return override:gsub("/+$", "")
		end
	end
	return BACKEND_URL
end

local function classifyStatus(statusCode, networkError)
	if networkError then
		return "network", true
	end
	if statusCode == 401 or statusCode == 403 then
		return "auth", false
	end
	if statusCode == 304 then
		return "ok", false
	end
	if statusCode == 429 then
		return "rate_limited", true
	end
	if statusCode >= 500 then
		return "server", true
	end
	if statusCode >= 400 then
		return "client", false
	end
	return "ok", false
end

local function parseRetryAfter(headers)
	if type(headers) ~= "table" then
		return nil
	end
	local value = headers["Retry-After"] or headers["retry-after"]
	if value == nil then
		return nil
	end
	local seconds = tonumber(value)
	if seconds then
		return math.clamp(seconds, 0, 60)
	end
	return nil
end

local function requestOnce(method, path, body, token, opts)
	opts = opts or {}
	local started = os.clock()
	local headers = {
		["Content-Type"] = "application/json",
		["Accept"] = "application/json",
	}
	if token then
		headers["Authorization"] = "Bearer " .. token
	end
	if type(opts.idempotencyKey) == "string" and opts.idempotencyKey ~= "" then
		headers["Idempotency-Key"] = opts.idempotencyKey
	elseif opts.idempotent then
		headers["Idempotency-Key"] = Services.HttpService:GenerateGUID(false)
	end
	if opts.useEtag and etagCache[path] then
		headers["If-None-Match"] = etagCache[path]
	end

	local requestBody = body and jsonEncode(body) or nil
	local useGzip = opts.compress == true or (requestBody and #requestBody > 4096)

	local ok, response = pcall(function()
		return Services.HttpService:RequestAsync({
			Url = getBackendUrl() .. path,
			Method = method,
			Headers = headers,
			Body = requestBody,
			Compress = useGzip and Enum.HttpCompression.Gzip or nil,
		})
	end)

	lastLatencyMs = math.floor((os.clock() - started) * 1000 + 0.5)

	if not ok then
		return {
			ok = false,
			kind = "network",
			retryable = true,
			status = 0,
			data = tostring(response),
			latencyMs = lastLatencyMs,
		}
	end

	if type(response.Headers) == "table" then
		local etag = response.Headers["ETag"] or response.Headers["etag"]
		if etag and opts.useEtag then
			etagCache[path] = etag
		end
	end

	if response.StatusCode == 204 then
		return {
			ok = true,
			kind = "ok",
			retryable = false,
			status = 204,
			data = nil,
			latencyMs = lastLatencyMs,
		}
	end

	if response.StatusCode == 304 then
		return {
			ok = true,
			kind = "ok",
			retryable = false,
			status = 304,
			data = { unchanged = true },
			latencyMs = lastLatencyMs,
		}
	end

	local kind, retryable = classifyStatus(response.StatusCode, false)
	if not response.Success then
		local errorData = response.Body ~= "" and response.Body or ("HTTP " .. tostring(response.StatusCode))
		if response.Body and response.Body ~= "" then
			local decodedErrorOk, decodedError = pcall(jsonDecode, response.Body)
			if decodedErrorOk then
				errorData = decodedError
			end
		end
		return {
			ok = false,
			kind = kind,
			retryable = retryable,
			status = response.StatusCode,
			data = errorData,
			retryAfter = parseRetryAfter(response.Headers),
			latencyMs = lastLatencyMs,
		}
	end

	if response.Body == nil or response.Body == "" then
		return {
			ok = true,
			kind = "ok",
			retryable = false,
			status = response.StatusCode,
			data = nil,
			latencyMs = lastLatencyMs,
		}
	end

	local decodedOk, decoded = pcall(jsonDecode, response.Body)
	if not decodedOk then
		return {
			ok = false,
			kind = "decode",
			retryable = false,
			status = response.StatusCode,
			data = "Invalid JSON response: " .. tostring(decoded),
			latencyMs = lastLatencyMs,
		}
	end

	return {
		ok = true,
		kind = "ok",
		retryable = false,
		status = response.StatusCode,
		data = decoded,
		latencyMs = lastLatencyMs,
	}
end

local function requestWithRetry(method, path, body, token, opts)
	opts = opts or {}
	-- A retry is another delivery attempt for the same operation, not a new
	-- operation. Resolve the key once before the loop so the backend can replay
	-- the original receipt if the first response was lost.
	if opts.idempotent and (type(opts.idempotencyKey) ~= "string" or opts.idempotencyKey == "") then
		opts.idempotencyKey = Services.HttpService:GenerateGUID(false)
	end
	local normalizedMethod = string.upper(tostring(method or "GET"))
	local retrySafe = normalizedMethod == "GET"
		or normalizedMethod == "HEAD"
		or normalizedMethod == "OPTIONS"
		or opts.idempotent == true
		or (type(opts.idempotencyKey) == "string" and opts.idempotencyKey ~= "")
	local defaultAttempts = retrySafe and 3 or 1
	local maxAttempts = math.clamp(tonumber(opts.maxAttempts) or defaultAttempts, 1, 5)
	local baseDelay = tonumber(opts.baseDelay) or 0.5
	local attempt = 0
	local lastResult

	while attempt < maxAttempts do
		attempt = attempt + 1
		lastResult = requestOnce(method, path, body, token, opts)
		if lastResult.ok or not lastResult.retryable or attempt >= maxAttempts then
			return lastResult
		end
		local delay = lastResult.retryAfter
		if not delay then
			delay = math.min(baseDelay * (2 ^ (attempt - 1)), 8) + (math.random() * 0.25)
		end
		task.wait(delay)
	end

	return lastResult
end

request = function(method, path, body, token, opts)
	local result = requestWithRetry(method, path, body, token, opts)
	if result.ok then
		return true, result.data, result.status
	end
	return false, requestErrorMessage(result.data), result.status
end

getLastLatencyMs = function()
	return lastLatencyMs
end

pingHealth = function()
	local result = requestOnce("GET", "/health", nil, nil, { maxAttempts = 1 })
	return result.ok == true, result.latencyMs or lastLatencyMs
end

-- Authenticated heartbeat. It never claims a command and the backend throttles
-- its single session write while returning collaborator and MCP summaries.
function pingSession(token, placeSignature, studio)
	if not token then
		return false, lastLatencyMs, false
	end
	local body = {}
	if type(placeSignature) == "string" and placeSignature ~= "" then
		body.placeSignature = placeSignature
	end
	if type(studio) == "table" then
		body.studio = studio
	end
	local result = requestOnce("POST", "/api/studio/session/ping", body, token, { maxAttempts = 1 })
	if result.status == 401 or result.status == 403 or (result.status == 409 and type(result.data) == "table" and result.data.code == "STUDIO_SESSION_REPLACED") then
		return false, result.latencyMs or lastLatencyMs, true, result.data
	end
	return result.ok == true, result.latencyMs or lastLatencyMs, false, result.data
end

getToken = function()
	return plugin:GetSetting("nexusrbxStudioToken")
end

setToken = function(token)
	plugin:SetSetting("nexusrbxStudioToken", token)
end
end
