	ObjectValue = true,
	Configuration = true,
	Script = true,
	LocalScript = true,
	ModuleScript = true,
	KeyframeSequence = true,
	Keyframe = true,
	Pose = true,
}

AGENT_ARTIFACT_ID_ATTRIBUTE = "AgentArtifactId"
AGENT_FILE_ID_ATTRIBUTE = "AgentFileId"
local NEXUS_MANAGED_ID_ATTRIBUTE = "NexusManagedId"
lastBatchSnapshots = {}

stableHash = function(value)
	local hash = 2166136261
	local text = tostring(value or "")
	for i = 1, #text do
		hash = bit32.bxor(hash, string.byte(text, i))
		hash = (hash * 16777619) % 4294967296
	end
	return string.format("%08x", hash)
end

nowMs = function()
	return math.floor(os.clock() * 1000)
end

ensureManagedId = function(inst)
	if not inst or inst == game then
		return nil
	end
	local existing = inst:GetAttribute(NEXUS_MANAGED_ID_ATTRIBUTE)
	if existing and tostring(existing) ~= "" then
		return tostring(existing)
	end
	local nextId = Services.HttpService:GenerateGUID(false)
	local ok = pcall(function()
		inst:SetAttribute(NEXUS_MANAGED_ID_ATTRIBUTE, nextId)
	end)
	return ok and nextId or nil
end

readManagedId = function(inst)
	if not inst or inst == game then
		return nil
	end
	local existing = inst:GetAttribute(NEXUS_MANAGED_ID_ATTRIBUTE)
	return existing and tostring(existing) or nil
end

attributesOf = function(inst)
	local ok, attrs = pcall(function()
		return inst:GetAttributes()
	end)
	return ok and attrs or {}
end

safePropertyValue = function(inst, key)
	local ok, value = pcall(function()
		return inst[key]
	end)
	if not ok then
		return nil
	end
	local valueType = typeof(value)
	if valueType == "string" or valueType == "number" or valueType == "boolean" then
		return value
	elseif valueType == "Color3" then
		return { r = value.R, g = value.G, b = value.B, type = "Color3" }
	elseif valueType == "UDim2" then
		return {
			type = "UDim2",
			xScale = value.X.Scale,
			xOffset = value.X.Offset,
			yScale = value.Y.Scale,
			yOffset = value.Y.Offset,
		}
	elseif valueType == "UDim" then
		return { type = "UDim", scale = value.Scale, offset = value.Offset }
	elseif valueType == "Vector2" then
		return { type = "Vector2", x = value.X, y = value.Y }
	elseif valueType == "Vector3" then
		return { type = "Vector3", x = value.X, y = value.Y, z = value.Z }
	elseif valueType == "CFrame" then
		local x, y, z, r00, r01, r02, r10, r11, r12, r20, r21, r22 = value:GetComponents()
		return {
			type = "CFrame",
			components = { x, y, z, r00, r01, r02, r10, r11, r12, r20, r21, r22 },
		}
	elseif valueType == "EnumItem" then
		return tostring(value)
	elseif valueType == "ColorSequence" then
		local keypoints = {}
		for _, keypoint in ipairs(value.Keypoints) do
			table.insert(keypoints, {
				time = keypoint.Time,
				color = { r = keypoint.Value.R, g = keypoint.Value.G, b = keypoint.Value.B },
			})
		end
		return { type = "ColorSequence", keypoints = keypoints }
	elseif valueType == "NumberSequence" then
		local keypoints = {}
		for _, keypoint in ipairs(value.Keypoints) do
			table.insert(keypoints, { time = keypoint.Time, value = keypoint.Value, envelope = keypoint.Envelope })
		end
		return { type = "NumberSequence", keypoints = keypoints }
	end
	return nil
end

propertiesOf = function(inst)
	local props = {
		Name = inst.Name,
		ClassName = inst.ClassName,
	}
	local candidates = {
		"Value",
		"Enabled",
		"ResetOnSpawn",
		"IgnoreGuiInset",
		"DisplayOrder",
		"Text",
		"PlaceholderText",
		"Visible",
		"Size",
		"Position",
		"AnchorPoint",
		"BackgroundTransparency",
		"BackgroundColor3",
		"BorderSizePixel",
		"ClipsDescendants",
		"Rotation",
		"TextColor3",
		"TextSize",
		"TextWrapped",
		"TextScaled",
		"TextXAlignment",
		"TextYAlignment",
		"Font",
		"TextTransparency",
		"ImageTransparency",
		"Image",
		"ImageColor3",
		"ScaleType",
		"CanvasSize",
		"AutomaticCanvasSize",
		"ScrollBarThickness",
		"AutoButtonColor",
		"Texture",
		"MeshId",
		"TextureID",
		"TextureId",
		"SoundId",
		"AnimationId",
		"Loop",
		"Priority",
		"Time",
		"Weight",
		"CFrame",
		"EasingStyle",
		"EasingDirection",
		"ZIndex",
		"LayoutOrder",
		"SortOrder",
		"Padding",
		"PaddingTop",
		"PaddingRight",
		"PaddingBottom",
		"PaddingLeft",
		"FillDirection",
		"HorizontalAlignment",
		"VerticalAlignment",
		"CellSize",
		"CellPadding",
		"CornerRadius",
		"Color",
		"Transparency",
		"AspectRatio",
		"MinSize",
		"MaxSize",
		"MinTextSize",
		"MaxTextSize",
		"Scale",
		"Thickness",
	}
	for _, key in ipairs(candidates) do
		local value = safePropertyValue(inst, key)
		if value ~= nil then
			props[key] = value
		end
	end
	return props
end

propertyHash = function(inst)
	-- Nested helpers avoid spending scarce top-level local registers in the
	-- generated single-chunk plugin bundle.
	local function isArrayTable(value)
		local count = 0
		local highest = 0
		for key in pairs(value) do
			if type(key) ~= "number" or key < 1 or key ~= math.floor(key) then
				return false, 0
			end
			count += 1
			highest = math.max(highest, key)
		end
		return count == highest, highest
	end
	local canonicalEncode
	canonicalEncode = function(value)
		if type(value) ~= "table" then
			return jsonEncode(value)
		end
		local isArray, length = isArrayTable(value)
		if isArray then
			local entries = {}
			for index = 1, length do
				table.insert(entries, canonicalEncode(value[index]))
			end
			return "[" .. table.concat(entries, ",") .. "]"
		end
		local entries = {}
		for key, childValue in pairs(value) do
			table.insert(entries, { key = tostring(key), value = childValue })
		end
		table.sort(entries, function(a, b)
			return a.key < b.key
		end)
		local encoded = {}
		for _, entry in ipairs(entries) do
			table.insert(encoded, jsonEncode(entry.key) .. ":" .. canonicalEncode(entry.value))
		end
		return "{" .. table.concat(encoded, ",") .. "}"
	end
	local tags = Services.CollectionService:GetTags(inst)
	table.sort(tags)
	return stableHash(
		canonicalEncode(propertiesOf(inst))
			.. "\0"
			.. canonicalEncode(attributesOf(inst))
			.. "\0"
			.. table.concat(tags, "\0")
	)
end

scriptHash = function(inst)
	if not inst or not SCRIPT_CLASSES[inst.ClassName] then
		return nil
	end
	if type(readScriptSource) ~= "function" then
		return nil
	end
	local ok, source = readScriptSource(inst)
	return ok and stableHash(source) or nil
end

-- Every mutation of an existing script must be tied to the exact source the
-- caller inspected. This avoids silently overwriting Studio edits made between
-- a read and a queued write.
verifyExpectedScriptHash = function(inst, expectedSourceHash, requestedPath)
	if not inst or not SCRIPT_CLASSES[inst.ClassName] then
		return true, nil
	end

	local targetPath = tostring(requestedPath or "")
	if targetPath == "" then
		targetPath = fullPath(inst)
	end
	local currentSourceHash = scriptHash(inst)
	if currentSourceHash == nil then
		return false, {
			ok = false,
			success = false,
			code = "source_read_failed",
			error = "Could not read the current Studio script source",
			path = targetPath,
			retryable = false,
		}
	end

	local expected = tostring(expectedSourceHash or "")
	if expected == "" then
		return false, {
			ok = false,
			success = false,
			code = "expected_source_hash_required",
			error = "expectedSourceHash is required before mutating an existing script",
			path = targetPath,
			currentSourceHash = currentSourceHash,
			retryable = false,
		}
	end
	if expected ~= currentSourceHash then
		return false, {
			ok = false,
			success = false,
			code = "source_conflict",
			error = "Source hash conflict",
			path = targetPath,
			expectedSourceHash = expected,
			currentSourceHash = currentSourceHash,
			retryable = false,
		}
	end
	return true, currentSourceHash
end

structuredUnsupported = function(operation, message)
	return {
		ok = false,
		success = false,
		operation = operation,
		error = {
			code = "unsupported_in_studio_plugin",
			message = message or (operation .. " is not supported by this Studio plugin runtime"),
			retryable = false,
		},
		warnings = {},
		diagnostics = {},
		affectedPaths = {},
	}
end

escapePattern = function(text)
	return tostring(text or ""):gsub("([^%w])", "%%%1")
end

escapeReplacement = function(text)
	return tostring(text or ""):gsub("%%", "%%%%")
end
end
-- END src/studio/serialization.lua

-- BEGIN src/studio/path.lua
do
-- Studio manifests and tool payloads use slash-delimited paths. Older agent
-- runs occasionally produced a dotted Starter Player path, e.g.
-- `StarterPlayer.StarterPlayerScripts.MainMenuClient`; normalize only the
-- unambiguous service aliases so dots in ordinary instance names remain valid.
local starterPlayerService = "StarterPlayer"
local starterPlayerServicePath = "Services.StarterPlayer"

local function canonicalizePath(path)
	local raw = tostring(path or "")
	raw = raw:gsub("^%s+", ""):gsub("%s+$", "")
	raw = raw:gsub("\\", "/"):gsub("/+$", "")
	raw = raw:gsub("^game[/.]", "")
	raw = raw:gsub("^Services[/.]", "")

	local dottedPrefixes = {
		[starterPlayerService .. ".StarterPlayerScripts"] = starterPlayerService .. "/StarterPlayerScripts",
		["StarterPlayerScripts"] = starterPlayerService .. "/StarterPlayerScripts",
	}
	for dottedPrefix, canonicalPrefix in pairs(dottedPrefixes) do
		if raw == dottedPrefix then
			return canonicalPrefix
		end
		local dottedStart = dottedPrefix .. "."
		if raw:sub(1, #dottedStart) == dottedStart then
			-- This input form is an old dotted hierarchy, not an instance name.
			return canonicalPrefix .. "/" .. raw:sub(#dottedStart + 1):gsub("%.", "/")
		end
	end
	return raw
end

splitPath = function(path)
	local parts = {}
	for part in canonicalizePath(path):gmatch("[^/]+") do
		if part ~= "" and part ~= "game" then
			table.insert(parts, part)
		end
	end
	return parts
end

local function createPathContainer(parent, name)
	if parent == Services.StarterPlayer then
		if name == "StarterPlayerScripts" then
			return Instance.new("StarterPlayerScripts")
		elseif name == "StarterCharacterScripts" then
			return Instance.new("StarterCharacterScripts")
		end
	end
	return Instance.new("Folder")
end

rootFromParts = function(parts)
	local first = parts[1]
	local rootInst = SERVICE_ROOTS and SERVICE_ROOTS[first]
	if rootInst then
		return rootInst, 2
	end
	if first == "Services" and parts[2] and SERVICE_ROOTS then
		local splitRoot = SERVICE_ROOTS[parts[2]] or SERVICE_ROOTS["Services." .. parts[2]]
		if splitRoot then
			return splitRoot, 3
		end
	end
	return nil, 1
end

fullPath = function(inst)
	if not inst then
		return ""
	end
	local names = {}
	local cur = inst
	while cur and cur ~= game do
		table.insert(names, 1, cur.Name)
		cur = cur.Parent
	end
	return table.concat(names, "/")
end

resolvePath = function(path)
	local parts = splitPath(path)
	local rootInst, startIndex = rootFromParts(parts)
	if not rootInst then
		return nil
	end
	local current = rootInst
	for i = startIndex, #parts do
		current = current:FindFirstChild(parts[i])
		if not current then
			return nil
		end
	end
	return current
end

ensureParent = function(path, createParents)
	local parts = splitPath(path)
	local rootInst, startIndex = rootFromParts(parts)
	if not rootInst or #parts < startIndex then
		return nil, nil
	end
	local current = rootInst
	for i = startIndex, #parts - 1 do
		local child = current:FindFirstChild(parts[i])
		if not child then
			if not createParents then
				return nil, nil
			end
			child = createPathContainer(current, parts[i])
			child.Name = parts[i]
			child.Parent = current
		end
		current = child
	end
	return current, parts[#parts]
end

SAFE_UI_RESTORE_PROPERTIES = {
	Enabled = true, DisplayOrder = true, PlaceholderText = true, BorderSizePixel = true, ClipsDescendants = true,
	Rotation = true, TextWrapped = true, TextScaled = true, TextXAlignment = true,
	TextYAlignment = true, Font = true, ImageColor3 = true, ScaleType = true, CanvasSize = true,
	AutomaticCanvasSize = true, ScrollBarThickness = true, AutoButtonColor = true,
	PaddingTop = true, PaddingRight = true, PaddingBottom = true, PaddingLeft = true,
	FillDirection = true, HorizontalAlignment = true, VerticalAlignment = true, CellSize = true,
	CellPadding = true, SortOrder = true, Color = true, Transparency = true, AspectRatio = true,
	MinSize = true, MaxSize = true, MinTextSize = true, MaxTextSize = true, Scale = true,
}

safeSetProperty = function(inst, key, value)
	local ok, err = pcall(function()
		if typeof(value) == "table" then
			local valueType = tostring(value.type or value["$type"] or value.__type or "")
			if valueType == "EnumItem" then
				local enumName = tostring(value.enumName or value.enumType or ""):gsub("[^%w_]", "")
				local itemName = tostring(value.name or value.itemName or ""):gsub("[^%w_]", "")
				if enumName ~= "" and itemName ~= "" then
					value = "Enum." .. enumName .. "." .. itemName
				end
			elseif valueType == "UDim2" then
				value = UDim2.new(value.xScale or 0, value.xOffset or 0, value.yScale or 0, value.yOffset or 0)
			elseif (key == "Size" or key == "Position") and typeof(value.X) == "table" and typeof(value.Y) == "table" then
				-- The planner's structured-output schema uses Roblox's X/Y shape.
				-- Accept it at the trust boundary and convert it to the canonical
				-- UDim2 representation used by manifest readback.
				value = UDim2.new(
					value.X.Scale or value.X.scale or 0,
					value.X.Offset or value.X.offset or 0,
					value.Y.Scale or value.Y.scale or 0,
					value.Y.Offset or value.Y.offset or 0
				)
			elseif valueType == "UDim" then
				value = UDim.new(value.scale or 0, value.offset or 0)
			elseif valueType == "Color3" or (
				(key == "TextColor3" or key == "BackgroundColor3" or key == "ImageColor3" or key == "Color")
				and (value.r ~= nil or value.R ~= nil)
				and (value.g ~= nil or value.G ~= nil)
				and (value.b ~= nil or value.B ~= nil)
			) then
				local r = tonumber(value.r or value.R) or 0
				local g = tonumber(value.g or value.G) or 0
				local b = tonumber(value.b or value.B) or 0
				local divisor = (r > 2 or g > 2 or b > 2) and 255 or 1
				value = Color3.new(
					math.clamp(r / divisor, 0, 1),
					math.clamp(g / divisor, 0, 1),
					math.clamp(b / divisor, 0, 1)
				)
			elseif valueType == "Vector2" then
				value = Vector2.new(value.x or 0, value.y or 0)
			elseif valueType == "Vector3" then
				value = Vector3.new(value.x or 0, value.y or 0, value.z or 0)
			elseif valueType == "CFrame" and typeof(value.components) == "table" and #value.components == 12 then
				value = CFrame.new(table.unpack(value.components))
			elseif valueType == "ColorSequence" then
				local keypoints = {}
				for _, keypoint in ipairs(value.keypoints or {}) do
					local color = keypoint.color or {}
					table.insert(keypoints, ColorSequenceKeypoint.new(
						keypoint.time or 0,
						Color3.new(color.r or 0, color.g or 0, color.b or 0)
					))
				end
				value = ColorSequence.new(keypoints)
			elseif valueType == "NumberSequence" then
				local keypoints = {}
				for _, keypoint in ipairs(value.keypoints or {}) do
					table.insert(keypoints, NumberSequenceKeypoint.new(
						keypoint.time or 0,
						keypoint.value or 0,
						keypoint.envelope or 0
					))
				end
				value = NumberSequence.new(keypoints)
			end
		end
		if type(value) == "string" then
			local enumType, enumItem = value:match("^Enum%.([%w_]+)%.([%w_]+)$")
			if enumType and enumItem and Enum[enumType] then
				value = Enum[enumType][enumItem] or value
			end
		end
		local nativeAllow = NATIVE_PROPERTY_ALLOWLIST[inst.ClassName]
		if key == "Position" and inst:IsA("BasePart") and typeof(value) == "Vector3" then
			inst.Position = value
		elseif nativeAllow and nativeAllow[key] == true then
			-- create_instance and snapshot restore share the same conservative
			-- native-property boundary as build_native_model. Values have already
			-- been converted above and pcall keeps invalid assignments fail-closed.
			inst[key] = value
		elseif key == "Value" and inst:IsA("ValueBase") then
			inst.Value = value
		elseif key == "ResetOnSpawn" and inst:IsA("ScreenGui") then
			inst.ResetOnSpawn = value ~= false
		elseif key == "IgnoreGuiInset" and inst:IsA("ScreenGui") then
			inst.IgnoreGuiInset = value ~= false
		elseif key == "Enabled" and inst:IsA("ScreenGui") then
			inst.Enabled = value ~= false
		elseif key == "Text" and (inst:IsA("TextLabel") or inst:IsA("TextButton") or inst:IsA("TextBox")) then
			inst.Text = tostring(value)
		elseif key == "Visible" and inst:IsA("GuiObject") then
			inst.Visible = value ~= false
		elseif key == "Size" and inst:IsA("GuiObject") and typeof(value) == "UDim2" then
			inst.Size = value
		elseif key == "Position" and inst:IsA("GuiObject") and typeof(value) == "UDim2" then
			inst.Position = value
		elseif key == "BackgroundTransparency" and inst:IsA("GuiObject") then
			inst.BackgroundTransparency = tonumber(value) or inst.BackgroundTransparency
		elseif key == "BackgroundColor3" and inst:IsA("GuiObject") and typeof(value) == "Color3" then
			inst.BackgroundColor3 = value
		elseif key == "TextColor3" and (inst:IsA("TextLabel") or inst:IsA("TextButton") or inst:IsA("TextBox")) and typeof(value) == "Color3" then
			inst.TextColor3 = value
		elseif key == "TextSize" and (inst:IsA("TextLabel") or inst:IsA("TextButton") or inst:IsA("TextBox")) then
			inst.TextSize = math.max(1, math.min(100, tonumber(value) or inst.TextSize))
		elseif key == "TextTransparency" and (inst:IsA("TextLabel") or inst:IsA("TextButton") or inst:IsA("TextBox")) then
			inst.TextTransparency = tonumber(value) or inst.TextTransparency
		elseif key == "ImageTransparency" and (inst:IsA("ImageLabel") or inst:IsA("ImageButton")) then
			inst.ImageTransparency = tonumber(value) or inst.ImageTransparency
		elseif key == "AnchorPoint" and inst:IsA("GuiObject") and typeof(value) == "Vector2" then
			inst.AnchorPoint = value
		elseif key == "ZIndex" and inst:IsA("GuiObject") then
			inst.ZIndex = tonumber(value) or inst.ZIndex
		elseif key == "LayoutOrder" and inst:IsA("GuiObject") then
			inst.LayoutOrder = tonumber(value) or inst.LayoutOrder
		elseif key == "Padding" and inst:IsA("UIListLayout") and typeof(value) == "UDim" then
			inst.Padding = value
		elseif key == "Padding" and inst:IsA("UIPadding") and typeof(value) == "UDim" then
			inst.PaddingTop = value
			inst.PaddingBottom = value
			inst.PaddingLeft = value
			inst.PaddingRight = value
		elseif key == "CornerRadius" and inst:IsA("UICorner") and typeof(value) == "UDim" then
			inst.CornerRadius = value
		elseif key == "Thickness" and inst:IsA("UIStroke") then
			inst.Thickness = tonumber(value) or inst.Thickness
		elseif SAFE_UI_RESTORE_PROPERTIES[key] then
			inst[key] = value
		elseif key == "Loop" and inst:IsA("KeyframeSequence") then
			inst.Loop = value == true
		elseif key == "Priority" and inst:IsA("KeyframeSequence") then
			local enumName = tostring(value):match("%.([%w_]+)$") or tostring(value)
			inst.Priority = Enum.AnimationPriority[enumName] or Enum.AnimationPriority.Action
		elseif key == "Time" and inst:IsA("Keyframe") then
			inst.Time = tonumber(value) or 0
		elseif key == "Weight" and inst:IsA("Pose") then
			inst.Weight = tonumber(value) or 1
		elseif key == "CFrame" and inst:IsA("Pose") and typeof(value) == "CFrame" then
			inst.CFrame = value
		elseif key == "EasingStyle" and inst:IsA("Pose") then
			local enumName = tostring(value):match("%.([%w_]+)$") or tostring(value)
			inst.EasingStyle = Enum.PoseEasingStyle[enumName] or Enum.PoseEasingStyle.Cubic
		elseif key == "EasingDirection" and inst:IsA("Pose") then
			local enumName = tostring(value):match("%.([%w_]+)$") or tostring(value)
			inst.EasingDirection = Enum.PoseEasingDirection[enumName] or Enum.PoseEasingDirection.InOut
		elseif key == "Name" then
			inst.Name = tostring(value)
		else
			error("Unsupported or unsafe property: " .. tostring(key))
		end
	end)
	return ok, ok and nil or tostring(err)
end

-- Asset-bearing properties stay out of safeSetProperty so general agent
-- property writes cannot smuggle an arbitrary Roblox asset reference. Only the
-- server-owned apply_asset_reference command reaches this exact class/property
-- allowlist.
ASSET_REFERENCE_TARGETS = {
	ImageLabel = { Image = true },
	ImageButton = { Image = true },
	Decal = { Texture = true },
	Texture = { Texture = true },
	MeshPart = { MeshId = true, TextureID = true },
	SpecialMesh = { MeshId = true, TextureId = true },
	Sound = { SoundId = true },
	Animation = { AnimationId = true },
}

local function assetReferencePropertyAllowed(inst, key, expectedClassName)
	if not inst or inst.ClassName ~= tostring(expectedClassName or "") then
		return false
	end
	local properties = ASSET_REFERENCE_TARGETS[inst.ClassName]
	return properties ~= nil and properties[tostring(key or "")] == true
end

safeSetAssetReference = function(inst, key, value, expectedClassName)
	local property = tostring(key or "")
	local reference = tostring(value or "")
	if not assetReferencePropertyAllowed(inst, property, expectedClassName) then
		return false, "Unsupported asset reference target: " .. tostring(expectedClassName) .. "." .. property
	end
	if reference:match("^rbxassetid://[1-9]%d*$") == nil then
		return false, "Invalid Roblox asset reference"
	end
	local ok, err = pcall(function()
		inst[property] = reference
	end)
	return ok, ok and nil or tostring(err)
end

-- Snapshot restore may write the empty pre-existing value as well as a
-- canonical Roblox asset reference. It reports whether the property belongs to
-- this narrow asset-reference boundary so callers can fall back safely.
safeRestoreAssetReference = function(inst, key, value)
	local property = tostring(key or "")
	if not assetReferencePropertyAllowed(inst, property, inst and inst.ClassName or "") then
		return false, nil, nil
	end
	local reference = tostring(value or "")
	if reference ~= "" and reference:match("^rbxassetid://[1-9]%d*$") == nil then
		return true, false, "Invalid snapshot asset reference"
	end
	local ok, err = pcall(function()
		inst[property] = reference
	end)
	return true, ok, ok and nil or tostring(err)
end

readScriptSource = function(inst)
	if not inst or not SCRIPT_CLASSES[inst.ClassName] then
		return false, "", {
			code = "not_script",
			className = inst and tostring(inst.ClassName) or "",
		}
	end
	local editorError = nil
	if Services.ScriptEditorService and Services.ScriptEditorService.GetEditorSource then
		local ok, source = pcall(function()
			return Services.ScriptEditorService:GetEditorSource(inst)
		end)
		if ok and type(source) == "string" then
			return true, source, { method = "ScriptEditorService.GetEditorSource" }
		end
		editorError = ok and ("unexpected source type: " .. type(source))
			or string.sub(tostring(source or "unknown error"), 1, 240)
	else
		editorError = "ScriptEditorService.GetEditorSource unavailable"
	end
	local ok, source = pcall(function()
		return inst.Source
	end)
	if ok and type(source) == "string" then
		return true, source, {
			method = "Instance.Source",
			editorError = editorError,
		}
	end
	return false, "", {
		code = "source_unreadable",
		method = "ScriptEditorService.GetEditorSource+Instance.Source",
		editorError = editorError,
		propertyError = ok and ("unexpected source type: " .. type(source))
			or string.sub(tostring(source or "unknown error"), 1, 240),
	}
end

writeScriptSource = function(inst, source)
	if not inst or not SCRIPT_CLASSES[inst.ClassName] then
		return false, "Not a script instance"
	end
	local nextSource = tostring(source or "")
	if Services.ScriptEditorService and Services.ScriptEditorService.UpdateSourceAsync then
		local ok, err = pcall(function()
			Services.ScriptEditorService:UpdateSourceAsync(inst, function()
				return nextSource
			end)
		end)
		if ok then
			return true
		end
	end
	local ok, err = pcall(function()
		inst.Source = nextSource
	end)
	return ok, ok and nil or tostring(err)
end
end
-- END src/studio/path.lua

-- BEGIN src/studio/snapshot.lua
local snapshotInstance, appendSnapshotTree, appendMissingPathSnapshots, beginRecording, finishRecording, restoreSnapshots, rollbackMutation, snapshotStateHash, createOrReplaceInstance
do
-- Cheap fingerprint of an instance's mutable state, used to tell whether a human
-- edited an instance after the agent wrote it. Scripts hash their source; other
-- instances hash curated properties + attributes + tags.
snapshotStateHash = function(inst)
	if not inst then
		return nil
	end
	if SCRIPT_CLASSES[inst.ClassName] then
		return scriptHash(inst)
	end
	-- Managed UI roots need a whole-tree fingerprint so undo/restore keeps a
	-- creator's node additions, removals, property edits, and source edits made
	-- after Nexus applied the artifact. UiArtifact is initialized before any
	-- command can execute, even though snapshot helpers are bundled earlier.
	if inst:IsA("ScreenGui") and type(UiArtifact) == "table" and type(UiArtifact.treeHash) == "function" then
		local treeOk, treeHash = pcall(UiArtifact.treeHash, inst)
		if treeOk then
			return treeHash
		end
	end
	local ok, hashValue = pcall(propertyHash, inst)
	return ok and hashValue or nil
end

local function recordStudioSnapshotLocally(snap)
	if type(localSnapshots) == "table" then
		table.insert(localSnapshots, snap)
		if type(updateSnapshotLabel) == "function" then
			updateSnapshotLabel()
		end
	end
end

snapshotInstance = function(path, deferLocalRecord)
	local inst = resolvePath(path)
	if not inst then
		local parts = splitPath(path)
		local parentPath = ""
		if #parts > 1 then
			parentPath = table.concat(parts, "/", 1, #parts - 1)
		end
		local missingSnap = {
			id = Services.HttpService:GenerateGUID(false),
			path = path,
			parentPath = parentPath,
			name = parts[#parts] or "",
			className = "",
			existed = false,
			properties = {},
		}
		if not deferLocalRecord then
			recordStudioSnapshotLocally(missingSnap)
		end
		return missingSnap
	end

	local snap = {
		id = Services.HttpService:GenerateGUID(false),
		path = fullPath(inst),
		parentPath = inst.Parent and fullPath(inst.Parent) or "",
		name = inst.Name,
		className = inst.ClassName,
		existed = true,
		properties = propertiesOf(inst),
		attributes = attributesOf(inst),
		tags = Services.CollectionService:GetTags(inst),
	}
	snap.properties.ClassName = nil

	if SCRIPT_CLASSES[inst.ClassName] then
		local ok, source = readScriptSource(inst)
		if not ok then
			error("Could not snapshot script source at " .. tostring(snap.path) .. "; mutation was not attempted")
		end
		snap.source = source
		-- Hash exactly the bytes captured in the snapshot. A second source read
		-- could race an editor update and make the snapshot unverifiable.
		snap.preHash = stableHash(source)
	else
		snap.preHash = snapshotStateHash(inst)
	end

	-- Pre-edit fingerprint: the state the instance had before the agent touched
	-- it. `postHash` (the state right after the agent's write) is stamped later
	-- by the command executor so restore can detect human edits made since.
	if not deferLocalRecord then
		recordStudioSnapshotLocally(snap)
	end
	return snap
end

appendSnapshotTree = function(inst, snapshots)
	if not inst then
		return
	end

	-- Capture the complete tree before publishing any of its snapshots. If one
	-- descendant script cannot be read, callers fail before mutation and the
	-- manual recovery list is not polluted with a partial tree.
	local pending = {}
	local function captureTree(current)
		for _, child in ipairs(current:GetChildren()) do
			captureTree(child)
		end
		table.insert(pending, snapshotInstance(fullPath(current), true))
	end
	captureTree(inst)
	for _, snap in ipairs(pending) do
		table.insert(snapshots, snap)
		recordStudioSnapshotLocally(snap)
	end
end

-- Snapshot every currently-missing segment before ensureParent can create it.
-- Restores run in reverse order, so a failed mutation removes the leaf first
-- and then any empty parent folders that were created for the command.
appendMissingPathSnapshots = function(path, snapshots, seenPaths)
	snapshots = snapshots or {}
	seenPaths = seenPaths or {}
	local parts = splitPath(path)
	local rootInst, startIndex = rootFromParts(parts)
	if not rootInst or #parts < startIndex then
		return snapshots
	end
	for index = startIndex, #parts do
		local segmentPath = table.concat(parts, "/", 1, index)
		if not seenPaths[segmentPath] and not resolvePath(segmentPath) then
			seenPaths[segmentPath] = true
			table.insert(snapshots, snapshotInstance(segmentPath))
		end
	end
	return snapshots
end

beginRecording = function(label)
	local ok, recording = pcall(function()
		return Services.ChangeHistoryService:TryBeginRecording(label)
	end)
	if ok then
		return recording
	end
	return nil
end

finishRecording = function(recording, commit)
	if not recording then
		return
	end
	pcall(function()
		Services.ChangeHistoryService:FinishRecording(
			recording,
			commit and Enum.FinishRecordingOperation.Commit or Enum.FinishRecordingOperation.Cancel
		)
	end)
end

createOrReplaceInstance = function(path, className, properties, createParents)
	local resolvedClass = tostring(className or "")
	if resolvedClass == "" then
		error("Missing className for " .. tostring(path))
	end
	if not CREATABLE_CLASSES[resolvedClass] then
		error("Unsupported className: " .. resolvedClass)
	end
	local parent, name = ensureParent(path, createParents ~= false)
	if not parent or not name then
		error("Could not resolve parent for " .. tostring(path))
	end
	local existing = parent:FindFirstChild(name)
	if existing then
		existing:Destroy()
	end
	local inst = Instance.new(resolvedClass)
	inst.Name = name
	for key, value in pairs(properties or {}) do
		local handled, ok, err = safeRestoreAssetReference(inst, key, value)
		if not handled then
			ok, err = safeSetProperty(inst, key, value)
		end
		if not ok then
			error(err)
		end
	end
	inst.Parent = parent
	return inst
end

-- Snapshot restoration must not replace a same-class container. Replacing a
-- Folder, Model, or GUI root destroys descendants that may have been added by
-- a creator after Nexus ran, bypassing the keep-my-edits protection.
restoreSnapshots = function(payload)
	local function restoreSnapshotInstance(snap)
	local inst = resolvePath(snap.path)
	if inst and inst.ClassName ~= snap.className then
		inst:Destroy()
		inst = nil
	end
	if not inst then
		local parent, name = ensureParent(snap.path, true)
		if not parent or not name then
			error("Could not resolve restore parent for " .. tostring(snap.path))
		end
		if not CREATABLE_CLASSES[snap.className] then
			error("Unsupported restore class: " .. tostring(snap.className))
		end
		inst = Instance.new(snap.className)
		inst.Name = name
		inst.Parent = parent
	end
	for key, value in pairs(snap.properties or {}) do
		if key ~= "ClassName" then
			local handled, propertyOk, propertyErr = safeRestoreAssetReference(inst, key, value)
			if not handled then
				propertyOk, propertyErr = safeSetProperty(inst, key, value)
			end
			if not propertyOk then
				error(propertyErr)
			end
		end
	end
	local expectedAttributes = snap.attributes or {}
	for key in pairs(inst:GetAttributes()) do
		if expectedAttributes[key] == nil then
			inst:SetAttribute(key, nil)
		end
	end
	for key, value in pairs(expectedAttributes) do
		inst:SetAttribute(key, value)
	end
	local expectedTags = {}
	for _, tag in ipairs(snap.tags or {}) do
		expectedTags[tostring(tag)] = true
	end
	for _, tag in ipairs(Services.CollectionService:GetTags(inst)) do
		if not expectedTags[tag] then
			Services.CollectionService:RemoveTag(inst, tag)
		end
	end
	for tag in pairs(expectedTags) do
		if not Services.CollectionService:HasTag(inst, tag) then
			Services.CollectionService:AddTag(inst, tag)
		end
	end
	if SCRIPT_CLASSES[inst.ClassName] and snap.source ~= nil then
		local wrote, writeErr = writeScriptSource(inst, snap.source)
		if not wrote then
			error(writeErr or "Could not restore script source")
		end
	end
		return inst
	end

	local restored = 0
	local removed = 0
	-- `kept` counts instances left untouched because the user edited them after
	-- the agent's write. `force` bypasses that protection for a full revert.
	local kept = 0
	local errors = {}
	local deferredHashChecks = {}
	local force = type(payload) == "table" and payload.force == true
	local snapshots = (type(payload) == "table" and payload.snapshots) or localSnapshots
	if type(snapshots) ~= "table" then
		snapshots = {}
	end
	for i = #snapshots, 1, -1 do
		local snap = snapshots[i]
		local ok, restoreErr = pcall(function()
			if snap.existed == false then
				local current = resolvePath(snap.path)
				if current then
					-- The agent created this. If the user changed it since the agent
					-- wrote it, keep their version instead of deleting it.
					if not force and snap.postHash then
						local currentHash = snapshotStateHash(current)
						if currentHash and currentHash ~= snap.postHash then
							kept = kept + 1
							return
						end
					end
					current:Destroy()
					if resolvePath(snap.path) then
						error("Created instance still exists after rollback")
					end
					removed = removed + 1
				end
			elseif snap.path and snap.className and snap.className ~= "" then
				-- The agent overwrote/edited this. If the current state no longer
				-- matches what the agent produced (and isn't already the pre-edit
				-- state), a human edited it since -> keep their edits.
				if not force and snap.postHash then
					local current = resolvePath(snap.path)
					if not current then
						-- The instance existed immediately after Nexus wrote it but is now
						-- missing, so a creator removed or renamed it. Keep that edit.
						kept = kept + 1
						return
					end
					local currentHash = snapshotStateHash(current)
					if currentHash and currentHash ~= snap.postHash and currentHash ~= snap.preHash then
						kept = kept + 1
						return
					end
				end
				local inst = restoreSnapshotInstance(snap)
				local restoredHash = snapshotStateHash(inst)
				if snap.preHash and restoredHash ~= snap.preHash then
					if inst:IsA("ScreenGui") and type(UiArtifact) == "table" and type(UiArtifact.treeHash) == "function" then
						-- The root is restored before its descendant snapshots. Verify its
						-- complete tree after the reverse-order restore has finished.
						table.insert(deferredHashChecks, snap)
					else
						error(
							"Restored state hash does not match the pre-mutation snapshot (expected "
								.. tostring(snap.preHash)
								.. ", got "
								.. tostring(restoredHash)
								.. ")"
						)
					end
				end
				restored = restored + 1
			end
		end)
		if not ok then
			table.insert(errors, {
				snapshotId = snap and snap.id or nil,
				path = snap and snap.path or "",
				message = tostring(restoreErr),
			})
		end
	end
	for _, snap in ipairs(deferredHashChecks) do
		local current = resolvePath(snap.path)
		local restoredHash = snapshotStateHash(current)
		if not current or restoredHash ~= snap.preHash then
			table.insert(errors, {
				snapshotId = snap.id,
				path = snap.path or "",
				message = "Restored UI tree hash does not match the pre-mutation snapshot (expected "
					.. tostring(snap.preHash)
					.. ", got "
					.. tostring(restoredHash)
					.. ")",
			})
		end
	end
	local complete = #errors == 0 and kept == 0
	local verificationChecks = {}
	local snapshotIds = {}
	for _, snap in ipairs(snapshots) do
		local current = snap.path and resolvePath(snap.path) or nil
		local actualHash = current and snapshotStateHash(current) or nil
		local expectedHash = snap.existed == false and nil or snap.preHash
		local restoredToBaseline = snap.existed == false
			and current == nil
			or current ~= nil and (not expectedHash or actualHash == expectedHash)
		table.insert(verificationChecks, {
			kind = "snapshot_restore",
			path = snap.path or "",
			snapshotId = snap.id,
			existed = snap.existed ~= false,
			expectedHash = expectedHash,
			actualHash = actualHash,
			ok = restoredToBaseline,
		})
		if snap.id then
			table.insert(snapshotIds, snap.id)
		end
	end
	for _, check in ipairs(verificationChecks) do
		if not check.ok then
			complete = false
			break
		end
	end
	return {
		ok = complete,
		success = complete,
		succeeded = complete,
		complete = complete,
		code = complete and nil or "snapshot_restore_incomplete",
		error = complete and nil or "One or more Studio snapshots could not be fully restored",
		restored = restored,
		removed = removed,
		kept = kept,
		requested = #snapshots,
		errors = errors,
		verification = {
			verified = complete,
			source = "studio_readback",
			evidence = {
				checks = verificationChecks,
				snapshotIds = snapshotIds,
			},
		},
	}
end

rollbackMutation = function(snapshots, code, message, details)
	local rollback = restoreSnapshots({ snapshots = snapshots, force = true })
	local response = type(details) == "table" and details or {}
	response.ok = false
	response.success = false
	response.error = tostring(message or "Studio mutation failed")
	response.mutationCode = tostring(code or "mutation_failed")
	response.code = rollback.ok and response.mutationCode or "rollback_failed"
	response.snapshots = snapshots or {}
	response.rolledBack = rollback.ok == true
	response.rollback = rollback
	for _, snap in ipairs(snapshots or {}) do
		if snap.source ~= nil then
			response.previousSourceHash = snap.preHash or scriptHash(resolvePath(snap.path))
			response.rollback.restoredSourceHash = scriptHash(resolvePath(snap.path))
			break
		end
	end
	return response
end
end
-- END src/studio/snapshot.lua

