-- BEGIN src/commands/readTools.lua
local getInspectionRoots, inspectPlace, listChildren, inspectInstances, searchProject, searchSource, readScript, writeScript, readInstance, readProperties, getSelectionTool, computePlaceSignature, serializeFlat, ScriptContextGuard, createInstanceTool, deleteInstanceTool
do
local function serializeInstance(inst, path, depth, maxDepth, state, includeSource, sourceMaxChars, parentPath)
	state.count = state.count + 1
	local managedId = readManagedId(inst)
	local item = {
		name = inst.Name,
		className = inst.ClassName,
		path = path,
		parentPath = parentPath or "",
		managedId = managedId,
		tags = Services.CollectionService:GetTags(inst),
		attributes = attributesOf(inst),
		propertyHash = propertyHash(inst),
		children = {},
	}

	if SCRIPT_CLASSES[inst.ClassName] then
		item.isScript = true
		item.sourceHash = scriptHash(inst)
		if includeSource then
			local ok, source = readScriptSource(inst)
			if ok then
				item.source = string.sub(source, 1, sourceMaxChars or 0)
				item.sourceLength = #source
			end
		end
	elseif inst:IsA("RemoteEvent") or inst:IsA("RemoteFunction") then
		item.isRemote = true
	elseif inst:IsA("ScreenGui") then
		item.isScreenGui = true
	end
	if not state.seenPaths[path] then
		state.seenPaths[path] = true
		table.insert(state.items, {
			name = item.name,
			className = item.className,
			path = item.path,
			parentPath = item.parentPath,
			managedId = item.managedId,
			sourceHash = item.sourceHash,
			propertyHash = item.propertyHash,
			updatedAt = os.time(),
		})
	else
		state.duplicateCanonicalPaths = state.duplicateCanonicalPaths + 1
	end

	if depth >= maxDepth or state.count >= state.maxInstances then
		item.truncated = #inst:GetChildren() > 0
		return item
	end

	local children = inst:GetChildren()
	table.sort(children, function(a, b)
		if a.Name ~= b.Name then
			return a.Name < b.Name
		end
		if a.ClassName ~= b.ClassName then
			return a.ClassName < b.ClassName
		end
		return tostring(a) < tostring(b)
	end)
	for _, child in ipairs(children) do
		if state.count >= state.maxInstances then
			item.truncated = true
			break
		end
		table.insert(item.children, serializeInstance(child, path .. "/" .. child.Name, depth + 1, maxDepth, state, includeSource, sourceMaxChars, path))
	end

	return item
end

getInspectionRoots = function()
	local roots = {}
	local seen = {}
	local preferred = {
		Services.ReplicatedStorage,
		Services.ReplicatedFirst,
		Services.ServerScriptService,
		Services.ServerStorage,
		Services.StarterGui,
		Services.StarterPlayer,
		Services.StarterPack,
		Services.Workspace,
		Services.Lighting,
	}
	for _, inst in ipairs(preferred) do
		if inst and not seen[inst] then
			seen[inst] = true
			table.insert(roots, inst)
		end
	end
	for _, child in ipairs(game:GetChildren()) do
		if SERVICE_ROOTS[child.Name] and not seen[child] then
			seen[child] = true
			table.insert(roots, child)
		end
	end
	table.sort(roots, function(a, b)
		if a.Name ~= b.Name then
			return tostring(a.Name) < tostring(b.Name)
		end
		return tostring(a.ClassName) < tostring(b.ClassName)
	end)
	return roots
end

-- Cheap top-level fingerprint of the place (service child counts). Used as a
-- fast "did anything structurally change?" signal so the backend can skip a
-- full re-index when the project is unchanged.
computePlaceSignature = function()
	local parts = {}
	for _, inst in ipairs(getInspectionRoots()) do
		local ok, count = pcall(function()
			return #inst:GetChildren()
		end)
		table.insert(parts, tostring(inst.Name) .. ":" .. tostring(inst.ClassName) .. ":" .. tostring(ok and count or 0))
	end
	return stableHash(table.concat(parts, "|"))
end

inspectPlace = function(payload)
	local maxDepth = math.clamp(tonumber(payload.maxDepth) or 12, 1, 32)
	local maxInstances = math.clamp(tonumber(payload.maxInstances) or 500, 20, 10000)
	local includeSource = payload.includeSource == true
	local sourceMaxChars = math.clamp(tonumber(payload.sourceMaxChars) or 0, 0, 8000)
	local pageSize = math.clamp(tonumber(payload.pageSize) or maxInstances, 20, 1000)
	local cursor = math.max(0, tonumber(payload.cursor) or 0)
	local requestedRevision = tostring(payload.manifestRevision or "")
	-- Elapsed-time TTL (10 minutes). Prefer tick() so wall-clock jumps do not keep
	-- expired snapshots alive; fall back to os.time() when tick is unavailable.
	local MANIFEST_SNAPSHOT_TTL_SEC = 600
	local function snapshotNow()
		if typeof(tick) == "function" then
			return tick()
		end
		return os.time()
	end
	NEXUS_RBX_MANIFEST_SNAPSHOTS = NEXUS_RBX_MANIFEST_SNAPSHOTS or {}
	for revision, snapshot in pairs(NEXUS_RBX_MANIFEST_SNAPSHOTS) do
		local createdAt = snapshot.createdAtElapsed or snapshot.createdAt or 0
		if snapshotNow() - createdAt > MANIFEST_SNAPSHOT_TTL_SEC then
			NEXUS_RBX_MANIFEST_SNAPSHOTS[revision] = nil
		end
	end
	if cursor > 0 and requestedRevision == "" then
		return {
			ok = false,
			code = "manifest_revision_required",
			error = "Manifest continuation requires the revision from the first page",
			retryable = true,
		}
	end
	local snapshot = requestedRevision ~= "" and NEXUS_RBX_MANIFEST_SNAPSHOTS[requestedRevision] or nil
	if cursor > 0 and not snapshot then
		return {
			ok = false,
			code = "manifest_revision_expired",
			error = "The manifest snapshot expired; start a new scan from the first page",
			retryable = true,
		}
	end
	local supersedesRevision = nil
	if not snapshot then
		local state = {
			count = 0,
			maxInstances = maxInstances,
			items = {},
			seenPaths = {},
			duplicateCanonicalPaths = 0,
		}
		local roots = {}
		for _, inst in ipairs(getInspectionRoots()) do
			if state.count >= state.maxInstances then
				break
			end
			table.insert(roots, serializeInstance(inst, inst.Name, 1, maxDepth, state, includeSource, sourceMaxChars, ""))
		end
		-- Revision immutability: never rebuild under a previously requested revision
		-- when the snapshot is gone. Always mint a new GUID.
		if requestedRevision ~= "" then
			supersedesRevision = requestedRevision
		end
		requestedRevision = Services.HttpService:GenerateGUID(false)
		snapshot = {
			createdAt = os.time(),
			createdAtElapsed = snapshotNow(),
			items = state.items,
			roots = roots,
			scannedInstances = state.count,
			truncated = state.count >= maxInstances,
			duplicateCanonicalPaths = state.duplicateCanonicalPaths,
			placeSignature = computePlaceSignature(),
		}
		NEXUS_RBX_MANIFEST_SNAPSHOTS[requestedRevision] = snapshot
	end
	local page = {}
	for i = cursor + 1, math.min(#snapshot.items, cursor + pageSize) do
		table.insert(page, snapshot.items[i])
	end
	return {
		pluginVersion = PLUGIN_VERSION,
		protocolVersion = STUDIO_PROTOCOL_VERSION,
		revision = requestedRevision,
		supersedesRevision = supersedesRevision,
		placeName = game.Name,
		placeId = tostring(game.PlaceId),
		count = #snapshot.items,
		totalInstances = #snapshot.items,
		scannedInstances = snapshot.scannedInstances,
		truncated = snapshot.truncated,
		duplicateCanonicalPaths = snapshot.duplicateCanonicalPaths,
		items = page,
		nextCursor = (cursor + pageSize < #snapshot.items) and tostring(cursor + pageSize) or nil,
		roots = cursor == 0 and snapshot.roots or nil,
		placeSignature = snapshot.placeSignature,
	}
end

readScript = function(payload)
	local out = {}
	local maxChars = math.clamp(tonumber(payload.maxChars) or 20000, 500, 60000)
	for _, path in ipairs(payload.paths or {}) do
		local inst = resolvePath(path)
		if inst and SCRIPT_CLASSES[inst.ClassName] then
			local ok, source = readScriptSource(inst)
			table.insert(out, {
				path = fullPath(inst),
				className = inst.ClassName,
				name = inst.Name,
				source = ok and string.sub(source, 1, maxChars) or "",
				sourceLength = ok and #source or 0,
				sourceHash = ok and stableHash(source) or nil,
				truncated = ok and #source > maxChars or false,
			})
		else
			table.insert(out, { path = path, error = "Script not found" })
		end
	end
	return { scripts = out }
end

-- Last-line execution-context guard. The backend performs the same checks and
-- may disclose a safe adjustment before a command is queued; the plugin never
-- guesses or adjusts. It rejects the full mutation before snapshots or writes.
ScriptContextGuard = {}

function ScriptContextGuard.resolveScriptClassName(value)
	local className = tostring(value or "")
	return SCRIPT_CLASSES[className] and className or ""
end

function ScriptContextGuard.stripCommentsAndStrings(source)
	local input = tostring(source or "")
	local output = {}
	local length = #input

	local function blankSegment(segment)
		return (segment:gsub("[^\r\n]", " "))
	end

	local function longBracketAt(index)
		if input:sub(index, index) ~= "[" then
			return nil, nil
		end
		local cursor = index + 1
		while input:sub(cursor, cursor) == "=" do
			cursor = cursor + 1
		end
		if input:sub(cursor, cursor) ~= "[" then
			return nil, nil
		end
		local equals = cursor - index - 1
		return cursor + 1, "]" .. string.rep("=", equals) .. "]"
	end

	local index = 1
	while index <= length do
		local current = input:sub(index, index)
		local nextChar = input:sub(index + 1, index + 1)
		if current == "-" and nextChar == "-" then
			local contentStart, closing = longBracketAt(index + 2)
			local finish
			if contentStart then
				local closeStart = string.find(input, closing, contentStart, true)
				finish = closeStart and (closeStart + #closing - 1) or length
			else
				local newline = string.find(input, "\n", index + 2, true)
				finish = newline and (newline - 1) or length
			end
			table.insert(output, blankSegment(input:sub(index, finish)))
			index = finish + 1
		elseif current == "'" or current == '"' then
			local quote = current
			local cursor = index + 1
			local prefix = input:sub(math.max(1, index - 120), index - 1)
			local isGetServiceArgument = prefix:match("GetService%s*%(%s*$") ~= nil
			while cursor <= length do
				local value = input:sub(cursor, cursor)
				if value == "\\" then
					cursor = cursor + 2
				elseif value == quote then
					cursor = cursor + 1
					break
				else
					cursor = cursor + 1
				end
			end
			local segment = input:sub(index, cursor - 1)
			table.insert(output, isGetServiceArgument and segment or blankSegment(segment))
			index = cursor
		elseif current == "[" then
			local contentStart, closing = longBracketAt(index)
			if contentStart then
				local closeStart = string.find(input, closing, contentStart, true)
				local finish = closeStart and (closeStart + #closing - 1) or length
				table.insert(output, blankSegment(input:sub(index, finish)))
				index = finish + 1
			else
				table.insert(output, current)
				index = index + 1
			end
		else
			table.insert(output, current)
			index = index + 1
		end
	end
	return table.concat(output)
end

function ScriptContextGuard.placementContext(path)
	local normalized = tostring(path or "")
		:gsub("\\", "/")
		:gsub("^game[./]", "")
		:gsub("/+", "/")
		:gsub("^/", "")
		:gsub("/$", "")
	local parts = splitPath(normalized)
	local root = parts[1] or ""
	local second = parts[2] or ""
	if root == "StarterPlayer" and (second == "StarterPlayerScripts" or second == "StarterCharacterScripts") then
		return "client"
	end
	if root == "StarterGui" or root == "StarterPack" or root == "ReplicatedFirst"
		or root == "StarterPlayerScripts" or root == "StarterCharacterScripts" then
		return "client"
	end
	if root == "ServerScriptService" or root == "Workspace" then
		return "server"
	end
	if root == "ServerStorage" then
		return "non_executing"
	end
	if root == "ReplicatedStorage" then
		return "shared"
	end
	return "unknown"
end

function ScriptContextGuard.validate(descriptor)
	local source = ScriptContextGuard.stripCommentsAndStrings(descriptor.source or descriptor.content or "")
	local className = tostring(descriptor.className or "")
	local path = tostring(descriptor.path or descriptor.placement or "")
	local placement = ScriptContextGuard.placementContext(path)
	local findings = {}
	local clientFeatures = {
		{ name = "Players.LocalPlayer", token = "LocalPlayer" },
		{ name = "UserInputService", token = "UserInputService" },
		{ name = "workspace.CurrentCamera", token = "CurrentCamera" },
		{ name = "RunService.RenderStepped", token = "RenderStepped" },
		{ name = "RunService:BindToRenderStep", token = "BindToRenderStep" },
		{ name = "StarterGui", token = "StarterGui" },
	}
	local serverFeatures = {
		{ name = "DataStoreService", token = "DataStoreService" },
		{ name = "MemoryStoreService", token = "MemoryStoreService" },
		{ name = "MessagingService", token = "MessagingService" },
		{ name = "ServerStorage", token = "ServerStorage" },
		{ name = "ServerScriptService", token = "ServerScriptService" },
	}
	local clientMatch = nil
	local serverMatch = nil
	local function findIdentifier(token)
		local searchFrom = 1
		while true do
			local startIndex, endIndex = string.find(source, token, searchFrom, true)
			if not startIndex then
				return nil
			end
			local before = startIndex > 1 and source:sub(startIndex - 1, startIndex - 1) or ""
			local after = endIndex < #source and source:sub(endIndex + 1, endIndex + 1) or ""
			if not before:match("[%w_]") and not after:match("[%w_]") then
				return startIndex
			end
			searchFrom = endIndex + 1
		end
	end
	for _, feature in ipairs(clientFeatures) do
		if findIdentifier(feature.token) then
			clientMatch = feature
			break
		end
	end
	for _, feature in ipairs(serverFeatures) do
		if findIdentifier(feature.token) then
			serverMatch = feature
			break
		end
	end

	local function sourceLine(token)
		local startIndex = token and findIdentifier(token) or nil
		if not startIndex then
			return nil
		end
		local prefix = source:sub(1, startIndex - 1)
		local _, count = prefix:gsub("\n", "\n")
		return count + 1
	end

	local function addFinding(code, explanation, token)
		local finding = {
			ruleCode = code,
			code = code,
			severity = "blocking",
			explanation = explanation,
			message = explanation,
			path = path ~= "" and path or "Unknown",
		}
		local line = sourceLine(token)
		if line then
			finding.line = line
		end
		table.insert(findings, finding)
	end

	local requiredContext = "unknown"
	if clientMatch and serverMatch then
		requiredContext = "mixed"
	elseif className == "ModuleScript" then
		requiredContext = "module"
	elseif clientMatch then
		requiredContext = "client"
	elseif serverMatch then
		requiredContext = "server"
	elseif placement == "client" or placement == "server" then
		requiredContext = placement
	elseif className == "LocalScript" then
		requiredContext = "client"
	elseif className == "Script" then
		requiredContext = "server"
	end

	if not SCRIPT_CLASSES[className] then
		addFinding("SCRIPT_CLASS_REQUIRED", "Every Studio script must declare Script, LocalScript, or ModuleScript explicitly.")
	end
	if placement == "unknown" then
		addFinding("SCRIPT_LOCATION_MISMATCH", "Every Studio script must declare a supported, explicit Studio location.")
	end
	if source:find("%.%s*Source%s*=") then
		addFinding(
			"RUNTIME_SCRIPT_SOURCE_WRITE",
			"Roblox game scripts cannot assign Script.Source at runtime. Create or update the target Script or LocalScript in Studio before play begins.",
			"Source"
		)
	end
	if requiredContext == "mixed" then
		addFinding(
			"MIXED_RUNTIME_CONTEXT",
			"This source combines client-only and server-only behavior. Split it into client and server scripts connected by remotes.",
			clientMatch and clientMatch.token
		)
	end
	if className ~= "ModuleScript" then
		if clientMatch and className == "Script" then
			addFinding("CLIENT_API_ON_SERVER", clientMatch.name .. " requires client execution, but this is a server Script.", clientMatch.token)
		end
		if serverMatch and className == "LocalScript" then
			addFinding("SERVER_API_ON_CLIENT", serverMatch.name .. " requires trusted server execution, but this is a LocalScript.", serverMatch.token)
		end
		if className == "LocalScript" and placement ~= "client" then
			addFinding("SCRIPT_LOCATION_MISMATCH", "LocalScript must be placed in a supported client container.")
		end
		if className == "Script" and placement ~= "server" and placement ~= "non_executing" then
			addFinding("SCRIPT_LOCATION_MISMATCH", "Script must be placed in ServerScriptService or Workspace.")
		end
		if placement == "non_executing" then
			addFinding("SCRIPT_LOCATION_MISMATCH", "Runnable scripts do not execute from ServerStorage.")
		end
	end

	return {
		ok = #findings == 0,
		status = #findings == 0 and "valid" or "blocked",
		requiredContext = requiredContext,
		findings = findings,
		adjustments = {},
	}
end

function ScriptContextGuard.failure(validation)
	return {
		ok = false,
		success = false,
		code = "SCRIPT_CONTEXT_MISMATCH",
		error = validation.findings[1] and validation.findings[1].message or "Script execution context is invalid",
		status = validation.status,
		requiredContext = validation.requiredContext,
		findings = validation.findings,
		adjustments = validation.adjustments,
		validation = validation,
		retryable = false,
	}
end

writeScript = function(payload)
	local path = payload.path
	local className = payload.className
	if type(className) ~= "string" or className == "" then
		return ScriptContextGuard.failure(ScriptContextGuard.validate({
			className = className,
			path = path,
			source = payload.source,
		}))
	end
	if not SCRIPT_CLASSES[className] then
		return ScriptContextGuard.failure(ScriptContextGuard.validate({
			className = className,
			path = path,
			source = payload.source,
		}))
	end
	local snapshots = {}
	local existing = resolvePath(path)
	if existing and not SCRIPT_CLASSES[existing.ClassName] then
		return {
			ok = false,
			code = "class_conflict",
			error = "Refusing to replace non-script instance hierarchy with a script",
			path = fullPath(existing),
			currentClassName = existing.ClassName,
			expectedClassName = className,
			retryable = false,
		}
	end
	if existing and existing.ClassName ~= className then
		local hasConversionAuthorization = payload.allowClassChange == true
			and tostring(payload.inspectedClassName or "") == existing.ClassName
			and tostring(payload.expectedSourceHash or "") ~= ""
		if not hasConversionAuthorization then
			return ScriptContextGuard.failure({
				ok = false,
				status = "blocked",
				requiredContext = "unknown",
				findings = {
					{
						ruleCode = "SCRIPT_LOCATION_MISMATCH",
						code = "SCRIPT_LOCATION_MISMATCH",
						severity = "blocking",
						message = "Changing an existing script class requires allowClassChange, the inspected class, and the inspected source hash.",
					},
				},
				adjustments = {},
			})
		end
	end
	if existing and not payload.allowOverwrite and payload.createOnly == true then
		return {
			ok = false,
			code = "already_exists",
			error = "Script already exists",
			path = fullPath(existing),
			retryable = false,
		}
	end
	if existing then
		local hashOk, hashResult = verifyExpectedScriptHash(existing, payload.expectedSourceHash, fullPath(existing))
		if not hashOk then
			return hashResult
		end
	end
	local contextValidation = ScriptContextGuard.validate({
		className = className,
		path = existing and fullPath(existing) or path,
		source = payload.source,
	})
	if not contextValidation.ok then
		return ScriptContextGuard.failure(contextValidation)
	end

	if existing then
		appendSnapshotTree(existing, snapshots)
	else
		appendMissingPathSnapshots(path, snapshots, {})
	end
	local mutationOk, mutationResult = pcall(function()
		local inst = existing
		if not inst then
			local parent, name = ensureParent(path, payload.createParents ~= false)
			if not parent or not name then
				error("Could not resolve parent for " .. tostring(path))
			end
			inst = Instance.new(className)
			inst.Name = name
			inst.Parent = parent
		elseif inst.ClassName ~= className and payload.allowClassChange == true then
			local previous = inst
			local parent = previous.Parent
			local name = previous.Name
			local attributes = previous:GetAttributes()
			previous:Destroy()
			inst = Instance.new(className)
			inst.Name = name
			for attributeName, attributeValue in pairs(attributes) do
				inst:SetAttribute(attributeName, attributeValue)
			end
			inst.Parent = parent
		end
		ensureManagedId(inst)
		local wrote, writeErr = writeScriptSource(inst, payload.source or "")
		if not wrote then
			error(writeErr or "Could not write script source")
		end
		return inst
	end)
	if not mutationOk then
		return rollbackMutation(snapshots, "write_failed", mutationResult, { path = tostring(path) })
	end
	local inst = mutationResult
	return {
		path = fullPath(inst),
		className = inst.ClassName,
		sourceLength = #(payload.source or ""),
		sourceHash = scriptHash(inst),
		snapshots = snapshots,
	}
end

createInstanceTool = function(payload)
	local path = payload.path
	local className = payload.className or "Folder"
	local snapshots = {}
	local existing = resolvePath(path)
	if existing and SCRIPT_CLASSES[existing.ClassName] then
		local hashOk, hashResult = verifyExpectedScriptHash(existing, payload.expectedSourceHash, fullPath(existing))
		if not hashOk then
			return hashResult
		end
	end

	if existing then
		appendSnapshotTree(existing, snapshots)
	else
		appendMissingPathSnapshots(path, snapshots, {})
	end
	local mutationOk, mutationResult = pcall(function()
		local inst = createOrReplaceInstance(path, className, payload.properties or {}, payload.createParents ~= false)
		for key, value in pairs(payload.attributes or {}) do
			inst:SetAttribute(tostring(key), value)
		end
		for _, tag in ipairs(payload.tags or {}) do
			Services.CollectionService:AddTag(inst, tostring(tag))
		end
		ensureManagedId(inst)
		return inst
	end)
	if not mutationOk then
		return rollbackMutation(snapshots, "create_instance_failed", mutationResult, { path = tostring(path) })
	end
	local inst = mutationResult
	return {
		path = fullPath(inst),
		className = inst.ClassName,
		properties = propertiesOf(inst),
		attributes = attributesOf(inst),
		tags = Services.CollectionService:GetTags(inst),
		snapshots = snapshots,
	}
end

deleteInstanceTool = function(payload)
	local path = payload.path
	local inst = resolvePath(path)
	local snapshots = {}
	if inst then
		local hashOk, hashResult = verifyExpectedScriptHash(inst, payload.expectedSourceHash, fullPath(inst))
		if not hashOk then
			return hashResult
		end
		appendSnapshotTree(inst, snapshots)
	else
		table.insert(snapshots, snapshotInstance(path))
	end
	if inst then
		local mutationOk, mutationErr = pcall(function()
			inst:Destroy()
		end)
		if not mutationOk then
			return rollbackMutation(snapshots, "delete_instance_failed", mutationErr, { path = tostring(path) })
		end
	end
	return { path = path, deleted = inst ~= nil, snapshots = snapshots }
end

serializeFlat = function(inst, includeProperties, includeAttributes, includeTags)
	local row = {
		name = inst.Name,
		className = inst.ClassName,
		path = fullPath(inst),
		parentPath = inst.Parent and fullPath(inst.Parent) or "",
		managedId = readManagedId(inst),
		propertyHash = propertyHash(inst),
	}
	if includeProperties ~= false then
		row.properties = propertiesOf(inst)
	end
	if includeAttributes ~= false then
		row.attributes = attributesOf(inst)
	end
	if includeTags ~= false then
		row.tags = Services.CollectionService:GetTags(inst)
	end
	if SCRIPT_CLASSES[inst.ClassName] then
		row.isScript = true
		row.sourceHash = scriptHash(inst)
	end
	return row
end

listChildren = function(payload)
	local inst = resolvePath(payload.path)
	if not inst then
		return { ok = false, error = "Instance not found", path = payload.path, children = {} }
	end
	local pageSize = math.clamp(tonumber(payload.pageSize) or 250, 20, 1000)
	local cursor = math.max(0, tonumber(payload.cursor) or 0)
	local children = inst:GetChildren()
	table.sort(children, function(a, b)
		return a.Name < b.Name
	end)
	local out = {}
	for i = cursor + 1, math.min(#children, cursor + pageSize) do
		table.insert(out, serializeFlat(children[i], payload.includeProperties == true, true, true))
	end
	return {
		path = fullPath(inst),
		total = #children,
		children = out,
		nextCursor = (cursor + pageSize < #children) and tostring(cursor + pageSize) or nil,
	}
end

inspectInstances = function(payload)
	local paths = payload.paths or {}
	local out = {}
	for _, path in ipairs(paths) do
		local inst = resolvePath(path)
		if inst then
			local row = serializeFlat(inst, payload.includeProperties ~= false, payload.includeAttributes ~= false, payload.includeTags ~= false)
			if payload.includeChildren == true then
				row.children = {}
				for _, child in ipairs(inst:GetChildren()) do
					table.insert(row.children, serializeFlat(child, false, true, true))
				end
			end
			table.insert(out, row)
		else
			table.insert(out, { path = path, error = "Instance not found" })
		end
	end
	return { instances = out }
end

searchProject = function(payload)
	local query = tostring(payload.query or "")
	local maxResults = math.clamp(tonumber(payload.maxResults) or 100, 1, 500)
	local caseSensitive = payload.caseSensitive == true
	local needle = caseSensitive and query or string.lower(query)
	local classes = {}
	for _, className in ipairs(payload.classes or {}) do
		classes[tostring(className)] = true
	end
	local results = {}
	for _, inst in ipairs(game:GetDescendants()) do
		if #results >= maxResults then
			break
		end
		if next(classes) == nil or classes[inst.ClassName] then
			local hay = fullPath(inst) .. " " .. inst.Name .. " " .. inst.ClassName
			if not caseSensitive then
				hay = string.lower(hay)
			end
			if query == "" or string.find(hay, needle, 1, true) then
				table.insert(results, serializeFlat(inst, false, true, true))
			end
		end
	end
	return { query = query, results = results, truncated = #results >= maxResults }
end

searchSource = function(payload)
	local query = tostring(payload.query or "")
	local maxResults = math.clamp(tonumber(payload.maxResults) or 100, 1, 500)
	local maxContext = math.clamp(tonumber(payload.maxContextChars) or 300, 0, 2000)
	local caseSensitive = payload.caseSensitive == true
	local needle = caseSensitive and query or string.lower(query)
	local allowedPaths = {}
	for _, path in ipairs(payload.paths or {}) do
		allowedPaths[tostring(path)] = true
	end
	local results = {}
	for _, inst in ipairs(game:GetDescendants()) do
		if #results >= maxResults then
			break
		end
		if SCRIPT_CLASSES[inst.ClassName] then
			local path = fullPath(inst)
			if next(allowedPaths) == nil or allowedPaths[path] then
				local ok, source = readScriptSource(inst)
				if ok then
					local hay = caseSensitive and source or string.lower(source)
					local startIndex, endIndex = string.find(hay, needle, 1, true)
					if query == "" or startIndex then
						local contextStart = math.max(1, (startIndex or 1) - maxContext)
						local contextEnd = math.min(#source, (endIndex or 1) + maxContext)
						table.insert(results, {
							path = path,
							className = inst.ClassName,
							sourceHash = stableHash(source),
							matchStart = startIndex,
							matchEnd = endIndex,
							context = string.sub(source, contextStart, contextEnd),
						})
					end
				end
			end
		end
	end
	return { query = query, results = results, truncated = #results >= maxResults }
end

readInstance = function(payload)
	local paths = payload.paths or {}
	if payload.path and payload.path ~= "" then
		paths = { payload.path }
	end
	local out = {}
	for _, path in ipairs(paths) do
		local inst = resolvePath(path)
		if inst then
			table.insert(out, serializeFlat(inst, true, payload.includeAttributes ~= false, payload.includeTags ~= false))
		else
			table.insert(out, { path = path, error = "Instance not found" })
		end
	end
	return { instances = out }
end

readProperties = function(payload)
	return readInstance(payload)
end

getSelectionTool = function()
	local out = {}
	for _, inst in ipairs(Services.Selection:Get()) do
		table.insert(out, serializeFlat(inst, false, true, true))
	end
	return { selection = out }
end
end
-- END src/commands/readTools.lua

-- BEGIN src/studio/targetIntegrity.lua
local getStudioConnectorId, refreshStudioPlaceGeneration, currentStudioTargetAttestation, recordStudioFreshness, updateStudioServerTarget, clearStudioServerTarget, getStudioTargetReadiness, validateCommandStudioTarget, publishStudioConnectionDiagnostics
do
-- Immutable Studio target identity and transport-freshness tracking.
-- Connector identity is stable across sessions. Target generation advances
-- for a different place identity and resumes the backend's authenticated
-- high-water mark after a plugin/runtime restart.

local studioFreshness, serverTarget = {
	heartbeat = { ok = false },
	poll = { ok = false },
	attestation = { ok = false },
}, {}
local TargetPrivate = {}

function TargetPrivate.stringValue(value)
	if value == nil then return nil end
	local result = tostring(value)
	return result ~= "" and result or nil
end

getStudioConnectorId = function()
	local connectorId = TargetPrivate.stringValue(plugin:GetSetting("nexusrbxStudioConnectorId"))
	if connectorId then return connectorId end
	connectorId = Services.HttpService:GenerateGUID(false)
	plugin:SetSetting("nexusrbxStudioConnectorId", connectorId)
	return connectorId
end

function TargetPrivate.currentPlaceKey()
	local placeId, universeId = tostring(game.PlaceId), tostring(game.GameId)
	local unpublished = placeId == "0" and universeId == "0" and (":" .. tostring(game.Name)) or ""
	return universeId .. ":" .. placeId .. unpublished
end

refreshStudioPlaceGeneration = function()
	local key = TargetPrivate.currentPlaceKey()
	local previous = TargetPrivate.stringValue(plugin:GetSetting("nexusrbxStudioPlaceIdentity"))
	local generation = math.max(0, tonumber(plugin:GetSetting("nexusrbxStudioTargetGeneration")) or 0)
	if previous ~= key then
		generation = generation + 1
		plugin:SetSetting("nexusrbxStudioPlaceIdentity", key)
		plugin:SetSetting("nexusrbxStudioTargetGeneration", generation)
	end
	return generation, previous ~= nil and previous ~= key
end

function TargetPrivate.targetSummary(attestation)
	local expectedPlaceId = TargetPrivate.stringValue(serverTarget.expectedPlaceId or serverTarget.placeId)
	local expectedUniverseId = TargetPrivate.stringValue(serverTarget.expectedUniverseId or serverTarget.universeId)
	local expectedPlaceSignature = TargetPrivate.stringValue(serverTarget.expectedPlaceSignature or serverTarget.placeSignature)
	local expectedGeneration = tonumber(serverTarget.targetGeneration)
	local mismatch = (expectedPlaceId and expectedPlaceId ~= attestation.placeId)
		or (expectedUniverseId and expectedUniverseId ~= attestation.universeId)
		or (expectedPlaceSignature and expectedPlaceSignature ~= attestation.placeSignature)
		or (expectedGeneration and expectedGeneration ~= tonumber(attestation.targetGeneration))
	local resumeError = TargetPrivate.stringValue(serverTarget.generationResumeError)
	local targetId = TargetPrivate.stringValue(serverTarget.targetId)
	local targetBound = expectedPlaceId ~= nil and expectedUniverseId ~= nil
		and expectedPlaceSignature ~= nil and targetId ~= nil
	return {
		targetId = targetId,
		placeName = attestation.placeName,
		placeId = attestation.placeId,
		universeId = attestation.universeId,
		targetGeneration = attestation.targetGeneration,
		targetBound = targetBound,
		targetReady = targetBound and mismatch ~= true and resumeError == nil,
		detail = resumeError and ("Studio target resume was rejected: " .. resumeError)
			or (not targetBound and "Studio target handshake is incomplete"
				or (mismatch and "Website target does not match this open place" or nil)),
	}
end

publishStudioConnectionDiagnostics = function(attestation)
	if type(setConnectionDiagnostics) ~= "function" then return end
	attestation = attestation or currentStudioTargetAttestation(false)
	setConnectionDiagnostics({
		target = TargetPrivate.targetSummary(attestation),
		freshness = studioFreshness,
	})
end

currentStudioTargetAttestation = function(recordFreshness)
	local generation, changed = refreshStudioPlaceGeneration()
	local signatureOk, signature = pcall(computePlaceSignature)
	local attestation = {
		connectorId = getStudioConnectorId(),
		sessionId = TargetPrivate.stringValue(plugin:GetSetting("nexusrbxStudioSessionId")),
		targetId = TargetPrivate.stringValue(serverTarget.targetId),
		placeName = tostring(game.Name),
		placeId = tostring(game.PlaceId),
		universeId = tostring(game.GameId),
		placeSignature = signatureOk and TargetPrivate.stringValue(signature) or nil,
		targetGeneration = generation,
		placeChanged = changed == true,
		attestedAt = os.time(),
	}
	if recordFreshness ~= false then
		studioFreshness.attestation = {
			ok = signatureOk,
			at = os.time(),
			detail = signatureOk and nil or tostring(signature),
		}
		publishStudioConnectionDiagnostics(attestation)
	end
	return attestation
end

recordStudioFreshness = function(channel, ok, detail, latencyMs)
	if studioFreshness[channel] == nil then return end
	studioFreshness[channel] = {
		ok = ok == true,
		at = os.time(),
		detail = detail and tostring(detail) or nil,
		latencyMs = tonumber(latencyMs),
	}
	publishStudioConnectionDiagnostics()
end

function TargetPrivate.resumeServerGeneration(target)
	local authoritativeGeneration = tonumber(target.targetGeneration)
	if not authoritativeGeneration or authoritativeGeneration < 1
		or authoritativeGeneration > 9007199254740991
		or authoritativeGeneration ~= math.floor(authoritativeGeneration) then
		return nil, "invalid_target_generation"
	end

	-- The server generation is authoritative only for this exact attested
	-- target. A delayed response from another session/place must never advance
	-- the local fence and strand valid commands behind an unrelated generation.
	local actual = currentStudioTargetAttestation(false)
	local responseSessionId = TargetPrivate.stringValue(target.sessionId)
	local responseConnectorId = TargetPrivate.stringValue(target.connectorId)
	local responseTargetId = TargetPrivate.stringValue(target.targetId)
	local responsePlaceId = TargetPrivate.stringValue(target.expectedPlaceId or target.placeId)
	local responseUniverseId = TargetPrivate.stringValue(target.expectedUniverseId or target.universeId)
	local responsePlaceSignature = TargetPrivate.stringValue(target.expectedPlaceSignature or target.placeSignature)
	if not responseSessionId or responseSessionId ~= actual.sessionId then
		return nil, "session_mismatch"
	end
	if not responseConnectorId or responseConnectorId ~= actual.connectorId then
		return nil, "connector_mismatch"
	end
	if not responseTargetId then
		return nil, "target_id_missing"
	end
	if not responsePlaceId or responsePlaceId ~= actual.placeId then
		return nil, "place_mismatch"
	end
	if not responseUniverseId or responseUniverseId ~= actual.universeId then
		return nil, "universe_mismatch"
	end
	if not responsePlaceSignature or responsePlaceSignature ~= actual.placeSignature then
		return nil, "signature_mismatch"
	end

	local localGeneration = tonumber(actual.targetGeneration)
	if not localGeneration or localGeneration < 0 or localGeneration > 9007199254740991
		or localGeneration ~= math.floor(localGeneration) then
		localGeneration = 0
	end
	local resumedGeneration = math.max(localGeneration, authoritativeGeneration)
	if resumedGeneration > localGeneration then
		plugin:SetSetting("nexusrbxStudioTargetGeneration", resumedGeneration)
	end
	return resumedGeneration, nil
end

updateStudioServerTarget = function(response)
	if type(response) ~= "table" then return end
	local target = type(response.studioTarget) == "table" and response.studioTarget
		or (type(response.target) == "table" and response.target)
		or (type(response.targeting) == "table" and response.targeting)
		or ((response.targetId ~= nil or response.expectedPlaceId ~= nil
			or response.expectedUniverseId ~= nil) and response)
		or nil
	if not target then return end
	local resumedGeneration, generationResumeError = TargetPrivate.resumeServerGeneration(target)
	serverTarget = {
		targetId = target.targetId,
		sessionId = target.sessionId,
		connectorId = target.connectorId,
		expectedPlaceId = target.expectedPlaceId or target.placeId,
		expectedUniverseId = target.expectedUniverseId or target.universeId,
		expectedPlaceSignature = target.expectedPlaceSignature or target.placeSignature,
		targetGeneration = resumedGeneration or target.targetGeneration,
		generationResumeError = generationResumeError,
	}
	publishStudioConnectionDiagnostics()
end

clearStudioServerTarget = function()
	serverTarget = {}
	publishStudioConnectionDiagnostics()
end

getStudioTargetReadiness = function()
	local summary = TargetPrivate.targetSummary(currentStudioTargetAttestation(false))
	return summary.targetReady, summary.detail
end

function TargetPrivate.commandTargetExpectation(command)
	local nested = type(command.studioTarget) == "table" and command.studioTarget
		or (type(command.target) == "table" and command.target)
		or (type(command.routing) == "table" and command.routing)
		or (type(command.payload) == "table" and type(command.payload.studioTarget) == "table" and command.payload.studioTarget)
		or {}
	local function field(name)
		if command[name] ~= nil then return command[name] end
		return nested[name]
	end
	local expectation = {
		targetId = TargetPrivate.stringValue(field("targetId")),
		sessionId = TargetPrivate.stringValue(field("sessionId")),
		expectedPlaceId = TargetPrivate.stringValue(field("expectedPlaceId")),
		expectedUniverseId = TargetPrivate.stringValue(field("expectedUniverseId")),
		expectedPlaceSignature = TargetPrivate.stringValue(field("expectedPlaceSignature")),
		targetGeneration = TargetPrivate.stringValue(field("targetGeneration")),
		operationId = TargetPrivate.stringValue(field("operationId")),
		idempotencyKey = TargetPrivate.stringValue(field("idempotencyKey")),
	}
	expectation.bound = expectation.targetId ~= nil or expectation.sessionId ~= nil
		or expectation.expectedPlaceId ~= nil or expectation.expectedUniverseId ~= nil
		or expectation.expectedPlaceSignature ~= nil or expectation.targetGeneration ~= nil
	return expectation
end

function TargetPrivate.targetError(code, message, stage, expected, actual, command, missingFields)
	local details = { stage = stage, expected = expected, actual = actual }
	if missingFields then details.missingFields = missingFields end
	return {
		ok = false,
		success = false,
		verified = false,
		code = code,
		retryable = false,
		commandId = command.id or command.commandId,
		runId = command.runId,
		stepId = command.stepId,
		operation = command.type,
		operationId = command.operationId,
		idempotencyKey = command.idempotencyKey,
		targetIntegrity = details,
		error = { code = code, message = message, retryable = false, details = details },
	}
end

validateCommandStudioTarget = function(command, stage, approvedAttestation)
	local expected = command._immutableStudioTarget or TargetPrivate.commandTargetExpectation(command)
	command._immutableStudioTarget = expected
	local actual = currentStudioTargetAttestation(true)
	local code, message
	if tonumber(command.lifecycleVersion) == 2 then
		local missing = {}
		for _, fieldName in ipairs({
			"targetId",
			"sessionId",
			"expectedPlaceId",
			"expectedUniverseId",
			"expectedPlaceSignature",
			"targetGeneration",
			"operationId",
			"idempotencyKey",
		}) do
			if expected[fieldName] == nil then table.insert(missing, fieldName) end
		end
		if #missing > 0 then
			message = "Reliable Studio mutation is missing immutable target fields: " .. table.concat(missing, ", ")
			setBridgeState("target_stale", message)
			return false, TargetPrivate.targetError(
				"INVALID_TARGET_ENVELOPE",
				message,
				stage,
				expected,
				actual,
				command,
				missing
			)
		end
	end
	if expected.sessionId and expected.sessionId ~= actual.sessionId then
		code, message = "TARGET_STALE", "The Studio session changed after this command was targeted"
	elseif expected.targetId and expected.targetId ~= actual.targetId then
		code, message = "TARGET_STALE", "The website target is no longer attached to this Studio connector"
	elseif expected.targetGeneration and expected.targetGeneration ~= tostring(actual.targetGeneration) then
		code, message = "TARGET_STALE", "The Studio place generation changed before this command could run"
	elseif expected.expectedPlaceId and expected.expectedPlaceId ~= actual.placeId then
		code, message = "TARGET_CHANGED", "The open Studio place does not match the command's place"
	elseif expected.expectedUniverseId and expected.expectedUniverseId ~= actual.universeId then
		code, message = "TARGET_CHANGED", "The open Studio universe does not match the command's universe"
	elseif expected.expectedPlaceSignature and expected.expectedPlaceSignature ~= actual.placeSignature then
		code, message = "TARGET_CHANGED", "The Studio place changed after the command was prepared"
	elseif approvedAttestation and (approvedAttestation.placeId ~= actual.placeId
		or approvedAttestation.universeId ~= actual.universeId
		or tostring(approvedAttestation.targetGeneration) ~= tostring(actual.targetGeneration)
		or approvedAttestation.placeSignature ~= actual.placeSignature) then
		code, message = "TARGET_CHANGED", "The open Studio place changed after approval"
	end
	if code then
		setBridgeState(code == "TARGET_STALE" and "target_stale" or "target_changed", message)
		return false, TargetPrivate.targetError(code, message, stage, expected, actual, command)
	end
	return true, actual, expected.bound
end
end
-- END src/studio/targetIntegrity.lua

-- BEGIN src/commands/validation.lua
local runProjectValidation, collectDiagnostics, collectOutput, getServiceRoot
do
local function vectorTable(v)
	return { x = v.X, y = v.Y, z = v.Z }
end

local function isFiniteNumber(value)
	return type(value) == "number" and value == value and value ~= math.huge and value ~= -math.huge
end

local function isDescendantOrSelf(inst, root)
	return inst == root or inst:IsDescendantOf(root)
end

local function addValidationIssue(issues, severity, code, inst, message, recommendation)
	table.insert(issues, {
		severity = severity,
		code = code,
		targetPath = inst and fullPath(inst) or "",
		message = tostring(message or code),
		recommendation = recommendation or "",
	})
end

local function validationTarget(payload)
	local target = payload.target or {}
	if target.type == "entire_project" then
		return game, "entire_project", ""
	end
	local path = tostring(target.path or target.modelPath or payload.modelPath or "")
	if path == "" then
		return nil, tostring(target.type or "unknown"), "Validation target path is missing."
	end
	local root = resolvePath(path)
	if not root then
		return nil, tostring(target.type or "unknown"), "Validation target does not exist in Studio."
	end
	return root, tostring(target.type or "unknown"), ""
end

local function validationBounds(root)
	local center = { x = 0, y = 0, z = 0 }
	local size = { x = 0, y = 0, z = 0 }
	local ok, cf, boxSize = pcall(function()
		if root:IsA("Model") then
			return root:GetBoundingBox()
		elseif root:IsA("BasePart") then
			return root.CFrame, root.Size
		else
			local model = Instance.new("Model")
			for _, child in ipairs(root:GetChildren()) do
				if child:IsA("PVInstance") then
					child:Clone().Parent = model
				end
			end
			if #model:GetChildren() == 0 then
				model:Destroy()
				return CFrame.new(), Vector3.new()
			end
			local nextCf, nextSize = model:GetBoundingBox()
			model:Destroy()
			return nextCf, nextSize
		end
	end)
	if ok and cf and boxSize then
		center = vectorTable(cf.Position)
		size = vectorTable(boxSize)
	end
	return {
		center = center,
		size = size,
		lowestPoint = center.y - (size.y / 2),
		highestPoint = center.y + (size.y / 2),
		distanceFromOrigin = math.sqrt((center.x * center.x) + (center.y * center.y) + (center.z * center.z)),
	}
end

runProjectValidation = function(payload)
	payload = payload or {}
	local root, targetType, targetError = validationTarget(payload)
	local issues = {}
	if not root then
		addValidationIssue(issues, "error", "VALIDATION_TARGET_NOT_FOUND", nil, targetError)
		return {
			ok = false,
			checksRun = 1,
			passed = 0,
			issues = issues,
			diagnostics = issues,
			counts = {},
			bounds = nil,
			rulesVersion = tostring(payload.rulesVersion or "studio-validation-1"),
		}
	end

	local target = payload.target or {}
	local checks = payload.checks or {}
	local limits = payload.limits or {}
	local visualOnly = payload.visualOnly == true and targetType ~= "entire_project"
	local maxDescendants = math.clamp(tonumber(limits.maxDescendants) or 1000, 20, 10000)
	local maxTreeDepth = math.clamp(tonumber(limits.maxTreeDepth) or NATIVE_MODEL_LIMITS.maxTreeDepth, 1, 64)
	local diagnosticLimit = math.clamp(tonumber(payload.diagnosticLimit or limits.diagnosticLimit) or 500, 10, 1000)
	local descendants = root == game and game:GetDescendants() or root:GetDescendants()
	local counts = {
		descendants = #descendants,
		models = root:IsA("Model") and 1 or 0,
		folders = root:IsA("Folder") and 1 or 0,
		baseParts = root:IsA("BasePart") and 1 or 0,
		meshParts = root:IsA("MeshPart") and 1 or 0,
		constraints = 0,
		attachments = 0,
		lights = 0,
		particleEmitters = 0,
		decals = 0,
		textures = 0,
		sounds = 0,
		scripts = 0,
		remotes = 0,
		bindables = 0,
		humanoids = 0,
		seats = 0,
		unanchoredParts = 0,
		anchoredParts = 0,
		collisionEnabledParts = 0,
		touchEnabledParts = 0,
		queryEnabledParts = 0,
	}
	local managedIds = {}
	local maxDepthSeen = 0
	local materialSet = {}

	if counts.descendants > maxDescendants then
		addValidationIssue(issues, "error", "VALIDATION_TARGET_TOO_LARGE", root, "Validation target exceeds configured object-count limits.", "Split the target or validate the specific model instead of the entire project.")
	end

	local function depthOf(inst)
		local depth = 0
		local current = inst
		while current and current ~= root do
			depth = depth + 1
			current = current.Parent
		end
		return depth
	end

	local function visit(inst)
		local depth = depthOf(inst)
		if depth > maxDepthSeen then
			maxDepthSeen = depth
		end
		if depth > maxTreeDepth then
			addValidationIssue(issues, "warning", "TREE_DEPTH_EXCEEDED", inst, "Instance hierarchy is deeper than the configured validation limit.", "Review the model hierarchy for accidental nesting.")
		end
		if #inst.Name > 100 then
			addValidationIssue(issues, "warning", "NAME_TOO_LONG", inst, "Instance name is unusually long.", "Use shorter instance names for easier Studio maintenance.")
		end
		local attrs = attributesOf(inst)
		local attrCount = 0
		for key in pairs(attrs) do
			attrCount = attrCount + 1
			if #tostring(key) > 100 then
				addValidationIssue(issues, "warning", "ATTRIBUTE_NAME_TOO_LONG", inst, "An attribute name is unusually long.")
			end
		end
		if attrCount > 40 then
			addValidationIssue(issues, "warning", "ATTRIBUTE_COUNT_HIGH", inst, "Instance has many attributes.", "Remove metadata that is not needed at runtime.")
		end
		local tags = Services.CollectionService:GetTags(inst)
		if #tags > 40 then
			addValidationIssue(issues, "warning", "TAG_COUNT_HIGH", inst, "Instance has many tags.", "Remove tags that are not needed for gameplay or tooling.")
		end
		local nexusId = inst:GetAttribute("NexusInstanceId")
		if nexusId then
			local key = tostring(nexusId)
			if managedIds[key] then
				addValidationIssue(issues, "error", "DUPLICATE_MANAGED_ID", inst, "Duplicate NexusInstanceId detected.", "Regenerate or repair the managed model metadata.")
			else
				managedIds[key] = true
			end
		end
		if inst:IsA("Model") then
			counts.models = counts.models + 1
		elseif inst:IsA("Folder") then
			counts.folders = counts.folders + 1
		end
		if inst:IsA("BasePart") then
			counts.baseParts = counts.baseParts + 1
			if inst:IsA("MeshPart") then
				counts.meshParts = counts.meshParts + 1
			end
			if inst:IsA("Seat") or inst:IsA("VehicleSeat") then
				counts.seats = counts.seats + 1
				if inst:IsA("VehicleSeat") then
					addValidationIssue(issues, "warning", "UNEXPECTED_VEHICLE_SEAT", inst, "VehicleSeat found in validation target.", "Confirm this model is intended to contain vehicle controls.")
				end
			end
			if inst.Anchored then
				counts.anchoredParts = counts.anchoredParts + 1
			else
				counts.unanchoredParts = counts.unanchoredParts + 1
			end
			if inst.CanCollide then
				counts.collisionEnabledParts = counts.collisionEnabledParts + 1
			end
			if inst.CanTouch then
				counts.touchEnabledParts = counts.touchEnabledParts + 1
			end
			if inst.CanQuery then
				counts.queryEnabledParts = counts.queryEnabledParts + 1
			end
			materialSet[tostring(inst.Material)] = true
			local pos = inst.Position
			local size = inst.Size
			if not (isFiniteNumber(pos.X) and isFiniteNumber(pos.Y) and isFiniteNumber(pos.Z) and isFiniteNumber(size.X) and isFiniteNumber(size.Y) and isFiniteNumber(size.Z)) then
				addValidationIssue(issues, "error", "INVALID_TRANSFORM", inst, "BasePart has a non-finite transform or size.", "Reset the part transform and size in Studio.")
			end
			if size.X <= 0 or size.Y <= 0 or size.Z <= 0 then
				addValidationIssue(issues, "error", "INVALID_PART_SIZE", inst, "BasePart has a non-positive dimension.", "Set all part dimensions to positive finite values.")
			end
			if math.abs(pos.X) > 50000 or math.abs(pos.Y) > 50000 or math.abs(pos.Z) > 50000 then
				addValidationIssue(issues, "warning", "PART_FAR_FROM_ORIGIN", inst, "Part is very far from the world origin.", "Move the model closer to the intended play area.")
			end
			if not inst.Anchored and visualOnly then
				addValidationIssue(issues, "warning", "UNANCHORED_DECORATIVE_PART", inst, "Visual-only target contains an unanchored part.", "Anchor decorative parts unless physics is intentional.")
			end
		end
		if SCRIPT_CLASSES[inst.ClassName] then
			counts.scripts = counts.scripts + 1
			local sourceOk, source = readScriptSource(inst)
			if sourceOk then
				local contextValidation = ScriptContextGuard.validate({
					className = inst.ClassName,
					path = fullPath(inst),
					source = source,
				})
				for _, finding in ipairs(contextValidation.findings or {}) do
					table.insert(issues, {
						severity = finding.severity == "blocking" and "error" or tostring(finding.severity or "error"),
						code = finding.ruleCode,
						ruleCode = finding.ruleCode,
						targetPath = fullPath(inst),
						message = finding.message or finding.explanation or finding.ruleCode,
						explanation = finding.explanation,
						line = finding.line,
						requiredContext = contextValidation.requiredContext,
						recommendation = finding.ruleCode == "MIXED_RUNTIME_CONTEXT"
							and "Split the behavior into client and server scripts connected by remotes."
							or "Correct the script class or location before running the project.",
					})
				end
			else
				addValidationIssue(
					issues,
					"warning",
					"SCRIPT_SOURCE_UNREADABLE",
					inst,
					"Could not read this script while checking its execution context.",
					"Open the script in Studio and run validation again."
				)
			end
			if visualOnly then
				addValidationIssue(issues, "critical", "UNEXPECTED_EXECUTABLE_CONTENT", inst, "Visual-only validation target contains executable Luau.", "Remove the script or validate it as part of an explicit project-level review.")
			end
		end
		if NETWORKING_CLASSES[inst.ClassName] then
			if inst.ClassName == "RemoteEvent" or inst.ClassName == "RemoteFunction" or inst.ClassName == "UnreliableRemoteEvent" then
				counts.remotes = counts.remotes + 1
			else
				counts.bindables = counts.bindables + 1
			end
			if visualOnly then
				addValidationIssue(issues, "critical", "UNEXPECTED_NETWORKING_OBJECT", inst, "Visual-only validation target contains a networking or bindable object.", "Remove unexpected remotes or validate the containing project explicitly.")
			end
		end
		if inst:IsA("Constraint") then
			counts.constraints = counts.constraints + 1
			local ok0, a0 = pcall(function() return inst.Attachment0 end)
			local ok1, a1 = pcall(function() return inst.Attachment1 end)
			if (ok0 and a0 and not isDescendantOrSelf(a0, root)) or (ok1 and a1 and not isDescendantOrSelf(a1, root)) then
				addValidationIssue(issues, "error", "BROKEN_CONSTRAINT_REFERENCE", inst, "Constraint references an attachment outside the validation target.", "Repair the constraint attachments or include the referenced objects in the target.")
			end
		end
		if inst:IsA("WeldConstraint") then
			counts.constraints = counts.constraints + 1
			if (inst.Part0 and not isDescendantOrSelf(inst.Part0, root)) or (inst.Part1 and not isDescendantOrSelf(inst.Part1, root)) then
				addValidationIssue(issues, "error", "BROKEN_CONSTRAINT_REFERENCE", inst, "WeldConstraint references a part outside the validation target.", "Repair the weld parts or include the referenced objects in the target.")
			end
		end
		if inst:IsA("Attachment") then
			counts.attachments = counts.attachments + 1
		end
		if NATIVE_LIGHT_CLASSES[inst.ClassName] then
			counts.lights = counts.lights + 1
		end
		if inst:IsA("ParticleEmitter") then
			counts.particleEmitters = counts.particleEmitters + 1
		end
		if inst:IsA("Decal") then
			counts.decals = counts.decals + 1
			local texture = tostring(inst.Texture or "")
			if texture ~= "" and not string.match(texture, "^rbxassetid://%d+$") and not string.match(texture, "^%d+$") then
				addValidationIssue(issues, "warning", "UNEXPECTED_ASSET_REFERENCE", inst, "Decal texture is not a simple Roblox asset ID.", "Verify the texture reference is accessible in Studio.")
			end
		end
		if inst:IsA("Texture") then
			counts.textures = counts.textures + 1
			local texture = tostring(inst.Texture or "")
			if texture ~= "" and not string.match(texture, "^rbxassetid://%d+$") and not string.match(texture, "^%d+$") then
				addValidationIssue(issues, "warning", "UNEXPECTED_ASSET_REFERENCE", inst, "Texture reference is not a simple Roblox asset ID.", "Verify the texture reference is accessible in Studio.")
			end
		end
		if inst:IsA("Sound") then
			counts.sounds = counts.sounds + 1
			local soundId = tostring(inst.SoundId or "")
			if soundId ~= "" and not string.match(soundId, "^rbxassetid://%d+$") and not string.match(soundId, "^%d+$") then
				addValidationIssue(issues, "warning", "UNEXPECTED_ASSET_REFERENCE", inst, "SoundId is not a simple Roblox asset ID.", "Verify the sound reference is accessible in Studio.")
			end
		end
		if inst:IsA("ObjectValue") and inst.Value and visualOnly and not isDescendantOrSelf(inst.Value, root) then
			addValidationIssue(issues, "warning", "EXTERNAL_OBJECT_REFERENCE", inst, "ObjectValue points outside the validation target.", "Confirm this reference is intentional.")
		end
		if inst:IsA("Humanoid") then
			counts.humanoids = counts.humanoids + 1
		end
	end

	visit(root)
	for _, inst in ipairs(descendants) do
		if #issues >= diagnosticLimit then
			break
		end
		visit(inst)
	end

	local uniqueMaterials = 0
	for _ in pairs(materialSet) do
		uniqueMaterials = uniqueMaterials + 1
	end
	counts.uniqueMaterials = uniqueMaterials

	local bounds = validationBounds(root)
	if checks.managedIdentity ~= false and visualOnly then
		local managed = root:GetAttribute("NexusManaged") == true or root:GetAttribute("NexusGenerated") == true
		local expectedModelId = tostring(target.modelId or "")
		local actualModelId = tostring(root:GetAttribute("NexusModelId") or "")
		if not managed then
			addValidationIssue(issues, "warning", "MISSING_MANAGED_METADATA", root, "Expected NexusRBX managed metadata is missing.", "Reinsert or inspect the model through NexusRBX before relying on receipt-based validation.")
		end
		if expectedModelId ~= "" and actualModelId ~= "" and expectedModelId ~= actualModelId then
			addValidationIssue(issues, "error", "MANAGED_IDENTITY_MISMATCH", root, "Managed model ID does not match the validation receipt.", "Validate the model created by the matching NexusRBX receipt.")
		end
	end
	if counts.baseParts == 0 and visualOnly then
		addValidationIssue(issues, "error", "NO_USABLE_VISUAL_CONTENT", root, "Validation target contains no usable BaseParts.", "Reinsert or rebuild the model.")
	end
	if counts.anchoredParts == 0 and counts.baseParts > 0 and visualOnly then
		addValidationIssue(issues, "error", "NO_ANCHORED_STRUCTURE", root, "Static visual target has no anchored structural parts.", "Anchor the structural parts unless physics is intentional.")
	end
	if counts.meshParts > 0 and counts.meshParts == counts.collisionEnabledParts then
		addValidationIssue(issues, "warning", "DECORATIVE_COLLISION_ENABLED", root, "Every MeshPart has collision enabled.", "Disable collision on decorative MeshParts when players do not need to stand on them.")
	end
	if counts.touchEnabledParts > 100 then
		addValidationIssue(issues, "warning", "TOUCH_EVENTS_HIGH", root, "Many parts have CanTouch enabled.", "Disable touch on decorative parts that do not need touch events.")
	end
	if counts.descendants > 1000 then
		addValidationIssue(issues, "warning", "DESCENDANT_COUNT_HIGH", root, "Validation target has more than 1,000 descendants.", "Review whether the model can be simplified.")
	end
	if counts.baseParts > 500 then
		addValidationIssue(issues, "warning", "BASE_PART_COUNT_HIGH", root, "Validation target has more than 500 BaseParts.", "Consider simplifying geometry.")
	end
	if counts.constraints > 250 then
		addValidationIssue(issues, "warning", "CONSTRAINT_COUNT_HIGH", root, "Validation target has more than 250 constraints.", "Review whether all constraints are needed.")
	end
	if bounds.distanceFromOrigin > 50000 then
		addValidationIssue(issues, "warning", "MODEL_FAR_FROM_ORIGIN", root, "Target bounds are very far from the world origin.", "Move the model closer to the intended play area.")
	end
	if bounds.size.x > 4096 or bounds.size.y > 4096 or bounds.size.z > 4096 then
		addValidationIssue(issues, "warning", "EXTREME_BOUNDS", root, "Target bounding box is extremely large.", "Review accidental distant parts or oversized geometry.")
	end

	local errors = 0
	local critical = 0
	for _, issue in ipairs(issues) do
		if issue.severity == "error" then
			errors = errors + 1
		elseif issue.severity == "critical" then
			critical = critical + 1
		end
	end
	local ok = errors == 0 and critical == 0
	local checksRun = 0
	for _, enabled in pairs(checks) do
		if enabled == true then
			checksRun = checksRun + 1
		end
	end
	if checksRun == 0 then
		checksRun = 1
	end
	return {
		ok = ok,
		checksRun = checksRun,
		passed = ok and checksRun or math.max(0, checksRun - errors - critical),
		target = { type = targetType, path = root == game and "" or fullPath(root), name = root.Name },
		counts = counts,
		bounds = bounds,
		issues = issues,
		diagnostics = issues,
		rulesVersion = tostring(payload.rulesVersion or "studio-validation-1"),
		summary = {
			checksRun = checksRun,
			passed = ok and checksRun or math.max(0, checksRun - errors - critical),
			errors = errors,
			critical = critical,
		},
	}
end

collectDiagnostics = function(payload)
	local normalizedPayload = {}
	for key, value in pairs(payload or {}) do
		normalizedPayload[key] = value
	end
	if type(normalizedPayload.target) ~= "table" and normalizedPayload.modelPath == nil then
		normalizedPayload.target = { type = "entire_project" }
	end
	return runProjectValidation(normalizedPayload)
end

-- Output/log observer. LogService.MessageOut fires in the edit-context plugin for
-- messages printed during Play Solo, so we keep a capped ring buffer and merge it
-- with LogService:GetLogHistory() (which also includes pre-connection messages).
local outputLogBuffer, OUTPUT_LOG_LIMIT, LOG_MESSAGE_LEVEL = {}, 500, {
	[Enum.MessageType.MessageOutput] = "output",
	[Enum.MessageType.MessageInfo] = "info",
	[Enum.MessageType.MessageWarning] = "warning",
	[Enum.MessageType.MessageError] = "error",
}
do
	local ok, logService = pcall(function()
		return game:GetService("LogService")
	end)
	if ok and logService then
		logService.MessageOut:Connect(function(message, messageType)
			table.insert(outputLogBuffer, {
				message = tostring(message),
				level = LOG_MESSAGE_LEVEL[messageType] or "output",
				timestamp = os.time(),
			})
			if #outputLogBuffer > OUTPUT_LOG_LIMIT then
				table.remove(outputLogBuffer, 1)
			end
		end)
	end
end

collectOutput = function(payload)
	payload = payload or {}
	local maxMessages = math.clamp(tonumber(payload.maxMessages) or 200, 1, 500)
	local sinceTimestamp = tonumber(payload.sinceTimestamp) or 0
	local levelFilter = nil
	if type(payload.levels) == "table" and #payload.levels > 0 then
		levelFilter = {}
		for _, level in ipairs(payload.levels) do
			levelFilter[tostring(level):lower()] = true
		end
	end

	local combined, seen = {}, {}
	local function push(entry)
		local key = tostring(entry.timestamp) .. "|" .. tostring(entry.message)
		if seen[key] then
			return
		end
		seen[key] = true
		table.insert(combined, entry)
	end

	local okHistory, history = pcall(function()
		return game:GetService("LogService"):GetLogHistory()
	end)
	if okHistory and type(history) == "table" then
		for _, item in ipairs(history) do
			push({
				message = tostring(item.message),
				level = LOG_MESSAGE_LEVEL[item.messageType] or "output",
				timestamp = math.floor(tonumber(item.timestamp) or os.time()),
			})
		end
	end
	for _, entry in ipairs(outputLogBuffer) do
		push(entry)
	end

	local filtered = {}
	for _, entry in ipairs(combined) do
		if (not levelFilter or levelFilter[entry.level]) and entry.timestamp >= sinceTimestamp then
			table.insert(filtered, entry)
		end
	end
	if #filtered > maxMessages then
		local trimmed = {}
		for i = #filtered - maxMessages + 1, #filtered do
			table.insert(trimmed, filtered[i])
		end
		filtered = trimmed
	end

	local errorCount, warningCount = 0, 0
	for _, entry in ipairs(filtered) do
		if entry.level == "error" then
			errorCount = errorCount + 1
		elseif entry.level == "warning" then
			warningCount = warningCount + 1
		end
	end

	return {
		ok = true,
		output = filtered,
		messages = filtered,
		summary = {
			total = #filtered,
			errors = errorCount,
			warnings = warningCount,
		},
	}
end

getServiceRoot = function(serviceName)
	if serviceName == "ServerScriptService" then
		return Services.ServerScriptService
	elseif serviceName == "StarterPlayerScripts" then
		return getStarterPlayerScripts()
	elseif serviceName == "StarterGui" then
		return Services.StarterGui
	else
		return Services.ReplicatedStorage
	end
end
end
