-- BEGIN src/commands/writeTools.lua
local applyArtifact, getStudioContext, patchScript, renameInstanceTool, moveInstanceTool, duplicateInstanceTool, createScript, deleteScript, updateProperties, applyAssetReference, updateAttributes, updateTags, replaceInFiles, createSnapshotTool, parseLuau, runSmokeCheck, ensureCleanFolder, validateLuauSource, classNameForKind
do
getStudioContext = function()
	local roots = {}
	for _, inst in ipairs(getInspectionRoots()) do
		table.insert(roots, {
			name = inst.Name,
			className = inst.ClassName,
			path = fullPath(inst),
			childCount = #inst:GetChildren(),
		})
	end
	return {
		placeName = game.Name,
		placeId = tostring(game.PlaceId),
		jobId = tostring(game.JobId),
		pluginVersion = PLUGIN_VERSION,
		roots = roots,
	}
end

patchScript = function(payload)
	local path = payload.path
	local inst = resolvePath(path)
	if not inst or not SCRIPT_CLASSES[inst.ClassName] then
		return { ok = false, error = "Script not found", path = path }
	end
	local hashOk, hashResult = verifyExpectedScriptHash(inst, payload.expectedSourceHash, fullPath(inst))
	if not hashOk then
		return hashResult
	end
	local ok, source = readScriptSource(inst)
	if not ok then
		return { ok = false, error = "Could not read script source", path = path }
	end
	local currentHash = stableHash(source)
	local nextSource = payload.source and payload.source ~= "" and tostring(payload.source) or source
	local replacements = 0
	for _, patch in ipairs(payload.patches or {}) do
		local find = tostring(patch.find or "")
		local replace = tostring(patch.replace or "")
		if find ~= "" then
			if patch.all == true then
				local count
				nextSource, count = string.gsub(nextSource, escapePattern(find), escapeReplacement(replace))
				replacements = replacements + count
			else
				local startIndex, endIndex = string.find(nextSource, find, 1, true)
				if startIndex then
					nextSource = string.sub(nextSource, 1, startIndex - 1) .. replace .. string.sub(nextSource, endIndex + 1)
					replacements = replacements + 1
				else
					return { ok = false, error = "Patch find text not found", path = fullPath(inst), find = find }
				end
			end
		end
	end
	local contextValidation = ScriptContextGuard.validate({
		className = inst.ClassName,
		path = fullPath(inst),
		source = nextSource,
	})
	if not contextValidation.ok then
		return ScriptContextGuard.failure(contextValidation)
	end
	local snapshots = {}
	table.insert(snapshots, snapshotInstance(fullPath(inst)))
	local wrote, writeErr = writeScriptSource(inst, nextSource)
	if not wrote then
		return rollbackMutation(snapshots, "patch_script_failed", writeErr or "Could not write patched source", {
			path = fullPath(inst),
		})
	end
	return {
		ok = true,
		path = fullPath(inst),
		replacements = replacements,
		previousHash = currentHash,
		sourceHash = stableHash(nextSource),
		sourceLength = #nextSource,
		snapshots = snapshots,
	}
end

renameInstanceTool = function(payload)
	local inst = resolvePath(payload.path)
	if not inst then
		return { ok = false, error = "Instance not found", path = payload.path }
	end
	local hashOk, hashResult = verifyExpectedScriptHash(inst, payload.expectedSourceHash, fullPath(inst))
	if not hashOk then
		return hashResult
	end
	local newName = tostring(payload.newName or payload.name or inst.Name)
	local existingTarget = inst.Parent and inst.Parent:FindFirstChild(newName) or nil
	if existingTarget and existingTarget ~= inst then
		return {
			ok = false,
			code = "target_exists",
			error = "Rename target already exists",
			path = fullPath(existingTarget),
			retryable = false,
		}
	end
	local snapshots = {}
	local oldPath = fullPath(inst)
	appendSnapshotTree(inst, snapshots)
	local destinationPath = inst.Parent and (fullPath(inst.Parent) .. "/" .. newName) or newName
	if destinationPath ~= oldPath then
		table.insert(snapshots, snapshotInstance(destinationPath))
	end
	local mutationOk, mutationErr = pcall(function()
		inst.Name = newName
	end)
	if not mutationOk then
		return rollbackMutation(snapshots, "rename_instance_failed", mutationErr, { path = oldPath })
	end
	return { ok = true, previousPath = oldPath, path = fullPath(inst), snapshots = snapshots }
end

moveInstanceTool = function(payload)
	local inst = resolvePath(payload.path)
	if not inst then
		return { ok = false, error = "Instance not found", path = payload.path }
	end
	local hashOk, hashResult = verifyExpectedScriptHash(inst, payload.expectedSourceHash, fullPath(inst))
	if not hashOk then
		return hashResult
	end
	local targetPath = payload.newPath and canonicalizePath(payload.newPath) or ""
	local parent = nil
	local leaf = nil
	local parentPath = ""
	if targetPath ~= "" then
		local parts = splitPath(targetPath)
		leaf = parts[#parts]
		if #parts > 1 then
			parentPath = table.concat(parts, "/", 1, #parts - 1)
			parent = resolvePath(parentPath)
		end
		if not leaf or leaf == "" or (not parent and payload.createParents == false) then
			return { ok = false, error = "Target parent not found", path = payload.path }
		end
	else
		parentPath = canonicalizePath(payload.newParentPath)
		parent = resolvePath(parentPath)
	end
	if targetPath == "" and not parent then
		return { ok = false, error = "Target parent not found", path = payload.path }
	end
	local destinationName = leaf and leaf ~= "" and leaf or inst.Name
	local sourcePath = fullPath(inst)
	local destinationPath = targetPath ~= "" and targetPath or (fullPath(parent) .. "/" .. destinationName)
	if (parent and (parent == inst or parent:IsDescendantOf(inst)))
		or string.sub(destinationPath, 1, #sourcePath + 1) == sourcePath .. "/" then
		return {
			ok = false,
			code = "destination_invalid",
			error = "An instance cannot be moved into its own descendant tree",
			path = sourcePath,
			retryable = false,
		}
	end
	local existingTarget = parent and parent:FindFirstChild(destinationName) or nil
	if existingTarget and existingTarget ~= inst then
		return {
			ok = false,
			code = "target_exists",
			error = "Move target already exists",
			path = fullPath(existingTarget),
			retryable = false,
		}
	end
	local snapshots = {}
	local oldPath = sourcePath
	appendSnapshotTree(inst, snapshots)
	if destinationPath ~= oldPath then
		appendMissingPathSnapshots(destinationPath, snapshots, {})
	end
	local mutationOk, mutationResult = pcall(function()
		local targetParent = parent
		local targetLeaf = leaf
		if targetPath ~= "" and not targetParent then
			targetParent, targetLeaf = ensureParent(targetPath, payload.createParents ~= false)
		end
		if not targetParent then
			error("Target parent not found")
		end
		local currentTarget = targetParent:FindFirstChild(destinationName)
		if currentTarget and currentTarget ~= inst then
			error("Move target already exists")
		end
		if targetLeaf and targetLeaf ~= "" then
			inst.Name = targetLeaf
		end
		inst.Parent = targetParent
		return inst
	end)
	if not mutationOk then
		return rollbackMutation(snapshots, "move_instance_failed", mutationResult, { path = oldPath })
	end
	return { ok = true, previousPath = oldPath, path = fullPath(mutationResult), snapshots = snapshots }
end

duplicateInstanceTool = function(payload)
	local inst = resolvePath(payload.path)
	if not inst then
		return { ok = false, error = "Instance not found", path = payload.path }
	end
	local sourceHashOk, sourceHashResult = verifyExpectedScriptHash(inst, payload.expectedSourceHash, fullPath(inst))
	if not sourceHashOk then
		return sourceHashResult
	end
	local targetPath = canonicalizePath(payload.newPath)
	local parts = splitPath(targetPath)
	local leaf = parts[#parts]
	local parentPath = #parts > 1 and table.concat(parts, "/", 1, #parts - 1) or ""
	local parent = parentPath ~= "" and resolvePath(parentPath) or nil
	if not leaf or leaf == "" or (not parent and payload.createParents == false) then
		return { ok = false, error = "Could not resolve duplicate target", path = payload.newPath }
	end
	local sourcePath = fullPath(inst)
	if (parent and (parent == inst or parent:IsDescendantOf(inst)))
		or string.sub(targetPath, 1, #sourcePath + 1) == sourcePath .. "/" then
		return {
			ok = false,
			code = "destination_invalid",
			error = "An instance cannot be duplicated into its own descendant tree",
			path = sourcePath,
			retryable = false,
		}
	end
	local existing = parent and parent:FindFirstChild(leaf) or nil
	if existing == inst then
		return {
			ok = false,
			code = "source_target_conflict",
			error = "Duplicate target must differ from the source",
			path = fullPath(inst),
			retryable = false,
		}
	end
	if existing and SCRIPT_CLASSES[existing.ClassName] then
		local targetHashOk, targetHashResult =
			verifyExpectedScriptHash(existing, payload.expectedTargetSourceHash, fullPath(existing))
		if not targetHashOk then
			return targetHashResult
		end
	end
	local snapshots = {}
	if existing then
		appendSnapshotTree(existing, snapshots)
	else
		appendMissingPathSnapshots(targetPath, snapshots, {})
	end
	local mutationOk, mutationResult = pcall(function()
		local targetParent = parent
		local targetLeaf = leaf
		if not targetParent then
			targetParent, targetLeaf = ensureParent(targetPath, payload.createParents ~= false)
		end
		if not targetParent or not targetLeaf then
			error("Could not resolve duplicate target")
		end
		local currentTarget = targetParent:FindFirstChild(targetLeaf)
		if currentTarget == inst then
			error("Duplicate target must differ from the source")
		end
		if currentTarget ~= existing then
			error("Duplicate target changed before mutation")
		end
		local clone = inst:Clone()
		if currentTarget then
			currentTarget:Destroy()
		end
		clone.Name = targetLeaf
		clone.Parent = targetParent
		ensureManagedId(clone)
		return clone
	end)
	if not mutationOk then
		return rollbackMutation(snapshots, "duplicate_instance_failed", mutationResult, {
			path = tostring(payload.newPath or ""),
			sourcePath = sourcePath,
		})
	end
	local clone = mutationResult
	return { ok = true, path = fullPath(clone), sourcePath = sourcePath, snapshots = snapshots }
end

createScript = function(payload)
	payload.createOnly = true
	return writeScript(payload)
end

deleteScript = function(payload)
	local inst = resolvePath(payload.path)
	if inst and not SCRIPT_CLASSES[inst.ClassName] then
		return { ok = false, error = "Target is not a script", path = payload.path }
	end
	local previousHash = nil
	if inst then
		local hashOk, hashResult = verifyExpectedScriptHash(inst, payload.expectedSourceHash, fullPath(inst))
		if not hashOk then
			return hashResult
		end
		previousHash = scriptHash(inst)
	end
	local result = deleteInstanceTool(payload)
	result.previousHash = previousHash
	return result
end

updateProperties = function(payload)
	local inst = resolvePath(payload.path)
	if not inst then
		return { ok = false, error = "Instance not found", path = payload.path }
	end
	local hashOk, hashResult = verifyExpectedScriptHash(inst, payload.expectedSourceHash, fullPath(inst))
	if not hashOk then
		return hashResult
	end
	local snapshots = {}
	table.insert(snapshots, snapshotInstance(fullPath(inst)))
	local errors = {}
	for key, value in pairs(payload.properties or {}) do
		local ok, err = safeSetProperty(inst, key, value)
		if not ok then
			table.insert(errors, { property = key, message = err })
		end
	end
	if #errors > 0 then
		return rollbackMutation(snapshots, "update_properties_failed", "One or more Studio properties could not be updated", {
			path = fullPath(inst),
			errors = errors,
		})
	end
	return { path = fullPath(inst), properties = propertiesOf(inst), errors = {}, snapshots = snapshots, ok = true }
end

applyAssetReference = function(payload)
	local requestedPath = tostring(payload.path or "")
	local inst = resolvePath(requestedPath)
	if not inst then
		return {
			ok = false,
			code = "STUDIO_ASSET_IMPLEMENTATION_FAILED",
			error = "Target instance not found",
			path = requestedPath,
		}
	end

	-- Inspect the exact target and current value before taking a snapshot or
	-- mutating anything. The server has already validated this tuple, but the
	-- live Studio class must still agree.
	local targetPath = fullPath(inst)
	local expectedClassName = tostring(payload.className or "")
	local property = tostring(payload.property or "")
	local previousValue = safePropertyValue(inst, property)
	if inst.ClassName ~= expectedClassName then
		return {
			ok = false,
			code = "STUDIO_ASSET_IMPLEMENTATION_FAILED",
			error = "Target class changed before the asset could be applied",
			path = targetPath,
			className = inst.ClassName,
			expectedClassName = expectedClassName,
			property = property,
		}
	end

	local robloxAssetId = tostring(payload.robloxAssetId or "")
	local assetReference = "rbxassetid://" .. robloxAssetId
	local snapshot = snapshotInstance(targetPath)
	local ok, err = safeSetAssetReference(inst, property, assetReference, expectedClassName)
	local currentValue = safePropertyValue(inst, property)
	local exact = ok and currentValue == assetReference
	local changed = {
		path = targetPath,
		className = inst.ClassName,
		property = property,
		previousValue = previousValue,
		currentValue = currentValue,
	}
	local details = {
		path = targetPath,
		className = inst.ClassName,
		property = property,
		robloxAssetId = robloxAssetId,
		assetRecordId = tostring(payload.assetRecordId or ""),
		assetReference = assetReference,
		previousValue = previousValue,
		currentValue = currentValue,
		changedInstances = { changed },
		snapshotIds = { snapshot.id },
		affectedPaths = { targetPath },
	}

	if not exact then
		return rollbackMutation(
			{ snapshot },
			"STUDIO_ASSET_IMPLEMENTATION_FAILED",
			err or "Studio did not retain the exact Roblox asset reference",
			details
		)
	end

	details.ok = true
	details.snapshots = { snapshot }
	return details
end

updateAttributes = function(payload)
	local inst = resolvePath(payload.path)
	if not inst then
		return { ok = false, error = "Instance not found", path = payload.path }
	end
	local hashOk, hashResult = verifyExpectedScriptHash(inst, payload.expectedSourceHash, fullPath(inst))
	if not hashOk then
		return hashResult
	end
	local snapshots = { snapshotInstance(fullPath(inst)) }
	local mutationOk, mutationErr = pcall(function()
		for key, value in pairs(payload.attributes or payload.values or {}) do
			inst:SetAttribute(tostring(key), value)
		end
	end)
	if not mutationOk then
		return rollbackMutation(snapshots, "update_attributes_failed", mutationErr, {
			path = fullPath(inst),
		})
	end
	return { ok = true, path = fullPath(inst), attributes = attributesOf(inst), snapshots = snapshots }
end

updateTags = function(payload)
	local inst = resolvePath(payload.path)
	if not inst then
		return { ok = false, error = "Instance not found", path = payload.path }
	end
	local hashOk, hashResult = verifyExpectedScriptHash(inst, payload.expectedSourceHash, fullPath(inst))
	if not hashOk then
		return hashResult
	end
	local snapshots = { snapshotInstance(fullPath(inst)) }
	local mutationOk, mutationErr = pcall(function()
		if payload.set ~= nil then
			for _, tag in ipairs(Services.CollectionService:GetTags(inst)) do
				Services.CollectionService:RemoveTag(inst, tag)
			end
			for _, tag in ipairs(payload.set or {}) do
				Services.CollectionService:AddTag(inst, tostring(tag))
			end
		else
			for _, tag in ipairs(payload.remove or {}) do
				Services.CollectionService:RemoveTag(inst, tostring(tag))
			end
			for _, tag in ipairs(payload.add or {}) do
				Services.CollectionService:AddTag(inst, tostring(tag))
			end
		end
	end)
	if not mutationOk then
		return rollbackMutation(snapshots, "update_tags_failed", mutationErr, {
			path = fullPath(inst),
		})
	end
	return { ok = true, path = fullPath(inst), tags = Services.CollectionService:GetTags(inst), snapshots = snapshots }
end

replaceInFiles = function(payload)
	local paths = payload.paths or {}
	if #paths == 0 then
		for _, inst in ipairs(game:GetDescendants()) do
			if SCRIPT_CLASSES[inst.ClassName] then
				table.insert(paths, fullPath(inst))
			end
		end
	end
	local maxFiles = math.clamp(tonumber(payload.maxFiles) or 120, 1, 500)
	local candidates = {}
	local snapshots = {}
	local find = tostring(payload.find or "")
	local replace = tostring(payload.replace or "")
	local expectedSourceHashes = type(payload.expectedSourceHashes) == "table" and payload.expectedSourceHashes or {}
	if find == "" then
		return { ok = false, error = "find is required" }
	end
	for _, path in ipairs(paths) do
		if #candidates >= maxFiles then
			break
		end
		local inst = resolvePath(path)
		if inst and SCRIPT_CLASSES[inst.ClassName] then
			local readOk, source = readScriptSource(inst)
			if not readOk then
				return {
					ok = false,
					code = "source_read_failed",
					error = "Could not read script source",
					path = fullPath(inst),
					retryable = false,
				}
			end
			local hay = source
			local needle = find
			if payload.caseSensitive == false then
				hay = string.lower(source)
				needle = string.lower(find)
			end
			if string.find(hay, needle, 1, true) then
				local canonicalPath = fullPath(inst)
				local expectedHash = expectedSourceHashes[canonicalPath] or expectedSourceHashes[tostring(path)]
				local hashOk, hashResult = verifyExpectedScriptHash(inst, expectedHash, canonicalPath)
				if not hashOk then
					return hashResult
				end
				local nextSource
				if payload.caseSensitive == false then
					nextSource = source
					local startIndex, endIndex = string.find(string.lower(nextSource), needle, 1, true)
					while startIndex do
						nextSource = string.sub(nextSource, 1, startIndex - 1) .. replace .. string.sub(nextSource, endIndex + 1)
						startIndex, endIndex = string.find(string.lower(nextSource), needle, startIndex + #replace, true)
					end
				else
					nextSource = string.gsub(source, escapePattern(find), escapeReplacement(replace))
				end
				table.insert(candidates, {
					instance = inst,
					path = canonicalPath,
					source = source,
					nextSource = nextSource,
				})
			end
		end
	end
	for _, candidate in ipairs(candidates) do
		local contextValidation = ScriptContextGuard.validate({
			className = candidate.instance.ClassName,
			path = candidate.path,
			source = candidate.nextSource,
		})
		if not contextValidation.ok then
			return ScriptContextGuard.failure(contextValidation)
		end
	end
	for _, candidate in ipairs(candidates) do
		table.insert(snapshots, snapshotInstance(candidate.path))
	end

	local results = {}
	for _, candidate in ipairs(candidates) do
		local wrote, writeErr = writeScriptSource(candidate.instance, candidate.nextSource)
		if not wrote then
			return rollbackMutation(snapshots, "replace_in_files_failed", writeErr or "Could not replace script source", {
				path = candidate.path,
				files = results,
				filesChanged = #results,
			})
		end
		table.insert(results, {
			path = candidate.path,
			previousHash = stableHash(candidate.source),
			sourceHash = stableHash(candidate.nextSource),
		})
	end
	return { ok = true, filesChanged = #results, files = results, snapshots = snapshots }
end

createSnapshotTool = function(payload)
	local snapshots = {}
	for _, path in ipairs(payload.paths or {}) do
		local inst = resolvePath(path)
		if inst and payload.recursive ~= false then
			appendSnapshotTree(inst, snapshots)
		else
			table.insert(snapshots, snapshotInstance(path))
		end
	end
	return { snapshots = snapshots, snapshotCount = #snapshots }
end

runSmokeCheck = function(payload)
	local maxScripts = math.clamp(tonumber(payload.maxScripts) or 200, 10, 500)
	local checked = 0
	local issues = {}
	local function scan(inst)
		if checked >= maxScripts then
			return
		end
		if SCRIPT_CLASSES[inst.ClassName] then
			checked = checked + 1
			local ok, source = readScriptSource(inst)
			if not ok then
				table.insert(issues, { path = fullPath(inst), message = "Could not read source" })
			elseif payload.includeSourceScan ~= false then
				local contextValidation = ScriptContextGuard.validate({
					className = inst.ClassName,
					path = fullPath(inst),
					source = source,
				})
				for _, finding in ipairs(contextValidation.findings or {}) do
					table.insert(issues, {
						path = fullPath(inst),
						code = finding.ruleCode,
						ruleCode = finding.ruleCode,
						severity = finding.severity,
						message = finding.message,
						explanation = finding.explanation,
						line = finding.line,
					})
				end
				if source:find("TODO", 1, true) then
					table.insert(issues, { path = fullPath(inst), message = "Contains TODO marker" })
				end
				if source:find("while true do", 1, true) and not source:find("task.wait", 1, true) then
					table.insert(issues, { path = fullPath(inst), message = "Possible unthrottled while true loop" })
				end
			end
		end
		for _, child in ipairs(inst:GetChildren()) do
			scan(child)
		end
	end
	scan(game)
	return { checkedScripts = checked, issues = issues, ok = #issues == 0 }
end

parseLuau = function(payload)
	local source = tostring(payload.source or "")
	local path = tostring(payload.path or "")
	if source == "" and path ~= "" then
		local inst = resolvePath(path)
		if inst and SCRIPT_CLASSES[inst.ClassName] then
			local ok, existing = readScriptSource(inst)
			if ok then
				source = existing
			end
		end
	end
	local diagnostics = {}
	if source:gsub("%s+", "") == "" then
		table.insert(diagnostics, { severity = "error", message = "Source is empty" })
	end
	if source:find("```", 1, true) then
		table.insert(diagnostics, { severity = "error", message = "Source contains markdown fence" })
	end
	if source:find("<file", 1, true) or source:find("</file>", 1, true) then
		table.insert(diagnostics, { severity = "error", message = "Source contains leaked file markup" })
	end
	local scanSource = ScriptContextGuard.stripCommentsAndStrings(source)
	local balance = 0
	for token in scanSource:gmatch("[%(%)]") do
		if token == "(" then
			balance = balance + 1
		else
			balance = balance - 1
		end
		if balance < 0 then
			table.insert(diagnostics, { severity = "warning", message = "Possible unmatched closing parenthesis" })
			break
		end
	end
	if balance > 0 then
		table.insert(diagnostics, { severity = "warning", message = "Possible unmatched opening parenthesis" })
	end
	local hasError = false
	for _, diagnostic in ipairs(diagnostics) do
		if diagnostic.severity == "error" then
			hasError = true
			break
		end
	end
	return {
		path = path ~= "" and path or nil,
		ok = not hasError,
		diagnostics = diagnostics,
		sourceHash = stableHash(source),
		sourceLength = #source,
	}
end

ensureCleanFolder = function(parent, folderName, snapshots)
	local existing = parent:FindFirstChild(folderName)
	if existing then
		if snapshots then
			appendSnapshotTree(existing, snapshots)
		end
		existing:Destroy()
	elseif snapshots then
		table.insert(snapshots, snapshotInstance(fullPath(parent) .. "/" .. folderName))
	end
	local folder = Instance.new("Folder")
	folder.Name = folderName
	folder.Parent = parent
	return folder
end

-- Lightweight pre-apply Luau sanity check. Studio plugins can't compile Luau
-- from a string, so this is a conservative static check (only high-confidence
-- problems) whose diagnostics are reported back to the backend.
validateLuauSource = function(source)
	local issues = {}
	local src = tostring(source or "")
	if src:gsub("%s+", "") == "" then
		table.insert(issues, "empty source")
		return false, issues
	end
	if src:find("```", 1, true) then
		table.insert(issues, "contains markdown code fence (```)")
	end
	if src:find("<file", 1, true) or src:find("</file>", 1, true) then
		table.insert(issues, "contains leaked <file> tag")
	end
	if src:find("TODO", 1, true) or src:find("your code here", 1, true) then
		table.insert(issues, "contains placeholder / TODO text")
	end
	return #issues == 0, issues
end

function ScriptContextGuard.resolveScriptClassName(className)
	return tostring(className or "")
end

function ScriptContextGuard.validateScriptDescriptors(descriptors)
	local findings = {}
	local contexts = {}
	for _, descriptor in ipairs(descriptors or {}) do
		local validation = ScriptContextGuard.validate(descriptor)
		contexts[validation.requiredContext or "unknown"] = true
		for _, finding in ipairs(validation.findings or {}) do
			table.insert(findings, finding)
		end
	end
	local requiredContext = "unknown"
	if contexts.mixed then
		requiredContext = "mixed"
	elseif contexts.client and contexts.server then
		requiredContext = "unknown"
	elseif contexts.client then
		requiredContext = "client"
	elseif contexts.server then
		requiredContext = "server"
	elseif contexts.module then
		requiredContext = "module"
	end
	return {
		ok = #findings == 0,
		status = #findings == 0 and "valid" or "blocked",
		requiredContext = requiredContext,
		findings = findings,
		adjustments = {},
	}
end

local function applyArtifactLegacy(payload)
	local projectName = payload.projectName or "NexusRBX_Project"
	local serviceFolders = {}
	local fileResults = {}
	local validationFailures = 0
	local snapshots = {}
	local contextDescriptors = {}
	for _, scriptSpec in ipairs(payload.scripts or {}) do
		local serviceName = tostring(scriptSpec.service or "")
		local className = ScriptContextGuard.resolveScriptClassName(scriptSpec.className)
		local name = tostring(scriptSpec.name or className)
		table.insert(contextDescriptors, {
			className = className,
			path = serviceName ~= "" and (serviceName .. "/" .. projectName .. "/" .. name) or "",
			source = scriptSpec.source,
		})
	end
	local contextValidation = ScriptContextGuard.validateScriptDescriptors(contextDescriptors)
	if not contextValidation.ok then
		return ScriptContextGuard.failure(contextValidation)
	end

	local executionOk, executionErr = pcall(function()
		for _, scriptSpec in ipairs(payload.scripts or {}) do
			local serviceName = tostring(scriptSpec.service)
			local serviceRoot = getServiceRoot(serviceName)
			if not serviceFolders[serviceName] then
				serviceFolders[serviceName] = ensureCleanFolder(serviceRoot, projectName, snapshots)
			end
			local name = scriptSpec.name or scriptSpec.className
			local valid, issues = validateLuauSource(scriptSpec.source)
			if not valid then
				validationFailures = validationFailures + 1
			end
			local applyOk, applyErr = pcall(function()
				local inst = Instance.new(ScriptContextGuard.resolveScriptClassName(scriptSpec.className))
				inst.Name = name
				inst.Parent = serviceFolders[serviceName]
				local ok, err = writeScriptSource(inst, scriptSpec.source or "")
				if not ok then
					error(err or "Could not write script source")
				end
			end)
			table.insert(fileResults, {
				name = name,
				service = serviceName,
				ok = applyOk,
				valid = valid,
				issues = issues,
				error = (not applyOk) and tostring(applyErr) or nil,
			})
			if not applyOk then
				error(applyErr or ("Could not apply " .. tostring(name)))
			end
		end

		if #(payload.remotes or {}) > 0 then
			local remoteFolder =
				serviceFolders["ReplicatedStorage"] or ensureCleanFolder(Services.ReplicatedStorage, projectName, snapshots)
			for _, remoteSpec in ipairs(payload.remotes or {}) do
				local remote = Instance.new(remoteSpec.className == "RemoteFunction" and "RemoteFunction" or "RemoteEvent")
				remote.Name = remoteSpec.name or remote.ClassName
				remote.Parent = remoteFolder
			end
		end
		for _, screenSpec in ipairs(payload.screenGuis or {}) do
			local screenPath = "StarterGui/" .. (screenSpec.name or "NexusRBXScreen")
			local existing = resolvePath(screenPath)
			if existing then
				appendSnapshotTree(existing, snapshots)
			else
				appendMissingPathSnapshots(screenPath, snapshots, {})
			end
			createOrReplaceInstance(screenPath, "ScreenGui", {
				ResetOnSpawn = screenSpec.resetOnSpawn ~= false,
				IgnoreGuiInset = screenSpec.ignoreGuiInset ~= false,
			}, true)
		end
	end)

	if not executionOk then
		return rollbackMutation(snapshots, "apply_artifact_failed", executionErr, {
			files = fileResults,
			validation = { failures = math.max(1, validationFailures), total = #(payload.scripts or {}) },
		})
	end
	return {
		ok = true,
		scripts = #(payload.scripts or {}),
		remotes = #(payload.remotes or {}),
		screenGuis = #(payload.screenGuis or {}),
		warnings = payload.warnings or {},
		files = fileResults,
		validation = { failures = validationFailures, total = #(payload.scripts or {}) },
		snapshots = snapshots,
	}
end

local function leafNameFromPath(path)
	local parts = splitPath(path)
	return parts[#parts] or ""
end

local function buildManagedIndexes(payload)
	local fileById = {}
	local fileByPath = {}
	local manifestById = {}
	local manifestByPath = {}
	local preconditionsByFileId = {}
	local preconditionsByPath = {}

	for _, file in ipairs(payload.files or {}) do
		local fileId = tostring(file.fileId or file.id or "")
		local path = tostring(file.path or "")
		local entry = {
			fileId = fileId,
			path = path,
			placement = file.placement,
			kind = file.kind,
			content = file.content or "",
			className = ScriptContextGuard.resolveScriptClassName(file.className),
			name = file.name or leafNameFromPath(path),
			allowClassChange = file.allowClassChange == true,
			inspectedClassName = ScriptContextGuard.resolveScriptClassName(file.inspectedClassName),
			expectedSourceHash = tostring(file.expectedSourceHash or ""),
		}
		if fileId ~= "" then
			fileById[fileId] = entry
		end
		if path ~= "" then
			fileByPath[path] = entry
		end
	end

	for _, file in ipairs(payload.managedManifest or {}) do
		local fileId = tostring(file.fileId or "")
		local path = tostring(file.canonicalPath or "")
		if fileId ~= "" then
			manifestById[fileId] = file
		end
		if path ~= "" then
			manifestByPath[path] = file
		end
	end

	for _, item in ipairs(payload.studioPreconditions or {}) do
		local fileId = tostring(item.fileId or "")
		local path = tostring(item.path or "")
		if fileId ~= "" then
			preconditionsByFileId[fileId] = item
		end
		if path ~= "" then
			preconditionsByPath[path] = item
		end
	end

	return {
		fileById = fileById,
		fileByPath = fileByPath,
		manifestById = manifestById,
		manifestByPath = manifestByPath,
		preconditionsByFileId = preconditionsByFileId,
		preconditionsByPath = preconditionsByPath,
	}
end

function ScriptContextGuard.validateManagedScriptContexts(payload, indexes)
	local descriptors = {}
	for _, file in ipairs(payload.files or {}) do
		table.insert(descriptors, {
			className = ScriptContextGuard.resolveScriptClassName(file.className),
			path = tostring(file.path or file.placement or ""),
			source = file.content,
		})
	end
	for _, op in ipairs(payload.operations or {}) do
		local opType = tostring(op.type or "")
		if opType == "upsert" then
			local spec = indexes.fileById[tostring(op.id or "")] or indexes.fileByPath[tostring(op.path or "")]
			table.insert(descriptors, {
				className = spec and spec.className or "",
				path = tostring(op.path or (spec and spec.path) or ""),
				source = spec and spec.content or "",
			})
		elseif opType == "rename" then
			local spec = indexes.fileById[tostring(op.id or "")] or indexes.fileByPath[tostring(op.toPath or "")]
			local manifestEntry = indexes.manifestById[tostring(op.id or "")]
				or indexes.manifestByPath[tostring(op.fromPath or "")]
			table.insert(descriptors, {
				className = ScriptContextGuard.resolveScriptClassName(
					(spec and spec.className) or (manifestEntry and manifestEntry.className)
				),
				path = tostring(op.toPath or ""),
				source = spec and spec.content or "",
			})
		end
	end
	return ScriptContextGuard.validateScriptDescriptors(descriptors)
end

local function validateManagedOperations(operations)
	local errors = {}
	local targetPaths = {}
	local renameSources = {}
	local deleteTargets = {}
	-- Collect the complete graph before checking conflicts: execution is phased,
	-- so input ordering must not affect whether a batch is valid.
	for index, op in ipairs(operations or {}) do
		local opType = tostring(op.type or "")
		if opType == "upsert" then
			local targetPath = tostring(op.path or "")
			if targetPath == "" then
				table.insert(errors, ("Upsert %d is missing path"):format(index))
			elseif targetPaths[targetPath] then
				table.insert(errors, "Duplicate target path: " .. targetPath)
			else
				targetPaths[targetPath] = true
			end
		elseif opType == "rename" then
			local fromPath = tostring(op.fromPath or "")
			local toPath = tostring(op.toPath or "")
			if fromPath == "" or toPath == "" then
				table.insert(errors, ("Rename %d is missing paths"):format(index))
			elseif fromPath == toPath then
				table.insert(errors, ("Rename %d does not change path"):format(index))
			else
				if renameSources[fromPath] then
					table.insert(errors, "Duplicate rename source: " .. fromPath)
				end
				if targetPaths[toPath] then
					table.insert(errors, "Duplicate target path: " .. toPath)
				end
				renameSources[fromPath] = true
				targetPaths[toPath] = true
			end
		elseif opType == "delete" then
			local targetPath = tostring(op.path or "")
			if targetPath == "" then
				table.insert(errors, ("Delete %d is missing path"):format(index))
			elseif deleteTargets[targetPath] then
				table.insert(errors, "Duplicate delete path: " .. targetPath)
			else
				deleteTargets[targetPath] = true
			end
		else
			table.insert(errors, ("Unsupported operation type: %s"):format(opType))
		end
	end
	for sourcePath in pairs(renameSources) do
		if deleteTargets[sourcePath] then
			table.insert(errors, "Conflicting rename/delete for " .. sourcePath)
		end
	end
	for deletePath in pairs(deleteTargets) do
		if targetPaths[deletePath] then
			table.insert(errors, "Conflicting delete/write target: " .. deletePath)
		end
	end
	return errors
end

local function snapshotOnce(target, snapshots, seenPaths)
	local path = typeof(target) == "Instance" and fullPath(target) or tostring(target or "")
	if path == "" or seenPaths[path] then
		return
	end
	if typeof(target) == "Instance" then
		seenPaths[path] = true
		appendSnapshotTree(target, snapshots)
	else
		local existing = resolvePath(path)
		if existing then
			seenPaths[path] = true
			appendSnapshotTree(existing, snapshots)
		else
			appendMissingPathSnapshots(path, snapshots, seenPaths)
		end
	end
end

local function findManagedInstanceByFileId(fileId, expectedClass)
	if not fileId or fileId == "" then
		return nil, nil
	end
	local matches = {}
	for _, inst in ipairs(game:GetDescendants()) do
		if inst:GetAttribute(AGENT_FILE_ID_ATTRIBUTE) == fileId
			and (not expectedClass or inst.ClassName == expectedClass) then
			table.insert(matches, inst)
		end
	end
	if #matches == 1 then
		return matches[1], nil
	end
	if #matches > 1 then
		return nil, "ambiguous"
	end
	return nil, nil
end

function ScriptContextGuard.managedClassChangeCredentials(spec, indexes)
	local fileId = tostring(spec.fileId or spec.id or "")
	local precondition = indexes.preconditionsByFileId[fileId]
		or indexes.preconditionsByPath[tostring(spec.path or "")]
	local inspectedClassName = tostring(spec.inspectedClassName or "")
	if inspectedClassName == "" and precondition then
		inspectedClassName = tostring(precondition.className or "")
	end
	local expectedSourceHash = tostring(spec.expectedSourceHash or "")
	if expectedSourceHash == "" and precondition then
		expectedSourceHash = tostring(precondition.sourceHash or "")
	end
	return {
		allowed = spec.allowClassChange == true,
		inspectedClassName = ScriptContextGuard.resolveScriptClassName(inspectedClassName),
		expectedSourceHash = expectedSourceHash,
	}
end

function ScriptContextGuard.canChangeManagedClass(spec, indexes, inst, expectedClass)
	if not inst or inst.ClassName == expectedClass then
		return true
	end
	local credentials = ScriptContextGuard.managedClassChangeCredentials(spec, indexes)
	return credentials.allowed
		and credentials.inspectedClassName == inst.ClassName
		and credentials.expectedSourceHash ~= ""
end

local function findUniqueLeafMatch(path, expectedClass)
	local parent, leaf = ensureParent(path, false)
	if not parent or not leaf then
		return nil, nil
	end
	local matches = {}
	for _, child in ipairs(parent:GetChildren()) do
		if child.Name == leaf and child.ClassName == expectedClass then
			table.insert(matches, child)
		end
	end
	if #matches == 1 then
		return matches[1], nil
	end
	if #matches > 1 then
		return nil, "ambiguous"
	end
	return nil, nil
end

local function resolveManagedTarget(spec, indexes, currentPathOverride)
	local fileId = tostring(spec.fileId or spec.id or "")
	local expectedClass = ScriptContextGuard.resolveScriptClassName(spec.className)
	local canonicalPath = tostring(currentPathOverride or spec.path or "")
	if not SCRIPT_CLASSES[expectedClass] then
		return {
			ok = false,
			code = "SCRIPT_CONTEXT_MISMATCH",
			message = "Managed script is missing an explicit className",
		}
	end
	local attrMatch, attrError = findManagedInstanceByFileId(fileId, nil)
	if attrError == "ambiguous" then
		return { ok = false, code = "ambiguous", message = "Multiple Studio instances share the same AgentFileId" }
	end
	if attrMatch then
		if not ScriptContextGuard.canChangeManagedClass(spec, indexes, attrMatch, expectedClass) then
			return {
				ok = false,
				code = "SCRIPT_CONTEXT_MISMATCH",
				message = "Changing an existing managed script class requires allowClassChange, the inspected class, and the inspected source hash.",
			}
		end
		return { ok = true, instance = attrMatch, expectedClass = expectedClass, matchType = "file_id" }
	end

	local exact = canonicalPath ~= "" and resolvePath(canonicalPath) or nil
	if exact then
		if not SCRIPT_CLASSES[exact.ClassName] then
			return {
				ok = false,
				code = "class_mismatch",
				message = ("Expected %s at %s but found %s"):format(expectedClass, canonicalPath, exact.ClassName),
			}
		end
		if not ScriptContextGuard.canChangeManagedClass(spec, indexes, exact, expectedClass) then
			return {
				ok = false,
				code = "SCRIPT_CONTEXT_MISMATCH",
				message = "Changing an existing managed script class requires allowClassChange, the inspected class, and the inspected source hash.",
			}
		end
		return { ok = true, instance = exact, expectedClass = expectedClass, matchType = "canonical_path" }
	end

	local leafMatch, leafError = findUniqueLeafMatch(canonicalPath, expectedClass)
	if leafError == "ambiguous" then
		return {
			ok = false,
			code = "ambiguous",
			message = ("Ambiguous Studio leaf-name match for %s"):format(canonicalPath),
		}
	end
	if leafMatch then
		return { ok = true, instance = leafMatch, expectedClass = expectedClass, matchType = "leaf_name" }
	end

	return { ok = true, instance = nil, expectedClass = expectedClass, matchType = "create" }
end

local function checkStudioPreconditions(inst, spec, manifestEntry, indexes)
	if not inst or not SCRIPT_CLASSES[inst.ClassName] then
		return true, nil, nil
	end
	local ok, source = readScriptSource(inst)
	if not ok then
		return false, "Could not read Studio script source", nil
	end
	local currentHash = stableHash(source)
	local fileId = tostring(spec.fileId or spec.id or "")
	local precondition = indexes.preconditionsByFileId[fileId] or indexes.preconditionsByPath[tostring(spec.path or "")]
	local credentials = ScriptContextGuard.managedClassChangeCredentials(spec, indexes)
	if credentials.expectedSourceHash ~= "" and credentials.expectedSourceHash ~= currentHash then
		return false, "Studio source hash no longer matches the inspected target", currentHash
	end
	if precondition and tostring(precondition.sourceHash or "") ~= "" and tostring(precondition.sourceHash) ~= currentHash then
		return false, "Studio source precondition hash mismatch", currentHash
	end
	if manifestEntry and tostring(manifestEntry.lastAppliedSourceHash or "") ~= "" and tostring(manifestEntry.lastAppliedSourceHash) ~= currentHash then
		return false, "Studio source changed independently since the last managed apply", currentHash
	end
	return true, nil, currentHash
end

local function waitForExpectedScriptSource(inst, expectedSource)
	local expectedHash = stableHash(expectedSource)
	local lastHash = nil
	for attempt = 1, 6 do
		local ok, source = readScriptSource(inst)
		if ok then
			lastHash = stableHash(source)
			if lastHash == expectedHash then
				return true, expectedHash
			end
		end
		if attempt < 6 then
			task.wait(0.05)
		end
	end
	return false, lastHash, expectedHash
end

local function applyManagedUpsert(spec, resolved, indexes, snapshots, seenPaths)
	local targetPath = tostring(spec.path or "")
	local expectedClass = ScriptContextGuard.resolveScriptClassName(spec.className)
	if not SCRIPT_CLASSES[expectedClass] then
		return nil, "Managed upsert is missing an explicit className"
	end
	local inst = resolved.instance
	local manifestEntry = indexes.manifestById[tostring(spec.fileId or spec.id or "")] or indexes.manifestByPath[targetPath]
	if inst then
		local ok, preconditionError = checkStudioPreconditions(inst, spec, manifestEntry, indexes)
		if not ok then
			return nil, preconditionError
		end
		snapshotOnce(inst, snapshots, seenPaths)
		if inst.ClassName ~= expectedClass then
			if not ScriptContextGuard.canChangeManagedClass(spec, indexes, inst, expectedClass) then
				return nil, "Managed script class conversion is not authorized"
			end
			local previous = inst
			local previousParent = previous.Parent
			local previousName = previous.Name
			local previousAttributes = previous:GetAttributes()
			previous:Destroy()
			inst = Instance.new(expectedClass)
			inst.Name = previousName
			for attributeName, attributeValue in pairs(previousAttributes) do
				inst:SetAttribute(attributeName, attributeValue)
			end
			inst.Parent = previousParent
		end
	else
		snapshotOnce(targetPath, snapshots, seenPaths)
		local parent, leaf = ensureParent(targetPath, true)
		if not parent or not leaf then
			return nil, "Could not resolve parent for " .. targetPath
		end
		inst = Instance.new(expectedClass)
		inst.Name = leaf
		inst.Parent = parent
	end

	if inst.ClassName ~= expectedClass then
		return nil, ("Expected %s but found %s"):format(expectedClass, inst.ClassName)
	end

	inst:SetAttribute(AGENT_ARTIFACT_ID_ATTRIBUTE, tostring(spec.artifactId or ""))
	inst:SetAttribute(AGENT_FILE_ID_ATTRIBUTE, tostring(spec.fileId or spec.id or ""))
	local parent, leaf = ensureParent(targetPath, true)
	if not parent or not leaf then
		return nil, "Could not resolve parent for " .. targetPath
	end
	inst.Name = leaf
	inst.Parent = parent
	local wrote, writeErr = writeScriptSource(inst, spec.content or "")
	if not wrote then
		return nil, writeErr or "Could not update Studio script source"
	end
	local readbackOk, appliedHash, expectedHash = waitForExpectedScriptSource(inst, tostring(spec.content or ""))
	if not readbackOk then
		return nil, ("Studio source did not settle to the applied content (expected %s, read %s)"):format(
			tostring(expectedHash or ""),
			tostring(appliedHash or "unavailable")
		)
	end
	return inst, nil, appliedHash
end

local function buildManagedFileRecord(inst, spec, knownSourceHash)
	local ok, source = readScriptSource(inst)
	local sourceText = ok and source or (spec.content or "")
	return {
		fileId = tostring(spec.fileId or spec.id or ""),
		canonicalPath = tostring(spec.path or fullPath(inst)),
		placement = tostring(spec.placement or ""),
		kind = tostring(spec.kind or "module"),
		className = inst.ClassName,
		lastAppliedSourceHash = knownSourceHash or stableHash(sourceText),
		lastResolvedStudioPath = fullPath(inst),
	}
end

UiArtifact = {}
UiArtifact.NODE_CLASSES = {
	Frame = true,
	TextLabel = true,
	TextButton = true,
	ImageLabel = true,
	ImageButton = true,
	TextBox = true,
	ScrollingFrame = true,
}

UiArtifact.color = function(hex, fallback)
	local value = tostring(hex or "")
	if not value:match("^#%x%x%x%x%x%x$") then
		return fallback or Color3.new(1, 1, 1)
	end
	return Color3.fromRGB(
		tonumber(value:sub(2, 3), 16),
		tonumber(value:sub(4, 5), 16),
		tonumber(value:sub(6, 7), 16)
	)
end

UiArtifact.udim2 = function(value)
	value = type(value) == "table" and value or {}
	local x = type(value.x) == "table" and value.x or {}
	local y = type(value.y) == "table" and value.y or {}
	return UDim2.new(tonumber(x.scale) or 0, tonumber(x.offset) or 0, tonumber(y.scale) or 0, tonumber(y.offset) or 0)
end

UiArtifact.applyProperties = function(inst, properties, order)
	properties = type(properties) == "table" and properties or {}
	local ok, err = pcall(function()
		inst.Position = UiArtifact.udim2(properties.position)
		inst.Size = UiArtifact.udim2(properties.size)
		inst.AnchorPoint = Vector2.new(
			tonumber(properties.anchorPoint and properties.anchorPoint.x) or 0,
			tonumber(properties.anchorPoint and properties.anchorPoint.y) or 0
		)
		inst.BackgroundColor3 = UiArtifact.color(properties.backgroundColor, Color3.fromRGB(36, 31, 37))
		inst.BackgroundTransparency = tonumber(properties.backgroundTransparency) or 0
		inst.Visible = properties.visible ~= false
		inst.ClipsDescendants = properties.clipsDescendants == true
		inst.Rotation = tonumber(properties.rotation) or 0
		inst.ZIndex = tonumber(properties.zIndex) or 1
		inst.LayoutOrder = tonumber(order) or 0
		inst.BorderSizePixel = 0
		if inst:IsA("TextLabel") or inst:IsA("TextButton") or inst:IsA("TextBox") then
			inst.Text = tostring(properties.text or "")
			inst.TextColor3 = UiArtifact.color(properties.textColor, Color3.new(1, 1, 1))
			inst.TextSize = tonumber(properties.textSize) or 18
			inst.TextWrapped = properties.textWrapped ~= false
			inst.TextXAlignment = Enum.TextXAlignment[tostring(properties.textXAlignment or "Center")] or Enum.TextXAlignment.Center
			inst.TextYAlignment = Enum.TextYAlignment[tostring(properties.textYAlignment or "Center")] or Enum.TextYAlignment.Center
			inst.TextTransparency = tonumber(properties.textTransparency) or 0
			inst.Font = Enum.Font[tostring(properties.font or "Gotham")] or Enum.Font.Gotham
			if inst:IsA("TextBox") then
				inst.PlaceholderText = tostring(properties.placeholderText or "")
			end
		end
		if inst:IsA("TextButton") or inst:IsA("ImageButton") then
			inst.AutoButtonColor = false
		end
		if inst:IsA("ImageLabel") or inst:IsA("ImageButton") then
			inst.Image = tostring(properties.image or "")
			inst.ImageColor3 = UiArtifact.color(properties.imageColor, Color3.new(1, 1, 1))
			inst.ImageTransparency = tonumber(properties.imageTransparency) or 0
			inst.ScaleType = Enum.ScaleType[tostring(properties.scaleType or "Fit")] or Enum.ScaleType.Fit
		end
		if inst:IsA("ScrollingFrame") then
			inst.CanvasSize = UiArtifact.udim2(properties.canvasSize)
			inst.AutomaticCanvasSize = Enum.AutomaticSize[tostring(properties.automaticCanvasSize or "Y")] or Enum.AutomaticSize.Y
			inst.ScrollBarThickness = tonumber(properties.scrollBarThickness) or 6
		end
	end)
	return ok, ok and nil or tostring(err)
end

UiArtifact.applyDecorators = function(inst, spec)
	local style = type(spec.style) == "table" and spec.style or {}
	local layout = type(spec.layout) == "table" and spec.layout or nil
	local constraints = type(spec.constraints) == "table" and spec.constraints or {}
	local ok, err = pcall(function()
		if (tonumber(style.cornerRadius) or 0) > 0 then
			local corner = Instance.new("UICorner")
			corner.Name = "NexusCorner"
			corner.CornerRadius = UDim.new(0, tonumber(style.cornerRadius) or 0)
			corner.Parent = inst
		end
		if type(style.stroke) == "table" then
			local stroke = Instance.new("UIStroke")
			stroke.Name = "NexusStroke"
			stroke.Color = UiArtifact.color(style.stroke.color, Color3.new(1, 1, 1))
			stroke.Thickness = tonumber(style.stroke.thickness) or 1
			stroke.Transparency = tonumber(style.stroke.transparency) or 0
			stroke.Parent = inst
		end
		if type(style.gradient) == "table" then
			local gradient = Instance.new("UIGradient")
			gradient.Name = "NexusGradient"
			gradient.Color = ColorSequence.new({
				ColorSequenceKeypoint.new(0, UiArtifact.color(style.gradient.from, Color3.new(0, 0, 0))),
				ColorSequenceKeypoint.new(1, UiArtifact.color(style.gradient.to, Color3.new(1, 1, 1))),
			})
			gradient.Rotation = tonumber(style.gradient.rotation) or 90
			gradient.Parent = inst
		end
		if type(style.padding) == "table" then
			local padding = Instance.new("UIPadding")
			padding.Name = "NexusPadding"
			padding.PaddingTop = UDim.new(0, tonumber(style.padding.top) or 0)
			padding.PaddingRight = UDim.new(0, tonumber(style.padding.right) or 0)
			padding.PaddingBottom = UDim.new(0, tonumber(style.padding.bottom) or 0)
			padding.PaddingLeft = UDim.new(0, tonumber(style.padding.left) or 0)
			padding.Parent = inst
		end
		if layout then
			if layout.type == "grid" then
				local grid = Instance.new("UIGridLayout")
				grid.Name = "NexusGridLayout"
				grid.CellSize = UiArtifact.udim2(layout.cellSize)
				grid.CellPadding = UDim2.fromOffset(tonumber(layout.padding) or 0, tonumber(layout.padding) or 0)
				grid.HorizontalAlignment = Enum.HorizontalAlignment[tostring(layout.horizontalAlignment or "Left")] or Enum.HorizontalAlignment.Left
				grid.VerticalAlignment = Enum.VerticalAlignment[tostring(layout.verticalAlignment or "Top")] or Enum.VerticalAlignment.Top
				grid.Parent = inst
			else
				local list = Instance.new("UIListLayout")
				list.Name = "NexusListLayout"
				list.FillDirection = layout.direction == "horizontal" and Enum.FillDirection.Horizontal or Enum.FillDirection.Vertical
				list.Padding = UDim.new(0, tonumber(layout.padding) or 0)
				list.HorizontalAlignment = Enum.HorizontalAlignment[tostring(layout.horizontalAlignment or "Left")] or Enum.HorizontalAlignment.Left
				list.VerticalAlignment = Enum.VerticalAlignment[tostring(layout.verticalAlignment or "Top")] or Enum.VerticalAlignment.Top
				list.SortOrder = Enum.SortOrder.LayoutOrder
				list.Parent = inst
			end
		end
		if constraints.aspectRatio then
			local aspect = Instance.new("UIAspectRatioConstraint")
			aspect.Name = "NexusAspectConstraint"
			aspect.AspectRatio = tonumber(constraints.aspectRatio) or 1
			aspect.Parent = inst
		end
		if type(constraints.minSize) == "table" or type(constraints.maxSize) == "table" then
			local sizeConstraint = Instance.new("UISizeConstraint")
			sizeConstraint.Name = "NexusSizeConstraint"
			if type(constraints.minSize) == "table" then
				sizeConstraint.MinSize = Vector2.new(
					tonumber(constraints.minSize.x and constraints.minSize.x.offset) or 0,
					tonumber(constraints.minSize.y and constraints.minSize.y.offset) or 0
				)
			end
			if type(constraints.maxSize) == "table" then
				sizeConstraint.MaxSize = Vector2.new(
					tonumber(constraints.maxSize.x and constraints.maxSize.x.offset) or 100000,
					tonumber(constraints.maxSize.y and constraints.maxSize.y.offset) or 100000
				)
			end
			sizeConstraint.Parent = inst
		end
		if constraints.textSizeMin or constraints.textSizeMax then
			local textConstraint = Instance.new("UITextSizeConstraint")
			textConstraint.Name = "NexusTextConstraint"
			textConstraint.MinTextSize = tonumber(constraints.textSizeMin) or 1
			textConstraint.MaxTextSize = tonumber(constraints.textSizeMax) or 100
			textConstraint.Parent = inst
			if inst:IsA("TextLabel") or inst:IsA("TextButton") or inst:IsA("TextBox") then
				inst.TextScaled = true
			end
		end
		if tonumber(spec.properties and spec.properties.uiScale) and tonumber(spec.properties.uiScale) ~= 1 then
			local scale = Instance.new("UIScale")
			scale.Name = "NexusScale"
			scale.Scale = tonumber(spec.properties.uiScale)
			scale.Parent = inst
		end
	end)
	return ok, ok and nil or tostring(err)
end

UiArtifact.treeHash = function(root)
	local rows = {}
	local instances = { root }
	for _, descendant in ipairs(root:GetDescendants()) do
		table.insert(instances, descendant)
	end
	for _, inst in ipairs(instances) do
		local values = {
			fullPath(inst),
			inst.ClassName,
			tostring(inst:GetAttribute(AGENT_ARTIFACT_ID_ATTRIBUTE) or ""),
			tostring(inst:GetAttribute(AGENT_FILE_ID_ATTRIBUTE) or ""),
			tostring(inst:GetAttribute("NexusRootId") or ""),
			tostring(inst:GetAttribute("NexusNodeId") or ""),
			tostring(inst:GetAttribute("NexusDesignId") or ""),
			tostring(inst:GetAttribute("NexusRevision") or ""),
			tostring(inst:GetAttribute("NexusDesiredTreeHash") or ""),
		}
		for _, propertyName in ipairs({
			"ResetOnSpawn", "IgnoreGuiInset", "DisplayOrder", "Enabled",
			"Position", "Size", "AnchorPoint", "BackgroundColor3", "BackgroundTransparency", "Visible",
			"ClipsDescendants", "Rotation", "ZIndex", "LayoutOrder", "BorderSizePixel",
			"Text", "PlaceholderText", "TextColor3", "TextSize", "TextWrapped", "TextScaled",
			"TextXAlignment", "TextYAlignment", "TextTransparency", "Font",
			"Image", "ImageColor3", "ImageTransparency", "ScaleType", "AutoButtonColor",
			"CanvasSize", "AutomaticCanvasSize", "ScrollBarThickness",
			"CornerRadius", "Color", "Transparency", "Thickness",
			"Padding", "PaddingTop", "PaddingRight", "PaddingBottom", "PaddingLeft",
			"FillDirection", "HorizontalAlignment", "VerticalAlignment", "SortOrder", "CellSize", "CellPadding",
			"AspectRatio", "MinSize", "MaxSize", "MinTextSize", "MaxTextSize", "Scale",
		}) do
			local propertyOk, propertyValue = pcall(function()
				return inst[propertyName]
			end)
			if propertyOk then
				table.insert(values, propertyName .. "=" .. tostring(propertyValue))
			end
		end
		if SCRIPT_CLASSES[inst.ClassName] then
			table.insert(values, "SourceHash=" .. tostring(scriptHash(inst) or ""))
		end
		table.insert(rows, table.concat(values, "|"))
	end
	table.sort(rows)
	return stableHash(table.concat(rows, "\n"))
end

UiArtifact.preflightRoot = function(rootSpec, artifactId)
	local targetPath = tostring(rootSpec.targetPath or "")
	if not targetPath:match("^StarterGui/NexusRBX_UI/[^/]+$") then
		return { ok = false, code = "ui_root_path_invalid", error = "UI roots must be direct children of StarterGui/NexusRBX_UI", path = targetPath }
	end
	if tostring(rootSpec.rootId or "") == "" or tostring(rootSpec.designId or "") == "" or tostring(rootSpec.documentRevision or "") == "" then
		return { ok = false, code = "ui_root_identity_invalid", error = "UI roots require root, design, and revision identity", path = targetPath }
	end
	if tostring(artifactId or "") == "" or tostring(rootSpec.designId or "") ~= tostring(artifactId or "") then
		return { ok = false, code = "ui_artifact_identity_mismatch", error = "UI root design identity does not match the artifact", path = targetPath }
	end
	local container = resolvePath("StarterGui/NexusRBX_UI")
	if container and (container.ClassName ~= "Folder"
		or (container:GetAttribute("NexusUiContainer") ~= true and #container:GetChildren() > 0)) then
		return {
			ok = false,
			code = "ui_foreign_collision",
			error = "StarterGui/NexusRBX_UI is not an empty or Nexus-managed UI container",
			path = "StarterGui/NexusRBX_UI",
		}
	end
	if #(rootSpec.nodes or {}) > 240 then
		return { ok = false, code = "ui_node_limit_exceeded", error = "UI roots support at most 240 nodes", path = targetPath }
	end
	local byId = {}
	for _, nodeSpec in ipairs(rootSpec.nodes or {}) do
		local nodeId = tostring(nodeSpec.nodeId or "")
		local parentId = tostring(nodeSpec.parentId or "")
		local nodeName = tostring(nodeSpec.name or "")
		if nodeId == "" or byId[nodeId] then
			return { ok = false, code = "ui_node_id_invalid", error = "UI node IDs must be non-empty and unique", path = targetPath }
		end
		if not UiArtifact.NODE_CLASSES[tostring(nodeSpec.className or "")] then
			return { ok = false, code = "ui_node_class_unsupported", error = "Unsupported UI node class", path = targetPath }
		end
		if parentId == "" and (nodeName == "Hooks" or nodeName == "NexusInteractions") then
			return { ok = false, code = "ui_node_name_reserved", error = nodeName .. " is reserved for the generated UI runtime", path = targetPath }
		end
		byId[nodeId] = nodeSpec
	end
	for nodeId, nodeSpec in pairs(byId) do
		local parentId = tostring(nodeSpec.parentId or "")
		local visited = { [nodeId] = true }
		local depth = 0
		while parentId ~= "" do
			if not byId[parentId] then
				return { ok = false, code = "ui_node_parent_invalid", error = "UI node parent does not exist", path = targetPath }
			end
			if visited[parentId] then
				return { ok = false, code = "ui_node_parent_cycle", error = "UI node parent cycle detected", path = targetPath }
			end
			visited[parentId] = true
			depth = depth + 1
			if depth > 32 then
				return { ok = false, code = "ui_node_depth_exceeded", error = "UI node depth exceeds 32", path = targetPath }
			end
			parentId = tostring(byId[parentId].parentId or "")
		end
	end

	local existing = resolvePath(targetPath)
	if not existing then
		return {
			ok = true,
			path = targetPath,
			container = container,
			adoptContainer = container ~= nil and container:GetAttribute("NexusUiContainer") ~= true,
		}
	end
	local identityMatches = existing.ClassName == "ScreenGui"
		and tostring(existing:GetAttribute(AGENT_ARTIFACT_ID_ATTRIBUTE) or "") == tostring(artifactId or "")
		and tostring(existing:GetAttribute("NexusRootId") or "") == tostring(rootSpec.rootId or "")
		and tostring(existing:GetAttribute("NexusDesignId") or "") == tostring(rootSpec.designId or "")
	if not identityMatches then
		return {
			ok = false,
			code = "ui_foreign_collision",
			error = "A non-managed or differently managed instance already exists at the UI root path",
			path = targetPath,
		}
	end
	local expectedTreeHash = tostring(rootSpec.expectedTreeHash or "")
	local actualTreeHash = UiArtifact.treeHash(existing)
	if expectedTreeHash == "" and rootSpec.replaceModifiedRoot ~= true then
		return {
			ok = false,
			code = "ui_tree_precondition_required",
			error = "Keep the Studio copy or explicitly replace it",
			path = targetPath,
			currentTreeHash = actualTreeHash,
		}
	end
	if expectedTreeHash ~= "" and actualTreeHash ~= expectedTreeHash and rootSpec.replaceModifiedRoot ~= true then
		return {
			ok = false,
			code = "ui_tree_conflict",
			error = ("Expected UI tree %s but found %s"):format(expectedTreeHash, actualTreeHash),
			path = targetPath,
			expectedTreeHash = expectedTreeHash,
			currentTreeHash = actualTreeHash,
		}
	end
	return {
		ok = true,
		path = targetPath,
		existing = existing,
		container = container,
		adoptContainer = container ~= nil and container:GetAttribute("NexusUiContainer") ~= true,
		currentTreeHash = actualTreeHash,
	}
end

UiArtifact.applyRoot = function(rootSpec, artifactId, snapshots, seenPaths)
	local targetPath = tostring(rootSpec.targetPath or "")
	local preflight = UiArtifact.preflightRoot(rootSpec, artifactId)
	if not preflight.ok then
		error(tostring(preflight.code or "ui_root_invalid") .. ": " .. tostring(preflight.error or "UI root preflight failed"))
	end
	local existing = preflight.existing
	if preflight.adoptContainer and preflight.container then
		snapshotOnce(preflight.container, snapshots, seenPaths)
	end
	if existing then
		snapshotOnce(existing, snapshots, seenPaths)
		existing:Destroy()
	else
		snapshotOnce(targetPath, snapshots, seenPaths)
	end

	local parent, leaf = ensureParent(targetPath, true)
	if not parent or not leaf then
		error("ui_root_parent_missing: could not create " .. targetPath)
	end
	if parent.ClassName ~= "Folder" then
		error("ui_foreign_collision: StarterGui/NexusRBX_UI is not a Folder")
	end
	parent:SetAttribute("NexusUiContainer", true)
	local root = Instance.new("ScreenGui")
	root.Name = leaf
	root.ResetOnSpawn = rootSpec.properties and rootSpec.properties.resetOnSpawn ~= false
	root.IgnoreGuiInset = rootSpec.properties and rootSpec.properties.ignoreGuiInset ~= false
	root.DisplayOrder = tonumber(rootSpec.properties and rootSpec.properties.displayOrder) or 0
	root.Enabled = not rootSpec.properties or rootSpec.properties.enabled ~= false
	root:SetAttribute(AGENT_ARTIFACT_ID_ATTRIBUTE, tostring(artifactId or ""))
	root:SetAttribute("NexusRootId", tostring(rootSpec.rootId or ""))
	root:SetAttribute("NexusDesignId", tostring(rootSpec.designId or ""))
	root:SetAttribute("NexusRevision", tostring(rootSpec.documentRevision or ""))
	root:SetAttribute("NexusDesiredTreeHash", tostring(rootSpec.treeHash or ""))
	root.Parent = parent

	local byId = {}
	local remaining = {}
	local expectedNodeIds = {}
	for _, nodeSpec in ipairs(rootSpec.nodes or {}) do
		table.insert(remaining, nodeSpec)
		table.insert(expectedNodeIds, tostring(nodeSpec.nodeId or ""))
	end
	table.sort(expectedNodeIds)
	local applied = 0
	while #remaining > 0 do
		local progressed = false
		for index = #remaining, 1, -1 do
			local nodeSpec = remaining[index]
			local parentId = tostring(nodeSpec.parentId or "")
			local nodeParent = parentId == "" and root or byId[parentId]
			if nodeParent then
				if not UiArtifact.NODE_CLASSES[tostring(nodeSpec.className or "")] then
					error("ui_node_class_unsupported: " .. tostring(nodeSpec.className or ""))
				end
				local node = Instance.new(nodeSpec.className)
				node.Name = tostring(nodeSpec.name or nodeSpec.nodeId or nodeSpec.className)
				local propertiesOk, propertiesError = UiArtifact.applyProperties(node, nodeSpec.properties, nodeSpec.order)
				if not propertiesOk then
					error("ui_property_apply_failed: " .. tostring(propertiesError))
				end
				local decoratorOk, decoratorError = UiArtifact.applyDecorators(node, nodeSpec)
				if not decoratorOk then
					error("ui_decorator_apply_failed: " .. tostring(decoratorError))
				end
				node:SetAttribute(AGENT_ARTIFACT_ID_ATTRIBUTE, tostring(artifactId or ""))
				node:SetAttribute("NexusDesignId", tostring(rootSpec.designId or ""))
				node:SetAttribute("NexusNodeId", tostring(nodeSpec.nodeId or ""))
				node:SetAttribute("NexusRevision", tostring(rootSpec.documentRevision or ""))
				node.Parent = nodeParent
				byId[tostring(nodeSpec.nodeId or "")] = node
				table.remove(remaining, index)
				applied = applied + 1
				progressed = true
			end
		end
		if not progressed then
			error("ui_tree_invalid: node parents could not be resolved")
		end
	end

	local appliedTreeHash = UiArtifact.treeHash(root)
	root:SetAttribute("NexusTreeHash", appliedTreeHash)
	return {
		rootId = tostring(rootSpec.rootId or ""),
		designId = tostring(rootSpec.designId or ""),
		artifactId = tostring(artifactId or ""),
		path = fullPath(root),
		nodeCount = applied,
		nodeIds = expectedNodeIds,
		treeHash = appliedTreeHash,
		documentTreeHash = tostring(rootSpec.treeHash or ""),
		expectedPreviousTreeHash = tostring(rootSpec.expectedTreeHash or ""),
		documentRevision = tostring(rootSpec.documentRevision or ""),
	}
end

applyArtifact = function(payload)
	if tonumber(payload.schemaVersion or 1) < 2 then
		return applyArtifactLegacy(payload)
	end

	local operations = payload.operations or {}
	local snapshots = {}
	local seenPaths = {}
	local fileResults = {}
	local indexes = buildManagedIndexes(payload)
	local validationErrors = validateManagedOperations(operations)
	local contextValidation = ScriptContextGuard.validateManagedScriptContexts(payload, indexes)
	local managedFiles = {}
	local finalFiles = {}
	local uiRootResults = {}
	local totalChanges = #operations + #(payload.uiRoots or {})
	local completedChanges = 0
	local function reportProgress(phase, operation, path, message)
		if type(payload._reportProgress) ~= "function" then return end
		pcall(payload._reportProgress, {
			phase = phase,
			operation = operation,
			path = tostring(path or ""),
			message = tostring(message or ""),
			completed = completedChanges,
			total = totalChanges,
		})
	end
	local function reportApplied(operation, path)
		completedChanges = completedChanges + 1
		reportProgress("applying", operation, path, "")
	end

	for _, spec in pairs(indexes.fileById) do
		table.insert(finalFiles, spec)
	end
	if not contextValidation.ok then
		return ScriptContextGuard.failure(contextValidation)
	end
	if #validationErrors > 0 then
		return {
			ok = false,
			error = table.concat(validationErrors, " | "),
			files = fileResults,
			validation = { failures = #validationErrors, total = #operations },
			snapshots = snapshots,
		}
	end
	for _, rootSpec in ipairs(payload.uiRoots or {}) do
		local preflight = UiArtifact.preflightRoot(rootSpec, payload.artifactId)
		if not preflight.ok then
			return {
				ok = false,
				code = tostring(preflight.code or "ui_root_invalid"),
				error = tostring(preflight.error or "UI root preflight failed"),
				retryable = false,
				files = fileResults,
				managedFiles = {},
				uiRoots = {
					{
						rootId = tostring(rootSpec.rootId or ""),
						designId = tostring(rootSpec.designId or ""),
						path = tostring(preflight.path or rootSpec.targetPath or ""),
						expectedTreeHash = preflight.expectedTreeHash,
						currentTreeHash = preflight.currentTreeHash,
					},
				},
				validation = { failures = 1, total = #operations + #(payload.uiRoots or {}) },
				snapshots = snapshots,
			}
		end
	end

	local function pushResult(base, ok, err)
		local row = base
		row.ok = ok
		if not ok then
			row.error = tostring(err or "Unknown Studio apply failure")
		end
		table.insert(fileResults, row)
		if ok then
			reportApplied(tostring(row.type or "operation"), tostring(row.toPath or row.path or ""))
		end
	end

	reportProgress("applying", "start", "", "Applying validated Studio changes")
	local executionOk, executionErr = pcall(function()
		for _, rootSpec in ipairs(payload.uiRoots or {}) do
			local uiResult = UiArtifact.applyRoot(rootSpec, payload.artifactId, snapshots, seenPaths)
			table.insert(uiRootResults, uiResult)
			reportApplied("ui_root", uiResult.path)
		end

		for _, phase in ipairs({ "rename", "delete", "upsert" }) do
			for _, op in ipairs(operations) do
				if op.type == phase then
					if phase == "rename" then
						local manifestEntry = indexes.manifestById[tostring(op.id or "")] or indexes.manifestByPath[tostring(op.fromPath or "")]
						local spec = indexes.fileById[tostring(op.id or "")] or indexes.fileByPath[tostring(op.toPath or "")]
						spec = spec or {
							fileId = tostring(op.id or ""),
							id = tostring(op.id or ""),
							path = tostring(op.toPath or ""),
							kind = manifestEntry and manifestEntry.kind,
							placement = manifestEntry and manifestEntry.placement or splitPath(op.toPath)[1],
							className = ScriptContextGuard.resolveScriptClassName(manifestEntry and manifestEntry.className),
						}
						spec.artifactId = payload.artifactId
						local resolved = resolveManagedTarget(spec, indexes, tostring(op.fromPath or ""))
						if not resolved.ok then
							pushResult({ type = phase, path = tostring(op.fromPath or ""), toPath = tostring(op.toPath or "") }, false, resolved.message)
							error(resolved.message)
						end
						if not resolved.instance then
							pushResult({ type = phase, path = tostring(op.fromPath or ""), toPath = tostring(op.toPath or "") }, false, "Rename source not found")
							error("Rename source not found")
						end
						local ok, preconditionError = checkStudioPreconditions(resolved.instance, spec, manifestEntry, indexes)
						if not ok then
							pushResult({ type = phase, path = tostring(op.fromPath or ""), toPath = tostring(op.toPath or "") }, false, preconditionError)
							error(preconditionError)
						end
						snapshotOnce(resolved.instance, snapshots, seenPaths)
						snapshotOnce(tostring(op.toPath or ""), snapshots, seenPaths)
						local parent, leaf = ensureParent(tostring(op.toPath or ""), true)
						if not parent or not leaf then
							pushResult({ type = phase, path = tostring(op.fromPath or ""), toPath = tostring(op.toPath or "") }, false, "Could not resolve rename target parent")
							error("Could not resolve rename target parent")
						end
						resolved.instance.Name = leaf
						resolved.instance.Parent = parent
						resolved.instance:SetAttribute(AGENT_ARTIFACT_ID_ATTRIBUTE, tostring(payload.artifactId or ""))
						resolved.instance:SetAttribute(AGENT_FILE_ID_ATTRIBUTE, tostring(spec.fileId or spec.id or ""))
						pushResult({ type = phase, path = tostring(op.fromPath or ""), toPath = tostring(op.toPath or "") }, true, nil)
					elseif phase == "delete" then
						local manifestEntry = indexes.manifestById[tostring(op.id or "")] or indexes.manifestByPath[tostring(op.path or "")]
						local spec = manifestEntry and {
							fileId = tostring(manifestEntry.fileId or op.id or ""),
							id = tostring(manifestEntry.fileId or op.id or ""),
							path = tostring(manifestEntry.canonicalPath or op.path or ""),
							kind = manifestEntry.kind,
							placement = manifestEntry.placement,
							className = ScriptContextGuard.resolveScriptClassName(manifestEntry.className),
						} or {
							fileId = tostring(op.id or ""),
							id = tostring(op.id or ""),
							path = tostring(op.path or ""),
							kind = nil,
							placement = splitPath(op.path)[1],
							className = "",
						}
						local resolved = resolveManagedTarget(spec, indexes, tostring(op.path or ""))
						if not resolved.ok then
							pushResult({ type = phase, path = tostring(op.path or "") }, false, resolved.message)
							error(resolved.message)
						end
						if resolved.instance then
							local ok, preconditionError = checkStudioPreconditions(resolved.instance, spec, manifestEntry, indexes)
							if not ok then
								pushResult({ type = phase, path = tostring(op.path or "") }, false, preconditionError)
								error(preconditionError)
							end
							snapshotOnce(resolved.instance, snapshots, seenPaths)
							resolved.instance:Destroy()
						else
							snapshotOnce(tostring(op.path or ""), snapshots, seenPaths)
						end
						pushResult({ type = phase, path = tostring(op.path or "") }, true, nil)
					else
						local spec = indexes.fileById[tostring(op.id or "")] or indexes.fileByPath[tostring(op.path or "")]
						if not spec then
							pushResult({ type = phase, path = tostring(op.path or "") }, false, "Upsert is missing an explicit file descriptor")
							error("Upsert is missing an explicit file descriptor")
						end
						spec.allowClassChange = op.allowClassChange == true or spec.allowClassChange == true
						if tostring(op.inspectedClassName or "") ~= "" then
							spec.inspectedClassName = op.inspectedClassName
						end
						if tostring(op.expectedSourceHash or "") ~= "" then
							spec.expectedSourceHash = op.expectedSourceHash
						end
						spec.artifactId = payload.artifactId
						local resolved = resolveManagedTarget(spec, indexes, tostring(op.path or spec.path or ""))
						if not resolved.ok then
							pushResult({ type = phase, path = tostring(op.path or "") }, false, resolved.message)
							error(resolved.message)
						end
						local inst, applyErr, appliedHash = applyManagedUpsert(spec, resolved, indexes, snapshots, seenPaths)
						if not inst then
							pushResult({ type = phase, path = tostring(op.path or "") }, false, applyErr)
							error(applyErr)
						end
						managedFiles[tostring(spec.fileId or spec.id or "")] = buildManagedFileRecord(inst, spec, appliedHash)
						pushResult({ type = phase, path = tostring(op.path or "") }, true, nil)
					end
				end
			end
		end

		for _, spec in ipairs(finalFiles) do
			local resolved = resolveManagedTarget(spec, indexes, tostring(spec.path or ""))
			local fileId = tostring(spec.fileId or spec.id or "")
			if resolved.ok and resolved.instance and managedFiles[fileId] == nil then
				managedFiles[fileId] = buildManagedFileRecord(resolved.instance, spec)
			end
		end

		reportProgress("verifying", "readback", "", "Verifying Studio changes")
		for _, uiResult in ipairs(uiRootResults) do
			local root = resolvePath(uiResult.path)
			if not root or root.ClassName ~= "ScreenGui" then
				error("ui_readback_failed: managed ScreenGui is missing at " .. tostring(uiResult.path or ""))
			end
			if tostring(root:GetAttribute(AGENT_ARTIFACT_ID_ATTRIBUTE) or "") ~= tostring(uiResult.artifactId or "")
				or tostring(root:GetAttribute("NexusRootId") or "") ~= tostring(uiResult.rootId or "")
				or tostring(root:GetAttribute("NexusDesignId") or "") ~= tostring(uiResult.designId or "")
				or tostring(root:GetAttribute("NexusRevision") or "") ~= tostring(uiResult.documentRevision or "") then
				error("ui_readback_failed: managed ScreenGui identity does not match the applied UI root")
			end
			local readbackNodeCount = 0
			local readbackNodeIds = {}
			local sourceHashes = {}
			for _, descendant in ipairs(root:GetDescendants()) do
				local nodeId = tostring(descendant:GetAttribute("NexusNodeId") or "")
				if nodeId ~= "" then
					readbackNodeCount = readbackNodeCount + 1
					table.insert(readbackNodeIds, nodeId)
				end
				if SCRIPT_CLASSES[descendant.ClassName] then
					table.insert(sourceHashes, {
						path = fullPath(descendant),
						className = descendant.ClassName,
						sourceHash = scriptHash(descendant),
					})
				end
			end
			table.sort(readbackNodeIds)
			table.sort(sourceHashes, function(a, b)
				return tostring(a.path or "") < tostring(b.path or "")
			end)
			if readbackNodeCount ~= tonumber(uiResult.nodeCount) then
				error(("ui_readback_failed: expected %d nodes but found %d at %s"):format(
					tonumber(uiResult.nodeCount) or 0,
					readbackNodeCount,
					tostring(uiResult.path or "")
				))
			end
			for index, expectedNodeId in ipairs(uiResult.nodeIds or {}) do
				if readbackNodeIds[index] ~= expectedNodeId then
					error("ui_readback_failed: managed UI node IDs do not match the applied document")
				end
			end
			uiResult.nodeIds = readbackNodeIds
			uiResult.sourceHashes = sourceHashes
			uiResult.treeHash = UiArtifact.treeHash(root)
			root:SetAttribute("NexusTreeHash", uiResult.treeHash)
		end
		reportProgress("verifying", "complete", "", "Studio changes verified")
	end)

	if not executionOk then
		local executionMessage = tostring(executionErr)
		local mutationCode = executionMessage:match("(ui_[%w_]+):") or "apply_artifact_failed"
		return rollbackMutation(snapshots, mutationCode, executionMessage, {
			files = fileResults,
			validation = { failures = 1, total = #operations + #(payload.uiRoots or {}) },
			managedFiles = {},
			uiRoots = uiRootResults,
		})
	end

	local managedList = {}
	for _, record in pairs(managedFiles) do
		table.insert(managedList, record)
	end

	return {
		ok = true,
		artifactId = payload.artifactId,
		revision = payload.revision,
		files = fileResults,
		managedFiles = managedList,
		uiRoots = uiRootResults,
		validation = { failures = 0, total = #operations + #(payload.uiRoots or {}) },
		warnings = payload.warnings or {},
		snapshots = snapshots,
	}
end
end
-- END src/commands/writeTools.lua

-- BEGIN src/commands/nativeModel.lua
local buildNativeModel, inspectNativeModel, applyNativeModelPatch, nativeRevision
do
local function nativeBuildError(code, message)
	return {
		ok = false,
		success = false,
		code = code or "BUILD_FAILED",
		error = tostring(message or "Native model build failed"),
	}
end

local function nativePanic(code, message)
	error(jsonEncode(nativeBuildError(code, message)))
end

local function isSafeNativeId(value)
	return type(value) == "string" and string.match(value, "^[A-Za-z][A-Za-z0-9_-]*$") ~= nil and #value <= 80
end

local function isSafeNativeName(value)
	return type(value) == "string" and value ~= "" and #value <= 120 and string.match(value, "^[%w][%w%s_%.%-]*$") ~= nil
end

local function finiteNumber(value, minValue, maxValue)
	local n = tonumber(value)
	if n == nil or n ~= n or n == math.huge or n == -math.huge then
		return nil
	end
	if minValue ~= nil and n < minValue then
		return nil
	end
	if maxValue ~= nil and n > maxValue then
		return nil
	end
	return n
end

local function nativeVector3(value, minValue, maxValue)
	if type(value) ~= "table" or value["$type"] ~= "Vector3" then
		return nil
	end
	local x = finiteNumber(value.x, minValue, maxValue)
	local y = finiteNumber(value.y, minValue, maxValue)
	local z = finiteNumber(value.z, minValue, maxValue)
	if not x or not y or not z then
		return nil
	end
	return Vector3.new(x, y, z)
end

local function nativeColor3(value)
	if type(value) ~= "table" or value["$type"] ~= "Color3" then
		return nil
	end
	local r = finiteNumber(value.r, 0, 1)
	local g = finiteNumber(value.g, 0, 1)
	local b = finiteNumber(value.b, 0, 1)
	if not r or not g or not b then
		return nil
	end
	return Color3.new(r, g, b)
end

local function nativeCFrame(value)
	if type(value) ~= "table" or value["$type"] ~= "CFrame" or type(value.position) ~= "table" then
		return nil
	end
	local x = finiteNumber(value.position.x, -100000, 100000)
	local y = finiteNumber(value.position.y, -100000, 100000)
	local z = finiteNumber(value.position.z, -100000, 100000)
	if not x or not y or not z then
		return nil
	end
	local rotation = value.rotationDegrees or {}
	return CFrame.new(x, y, z) * CFrame.Angles(
		math.rad(finiteNumber(rotation.x or 0, -3600, 3600) or 0),
		math.rad(finiteNumber(rotation.y or 0, -3600, 3600) or 0),
		math.rad(finiteNumber(rotation.z or 0, -3600, 3600) or 0)
	)
end

local function nativeEnum(value)
	if type(value) ~= "table" or value["$type"] ~= "Enum" then
		return nil
	end
	local enumType = tostring(value.enumType or "")
	local name = tostring(value.name or "")
	if enumType == "Material" and Enum.Material[name] then
		return Enum.Material[name]
	elseif enumType == "PartType" and Enum.PartType[name] then
		return Enum.PartType[name]
	elseif enumType == "NormalId" and Enum.NormalId[name] then
		return Enum.NormalId[name]
	elseif enumType == "ActuatorType" and Enum.ActuatorType[name] then
		return Enum.ActuatorType[name]
	elseif enumType == "HighlightDepthMode" and Enum.HighlightDepthMode[name] then
		return Enum.HighlightDepthMode[name]
	end
	return nil
end

local function nativeNumberRange(value)
	if type(value) ~= "table" or value["$type"] ~= "NumberRange" then
		return nil
	end
	local minValue = finiteNumber(value.min, 0, 10000)
	local maxValue = finiteNumber(value.max, 0, 10000)
	if not minValue or not maxValue or maxValue < minValue then
		return nil
	end
	return NumberRange.new(minValue, maxValue)
end

local function nativeNumberSequence(value)
	if type(value) == "number" then
		local n = finiteNumber(value, 0, 10000)
		return n and NumberSequence.new(n) or nil
	end
	if type(value) ~= "table" or value["$type"] ~= "NumberSequence" or type(value.keypoints) ~= "table" then
		return nil
	end
	local keypoints = {}
	for _, kp in ipairs(value.keypoints) do
		local time = finiteNumber(kp.time, 0, 1)
		local amount = finiteNumber(kp.value, 0, 10000)
		local envelope = finiteNumber(kp.envelope or 0, 0, 10000)
		if not time or not amount or not envelope then
			return nil
		end
		table.insert(keypoints, NumberSequenceKeypoint.new(time, amount, envelope))
	end
	if #keypoints == 0 then
		return nil
	end
	return NumberSequence.new(keypoints)
end

local function nativePropertyValue(key, value)
	if type(value) == "table" then
		local typed = value["$type"]
		if typed == "Vector3" then
			return nativeVector3(value, key == "Size" and 0.05 or -100000, key == "Size" and 2048 or 100000)
		elseif typed == "Color3" then
			return nativeColor3(value)
		elseif typed == "CFrame" then
			return nativeCFrame(value)
		elseif typed == "Enum" then
			return nativeEnum(value)
		elseif typed == "NumberRange" then
			return nativeNumberRange(value)
		elseif typed == "NumberSequence" then
			return nativeNumberSequence(value)
		end
	end
	return value
end

local function applyNativeProperty(inst, key, value, idMap)
	local allow = NATIVE_PROPERTY_ALLOWLIST[inst.ClassName]
	if not allow or not allow[key] then
		nativePanic("UNSUPPORTED_PROPERTY", inst.ClassName .. "." .. tostring(key) .. " is not supported")
	end
	if key == "Value" and inst:IsA("ObjectValue") then
		if value == nil then
			inst.Value = nil
			return
		end
		local target = idMap[tostring(value)]
		if not target then
			nativePanic("INVALID_REFERENCE", "ObjectValue references an unknown generated ID")
		end
		inst.Value = target
		return
	end
	local converted = nativePropertyValue(key, value)
	if converted == nil and value ~= nil then
		nativePanic("INVALID_PROPERTY_VALUE", "Invalid property value for " .. tostring(key))
	end
	local ok, err = pcall(function()
		inst[key] = converted
	end)
	if not ok then
		nativePanic("INVALID_PROPERTY_VALUE", tostring(err))
	end
end

local function validateNativeNode(node, state, depth)
	if type(node) ~= "table" then
		nativePanic("INVALID_SPEC", "Native model node must be an object")
	end
	if depth > NATIVE_MODEL_LIMITS.maxTreeDepth then
		nativePanic("TREE_DEPTH_EXCEEDED", "Native model tree is too deep")
	end
	local id = tostring(node.id or "")
	local className = tostring(node.className or "")
	if not isSafeNativeId(id) then
		nativePanic("INVALID_SPEC", "Invalid native model ID")
	end
	if state.ids[id] then
		nativePanic("DUPLICATE_INSTANCE_ID", "Duplicate native model ID: " .. id)
	end
	if not NATIVE_CLASSES[className] then
		nativePanic("UNSUPPORTED_CLASS", "Unsupported native model class: " .. className)
	end
	if not isSafeNativeName(tostring(node.name or id)) then
		nativePanic("INVALID_SPEC", "Invalid native model name")
	end
	state.ids[id] = node
	state.counts.instances = state.counts.instances + 1
	if state.counts.instances > NATIVE_MODEL_LIMITS.maxInstances then
		nativePanic("INSTANCE_LIMIT_EXCEEDED", "Native model instance limit exceeded")
	end
	if className == "Model" then
		state.counts.models = state.counts.models + 1
	elseif className == "Folder" then
		state.counts.folders = state.counts.folders + 1
	end
	if NATIVE_BASE_PART_CLASSES[className] then
		state.counts.parts = state.counts.parts + 1
		if className == "WedgePart" or className == "CornerWedgePart" then
			state.counts.wedgeParts = state.counts.wedgeParts + 1
		end
		if state.counts.parts > NATIVE_MODEL_LIMITS.maxBaseParts then
			nativePanic("PART_LIMIT_EXCEEDED", "Native model part limit exceeded")
		end
		local size = nativeVector3((node.properties or {}).Size or { ["$type"] = "Vector3", x = 4, y = 1, z = 2 }, 0.05, 2048)
		local cf = nativeCFrame((node.properties or {}).CFrame or { ["$type"] = "CFrame", position = { x = 0, y = 0, z = 0 }, rotationDegrees = { x = 0, y = 0, z = 0 } })
		if not size or not cf then
			nativePanic("INVALID_PROPERTY_VALUE", "Invalid BasePart Size or CFrame")
		end
		local p = cf.Position
		state.bounds.minX = math.min(state.bounds.minX, p.X - size.X / 2)
		state.bounds.maxX = math.max(state.bounds.maxX, p.X + size.X / 2)
		state.bounds.minY = math.min(state.bounds.minY, p.Y - size.Y / 2)
		state.bounds.maxY = math.max(state.bounds.maxY, p.Y + size.Y / 2)
		state.bounds.minZ = math.min(state.bounds.minZ, p.Z - size.Z / 2)
		state.bounds.maxZ = math.max(state.bounds.maxZ, p.Z + size.Z / 2)
	end
	if className == "Attachment" then
		state.counts.attachments = state.counts.attachments + 1
		if state.counts.attachments > NATIVE_MODEL_LIMITS.maxAttachments then
			nativePanic("INSTANCE_LIMIT_EXCEEDED", "Native model attachment limit exceeded")
		end
	end
	if NATIVE_CONSTRAINT_CLASSES[className] then
		state.counts.constraints = state.counts.constraints + 1
		if state.counts.constraints > NATIVE_MODEL_LIMITS.maxConstraints then
			nativePanic("CONSTRAINT_LIMIT_EXCEEDED", "Native model constraint limit exceeded")
		end
	end
	if NATIVE_LIGHT_CLASSES[className] then
		state.counts.lights = state.counts.lights + 1
		if state.counts.lights > NATIVE_MODEL_LIMITS.maxLights then
			nativePanic("INSTANCE_LIMIT_EXCEEDED", "Native model light limit exceeded")
		end
	end
	if className == "Decal" or className == "Texture" then
		state.counts.decals = state.counts.decals + 1
	end
	if className == "ParticleEmitter" then
		state.counts.particleEmitters = state.counts.particleEmitters + 1
		if state.counts.particleEmitters > NATIVE_MODEL_LIMITS.maxParticleEmitters then
			nativePanic("INSTANCE_LIMIT_EXCEEDED", "Native model particle emitter limit exceeded")
		end
	end
	if type(node.tags or {}) ~= "table" or #(node.tags or {}) > NATIVE_MODEL_LIMITS.maxTagsPerInstance then
		nativePanic("INVALID_SPEC", "Invalid native model tags")
	end
	local attrCount = 0
	for key, value in pairs(node.attributes or {}) do
		attrCount = attrCount + 1
		if attrCount > NATIVE_MODEL_LIMITS.maxAttributesPerInstance then
			nativePanic("INVALID_SPEC", "Too many native model attributes")
		end
		local valueType = type(value)
		if valueType ~= "string" and valueType ~= "number" and valueType ~= "boolean" then
			nativePanic("INVALID_PROPERTY_VALUE", "Unsupported attribute value")
		end
		if not isSafeNativeId(tostring(key)) then
			nativePanic("INVALID_SPEC", "Invalid native model attribute name")
		end
	end
	for key, value in pairs(node.properties or {}) do
		local allow = NATIVE_PROPERTY_ALLOWLIST[className]
		if not allow or not allow[key] then
			nativePanic("UNSUPPORTED_PROPERTY", className .. "." .. tostring(key) .. " is not supported")
		end
		if type(value) == "table" and value["$type"] ~= nil and nativePropertyValue(key, value) == nil then
			nativePanic("INVALID_PROPERTY_VALUE", "Invalid typed value for " .. tostring(key))
		end
	end
	for _, child in ipairs(node.children or {}) do
		validateNativeNode(child, state, depth + 1)
	end
end

local function validateNativeReferences(node, idMap)
	if NATIVE_CONSTRAINT_CLASSES[node.className] then
		for specKey, propName in pairs(NATIVE_REFERENCE_FIELDS[node.className] or {}) do
			local refId = tostring((node.references or {})[specKey] or node[specKey] or "")
			local target = idMap[refId]
			if not target then
				nativePanic("INVALID_REFERENCE", node.className .. " missing generated reference " .. specKey)
			end
			if propName == "Part0" or propName == "Part1" then
				if not target:IsA("BasePart") then
					nativePanic("INVALID_REFERENCE", specKey .. " must reference a BasePart")
				end
			elseif not target:IsA("Attachment") then
				nativePanic("INVALID_REFERENCE", specKey .. " must reference an Attachment")
			end
		end
	end
	for _, child in ipairs(node.children or {}) do
		validateNativeReferences(child, idMap)
	end
end

local function createNativeInstances(node, parent, idMap)
	local inst = Instance.new(node.className)
	inst.Name = tostring(node.name or node.id)
	idMap[tostring(node.id)] = inst
	inst:SetAttribute("NexusInstanceId", tostring(node.id))
	for key, value in pairs(node.properties or {}) do
		if key ~= "Value" then
			applyNativeProperty(inst, key, value, idMap)
		end
	end
	for key, value in pairs(node.attributes or {}) do
		inst:SetAttribute(tostring(key), value)
	end
	for _, tag in ipairs(node.tags or {}) do
		Services.CollectionService:AddTag(inst, tostring(tag))
	end
	for _, child in ipairs(node.children or {}) do
		createNativeInstances(child, inst, idMap)
	end
	inst.Parent = parent
	return inst
end

local function resolveNativeReferences(node, idMap)
	local inst = idMap[tostring(node.id)]
	if inst:IsA("ObjectValue") and (node.properties or {}).Value ~= nil then
		applyNativeProperty(inst, "Value", node.properties.Value, idMap)
	end
	if NATIVE_CONSTRAINT_CLASSES[node.className] then
		for specKey, propName in pairs(NATIVE_REFERENCE_FIELDS[node.className] or {}) do
			local refId = tostring((node.references or {})[specKey] or node[specKey] or "")
			inst[propName] = idMap[refId]
		end
	end
	for _, child in ipairs(node.children or {}) do
		resolveNativeReferences(child, idMap)
	end
end

local function findNativeIdempotentModel(idempotencyKey)
	if tostring(idempotencyKey or "") == "" then
		return nil
	end
	for _, rootInst in pairs(NATIVE_ALLOWED_ROOTS) do
		for _, inst in ipairs(rootInst:GetDescendants()) do
			if inst:IsA("Model") and inst:GetAttribute("NexusIdempotencyKey") == idempotencyKey then
				return inst
			end
		end
	end
	return nil
end

local function ensureNativeTargetParent(path)
	local parts = splitPath(path)
	local rootInst = NATIVE_ALLOWED_ROOTS[parts[1]]
	if not rootInst then
		nativePanic("INVALID_TARGET_PATH", "Native model target path must start with Workspace, ReplicatedStorage, or ServerStorage")
	end
	local current = rootInst
	local created = {}
	for i = 2, #parts do
		local name = parts[i]
		if not isSafeNativeName(name) then
			nativePanic("INVALID_TARGET_PATH", "Unsafe native model target path segment")
		end
		local child = current:FindFirstChild(name)
		if not child then
			child = Instance.new("Folder")
			child.Name = name
			child.Parent = current
			table.insert(created, child)
		elseif not child:IsA("Folder") and not child:IsA("Model") then
			nativePanic("INVALID_TARGET_PATH", "Native model target path segment is not a container")
		end
		current = child
	end
	return current, created
end

local function cleanupCreatedTargets(created)
	for i = #created, 1, -1 do
		local inst = created[i]
		if inst and inst.Parent and #inst:GetChildren() == 0 then
			inst:Destroy()
		end
	end
end

local function uniqueNativeName(parent, baseName)
	local name = baseName
	local index = 2
	while parent:FindFirstChild(name) do
		name = ("%s %d"):format(baseName, index)
		index = index + 1
	end
	return name
end

local function placementCFrame(spec)
	local placement = spec.placement or {}
	local mode = tostring(placement.mode or "camera_focus")
	local rotation = placement.rotation or {}
	local cf = CFrame.Angles(
		math.rad(finiteNumber(rotation.x or 0, -3600, 3600) or 0),
		math.rad(finiteNumber(rotation.y or 0, -3600, 3600) or 0),
		math.rad(finiteNumber(rotation.z or 0, -3600, 3600) or 0)
	)
	if mode == "origin" then
		return CFrame.new(0, 0, 0) * cf
	elseif mode == "explicit_position" and type(placement.position) == "table" then
		local p = placement.position
		return CFrame.new(finiteNumber(p.x, -100000, 100000) or 0, finiteNumber(p.y, -100000, 100000) or 0, finiteNumber(p.z, -100000, 100000) or 0) * cf
	elseif mode == "selection_relative" then
		local selected = Services.Selection:Get()
		if #selected > 0 and selected[1] and selected[1]:IsA("PVInstance") then
			return selected[1]:GetPivot() * CFrame.new(0, 0, -8) * cf
		end
	end
	local camera = Services.Workspace.CurrentCamera
	if camera then
		return camera.CFrame * CFrame.new(0, 0, -18) * cf
	end
	return CFrame.new(0, 6, 0) * cf
end

local function buildNativeReceipt(commandId, spec, rootModel, state, warnings, alreadyApplied)
	local bounds
	if state.bounds.minX == math.huge then
		bounds = { x = 0, y = 0, z = 0 }
	else
		bounds = {
			x = state.bounds.maxX - state.bounds.minX,
			y = state.bounds.maxY - state.bounds.minY,
			z = state.bounds.maxZ - state.bounds.minZ,
		}
	end
	return {
		ok = true,
		success = true,
		type = "build_native_model",
		commandId = commandId,
		modelId = tostring(spec.modelId or ""),
		insertedName = rootModel and rootModel.Name or tostring(spec.name or ""),
		insertedRootPath = rootModel and fullPath(rootModel) or "",
		counts = state.counts,
		bounds = bounds,
		placement = spec.placement or { mode = "camera_focus" },
		warnings = warnings or {},
		history = { recorded = true },
		commandAlreadyApplied = alreadyApplied == true,
	}
end

buildNativeModel = function(payload, command)
	local spec = payload.spec
	if type(spec) ~= "table" or tonumber(spec.schemaVersion or 0) ~= 1 then
		return nativeBuildError("INVALID_SPEC", "Invalid NativeModelSpec schema")
	end
	if type(spec.root) ~= "table" or spec.root.className ~= "Model" then
		return nativeBuildError("INVALID_SPEC", "NativeModelSpec root must be a Model")
	end
	local idempotencyKey = tostring(payload.idempotencyKey or "")
	local existing = findNativeIdempotentModel(idempotencyKey)
	if existing then
		local emptyState = {
			counts = { instances = 0, models = 1, folders = 0, parts = 0, wedgeParts = 0, attachments = 0, constraints = 0, lights = 0, decals = 0, particleEmitters = 0 },
			bounds = { minX = math.huge, minY = math.huge, minZ = math.huge, maxX = -math.huge, maxY = -math.huge, maxZ = -math.huge },
		}
		local receipt = buildNativeReceipt(command and command.id or "", spec, existing, emptyState, { "Command already applied; existing model returned." }, true)
		receipt.code = "COMMAND_ALREADY_APPLIED"
		return receipt
	end
	local state = {
		ids = {},
		counts = { instances = 0, models = 0, folders = 0, parts = 0, wedgeParts = 0, attachments = 0, constraints = 0, lights = 0, decals = 0, particleEmitters = 0 },
		bounds = { minX = math.huge, minY = math.huge, minZ = math.huge, maxX = -math.huge, maxY = -math.huge, maxZ = -math.huge },
	}
	local validateOk, validateErr = pcall(function()
		validateNativeNode(spec.root, state, 1)
		if state.bounds.minX ~= math.huge then
			local extentX = state.bounds.maxX - state.bounds.minX
			local extentY = state.bounds.maxY - state.bounds.minY
			local extentZ = state.bounds.maxZ - state.bounds.minZ
			if extentX > NATIVE_MODEL_LIMITS.maxModelExtent or extentY > NATIVE_MODEL_LIMITS.maxModelExtent or extentZ > NATIVE_MODEL_LIMITS.maxModelExtent then
				nativePanic("BOUNDS_LIMIT_EXCEEDED", "Native model bounds exceed safety limit")
			end
		end
	end)
	if not validateOk then
		return nativeBuildError("INVALID_SPEC", tostring(validateErr))
	end
	local idMap = {}
	local rootModel = nil
	local createdTargets = {}
	local buildOk, buildErr = pcall(function()
		rootModel = createNativeInstances(spec.root, nil, idMap)
		validateNativeReferences(spec.root, idMap)
		resolveNativeReferences(spec.root, idMap)
		rootModel:SetAttribute("NexusGenerated", true)
		rootModel:SetAttribute("NexusManaged", true)
		rootModel:SetAttribute("NexusBuildType", "native_model")
		rootModel:SetAttribute("NexusModelId", tostring(spec.modelId or ""))
		rootModel:SetAttribute("NexusCommandId", command and tostring(command.id or "") or "")
		rootModel:SetAttribute("NexusLastCommandId", command and tostring(command.id or "") or "")
		rootModel:SetAttribute("NexusSchemaVersion", 1)
		rootModel:SetAttribute("NexusRevision", "rev_" .. stableHash(tostring(spec.modelId or "") .. ":" .. tostring(command and command.id or "") .. ":" .. tostring(os.clock())))
		rootModel:SetAttribute("NexusIdempotencyKey", idempotencyKey)
		local targetParent
		targetParent, createdTargets = ensureNativeTargetParent(spec.targetParentPath or "Workspace/NexusBuilds")
		rootModel.Name = uniqueNativeName(targetParent, tostring(spec.name or rootModel.Name))
		rootModel.Parent = targetParent
		rootModel:PivotTo(placementCFrame(spec))
	end)
	if not buildOk then
		if rootModel then
			rootModel:Destroy()
		end
		cleanupCreatedTargets(createdTargets)
		return nativeBuildError("BUILD_FAILED", tostring(buildErr))
	end
	return buildNativeReceipt(command and command.id or "", spec, rootModel, state, spec.warnings or {}, false)
end

local function nativeTypedValue(value)
	local valueType = typeof(value)
	if valueType == "Vector3" then
		return { ["$type"] = "Vector3", x = value.X, y = value.Y, z = value.Z }
	elseif valueType == "Color3" then
		return { ["$type"] = "Color3", r = value.R, g = value.G, b = value.B }
	elseif valueType == "CFrame" then
		local rx, ry, rz = value:ToOrientation()
		return {
			["$type"] = "CFrame",
			position = { x = value.Position.X, y = value.Position.Y, z = value.Position.Z },
			rotationDegrees = { x = math.deg(rx), y = math.deg(ry), z = math.deg(rz) },
		}
	elseif valueType == "EnumItem" then
		local text = tostring(value)
		local enumType, name = string.match(text, "^Enum%.([^%.]+)%.(.+)$")
		return { ["$type"] = "Enum", enumType = enumType or "", name = name or text }
	elseif valueType == "NumberRange" then
		return { ["$type"] = "NumberRange", min = value.Min, max = value.Max }
	elseif valueType == "NumberSequence" then
		local keypoints = {}
		for _, kp in ipairs(value.Keypoints) do
			table.insert(keypoints, { time = kp.Time, value = kp.Value, envelope = kp.Envelope })
		end
		return { ["$type"] = "NumberSequence", keypoints = keypoints }
	elseif valueType == "string" or valueType == "number" or valueType == "boolean" then
		return value
	end
	return nil
end

local function nativeAllowedProperties(inst)
	local out = {}
	local allow = NATIVE_PROPERTY_ALLOWLIST[inst.ClassName] or {}
	for key in pairs(allow) do
		local ok, value = pcall(function()
			return inst[key]
		end)
		if ok then
			local typed = nativeTypedValue(value)
			if typed ~= nil then
				out[key] = typed
			end
		end
	end
	return out
end

local function nativeSnapshotSignature(root)
	local rows = {}
	for _, inst in ipairs(root:GetDescendants()) do
		local id = inst:GetAttribute("NexusInstanceId")
		if id then
			table.insert(rows, tostring(id) .. ":" .. inst.ClassName .. ":" .. inst.Name .. ":" .. propertyHash(inst))
		end
	end
	table.sort(rows)
	return table.concat(rows, "|")
end

nativeRevision = function(root)
	local stored = tostring(root:GetAttribute("NexusRevision") or "")
	return "rev_" .. stableHash(stored .. ":" .. nativeSnapshotSignature(root))
end

local function nativeModelSummary(root)
	local counts = { instances = 1, parts = 0, constraints = 0 }
	for _, inst in ipairs(root:GetDescendants()) do
		counts.instances = counts.instances + 1
		if inst:IsA("BasePart") then
			counts.parts = counts.parts + 1
		end
		if NATIVE_CONSTRAINT_CLASSES[inst.ClassName] then
			counts.constraints = counts.constraints + 1
		end
	end
	local bounds = { x = 0, y = 0, z = 0 }
	local ok, _, size = pcall(function()
		return root:GetBoundingBox()
	end)
	if ok and size then
		bounds = { x = size.X, y = size.Y, z = size.Z }
	end
	return counts, bounds
end

inspectNativeModel = function(payload)
	local root = resolvePath(payload.modelPath)
	if not root or not root:IsA("Model") then
		return nativeBuildError("MANAGED_MODEL_NOT_FOUND", "Managed native model was not found")
	end
	if root:GetAttribute("NexusManaged") ~= true and root:GetAttribute("NexusGenerated") ~= true then
		return nativeBuildError("MODEL_NOT_MANAGED", "Model is not managed by NexusRBX")
	end
	local expectedModelId = tostring(payload.expectedModelId or payload.modelId or "")
	local modelId = tostring(root:GetAttribute("NexusModelId") or "")
	if expectedModelId ~= "" and modelId ~= expectedModelId then
		return nativeBuildError("MODEL_ID_MISMATCH", "Managed model ID does not match")
	end

	local warnings = {}
	local seen = {}
	local instances = {}
	local maxInstances = finiteNumber(payload.maxInstances or NATIVE_MODEL_LIMITS.maxInstances, 20, NATIVE_MODEL_LIMITS.maxInstances) or NATIVE_MODEL_LIMITS.maxInstances
	local function addInstance(inst, parentId)
		if #instances >= maxInstances then
			table.insert(warnings, { code = "INSPECTION_TRUNCATED", message = "Native model inspection reached the instance limit" })
			return
		end
		local id = inst == root and "root" or tostring(inst:GetAttribute("NexusInstanceId") or "")
		if id == "" then
			table.insert(warnings, { code = "MISSING_INSTANCE_ID", message = fullPath(inst) .. " is missing NexusInstanceId" })
			return
		end
		if seen[id] then
			table.insert(warnings, { code = "DUPLICATE_INSTANCE_ID", message = "Duplicate NexusInstanceId: " .. id })
			return
		end
		if not NATIVE_CLASSES[inst.ClassName] then
			table.insert(warnings, { code = "UNSUPPORTED_CLASS", message = fullPath(inst) .. " has unsupported class " .. inst.ClassName })
			return
		end
		seen[id] = true
		table.insert(instances, {
			id = id,
			parentId = parentId,
			className = inst.ClassName,
			name = inst.Name,
			properties = nativeAllowedProperties(inst),
			attributes = attributesOf(inst),
			tags = Services.CollectionService:GetTags(inst),
		})
		for _, child in ipairs(inst:GetChildren()) do
			addInstance(child, id)
		end
	end
	addInstance(root, nil)
	local counts, bounds = nativeModelSummary(root)
	return {
		ok = true,
		success = true,
		type = "inspect_native_model",
		modelId = modelId,
		revision = nativeRevision(root),
		rootPath = fullPath(root),
		rootName = root.Name,
		summary = {
			instances = counts.instances,
			parts = counts.parts,
			constraints = counts.constraints,
			bounds = bounds,
		},
		instances = instances,
		warnings = warnings,
	}
end

local function nativeTargetMap(root)
	local map = { root = root }
	for _, inst in ipairs(root:GetDescendants()) do
		local id = inst:GetAttribute("NexusInstanceId")
		if id then
			if map[tostring(id)] then
				nativePanic("DUPLICATE_INSTANCE_ID", "Duplicate NexusInstanceId: " .. tostring(id))
			end
			map[tostring(id)] = inst
		end
	end
	return map
end

local function nativeTarget(idMap, targetId)
	local inst = idMap[tostring(targetId or "")]
	if not inst then
		nativePanic("TARGET_NOT_FOUND", "Unknown managed instance ID: " .. tostring(targetId or ""))
	end
	return inst
end

local function isProtectedNexusMetadata(key)
	return string.match(tostring(key or ""), "^Nexus") ~= nil
end

local function validateNoProtectedNexusAttributes(node)
	for key in pairs(node.attributes or {}) do
		if isProtectedNexusMetadata(key) then
			nativePanic("UNSUPPORTED_PROPERTY", tostring(key) .. " is protected Nexus metadata")
		end
	end
	for _, child in ipairs(node.children or {}) do
		validateNoProtectedNexusAttributes(child)
	end
end

local function applyNativeTransform(inst, op)
	local t = op.translation or {}
	local r = op.rotationDegrees or {}
	local cf = CFrame.new(finiteNumber(t.x or 0, -100000, 100000) or 0, finiteNumber(t.y or 0, -100000, 100000) or 0, finiteNumber(t.z or 0, -100000, 100000) or 0)
		* CFrame.Angles(math.rad(finiteNumber(r.x or 0, -3600, 3600) or 0), math.rad(finiteNumber(r.y or 0, -3600, 3600) or 0), math.rad(finiteNumber(r.z or 0, -3600, 3600) or 0))
	if inst:IsA("PVInstance") then
		inst:PivotTo(inst:GetPivot() * cf)
	elseif inst:IsA("BasePart") then
		inst.CFrame = inst.CFrame * cf
	else
		nativePanic("INVALID_OPERATION", inst.ClassName .. " cannot be transformed")
	end
end

local function rewriteDuplicateIds(rootClone, sourceId, newPrefix)
	local count = 0
	rootClone:SetAttribute("NexusCommandId", nil)
	rootClone:SetAttribute("NexusLastCommandId", nil)
	local function visit(inst)
		count = count + 1
		local oldId = tostring(inst:GetAttribute("NexusInstanceId") or sourceId)
		local newId = newPrefix
		if oldId ~= sourceId then
			newId = newPrefix .. "-" .. oldId
		end
		inst:SetAttribute("NexusInstanceId", newId)
		for _, child in ipairs(inst:GetChildren()) do
			visit(child)
		end
	end
	visit(rootClone)
	return count
end

applyNativeModelPatch = function(payload, command)
	local root = resolvePath(payload.modelPath)
	if not root or not root:IsA("Model") then
		return nativeBuildError("MANAGED_MODEL_NOT_FOUND", "Managed native model was not found")
	end
	if root:GetAttribute("NexusManaged") ~= true and root:GetAttribute("NexusGenerated") ~= true then
		return nativeBuildError("MODEL_NOT_MANAGED", "Model is not managed by NexusRBX")
	end
	local modelId = tostring(root:GetAttribute("NexusModelId") or "")
	if modelId ~= tostring(payload.modelId or "") then
		return nativeBuildError("MODEL_ID_MISMATCH", "Managed model ID does not match")
	end
	local expectedRevision = tostring(payload.expectedRevision or "")
	local currentRevision = nativeRevision(root)
	if expectedRevision ~= "" and expectedRevision ~= currentRevision then
		return {
			ok = false,
			success = false,
			code = "MODEL_REVISION_CONFLICT",
			expectedRevision = expectedRevision,
			currentRevision = currentRevision,
			message = "The model changed in Studio after this edit was prepared.",
		}
	end
	local idempotencyKey = tostring(payload.idempotencyKey or "")
	if idempotencyKey ~= "" and root:GetAttribute("NexusLastPatchIdempotencyKey") == idempotencyKey then
		return {
			ok = true,
			success = true,
			type = "apply_native_model_patch",
			code = "COMMAND_ALREADY_APPLIED",
			commandId = command and tostring(command.id or "") or "",
			modelId = modelId,
			rootPath = fullPath(root),
			previousRevision = expectedRevision,
			newRevision = currentRevision,
			operations = { requested = #(payload.patch and payload.patch.operations or {}), applied = 0, added = 0, removed = 0, modified = 0, duplicated = 0 },
			affectedInstanceIds = {},
			warnings = { "Command already applied; existing model returned." },
			history = { recorded = true },
		}
	end

	local patch = payload.patch or {}
	if tonumber(patch.schemaVersion or 0) ~= 1 or tostring(patch.modelId or "") ~= modelId then
		return nativeBuildError("INVALID_PATCH", "Invalid NativeModelPatch")
	end
	local hasRemoval = false
	for _, op in ipairs(patch.operations or {}) do
		if op.op == "remove_instance" then
			hasRemoval = true
		end
	end
	if hasRemoval and payload.destructiveConfirmed ~= true then
		return nativeBuildError("INVALID_PATCH", "remove_instance requires destructive confirmation")
	end

	local parent = root.Parent
	local originalName = root.Name
	local rollback = root:Clone()
	local snapshots = {}
	appendSnapshotTree(root, snapshots)
	local previousRevision = currentRevision
	local affected = {}
	local opCounts = { requested = #(patch.operations or {}), applied = 0, added = 0, removed = 0, modified = 0, duplicated = 0 }
	local applyOk, applyErr = pcall(function()
		local idMap = nativeTargetMap(root)
		for _, op in ipairs(patch.operations or {}) do
			local kind = tostring(op.op or "")
			if kind == "set_properties" then
				local inst = nativeTarget(idMap, op.targetId)
				for key, value in pairs(op.properties or {}) do
					applyNativeProperty(inst, key, value, idMap)
				end
				table.insert(affected, tostring(op.targetId))
				opCounts.modified = opCounts.modified + 1
			elseif kind == "set_attributes" then
				local inst = nativeTarget(idMap, op.targetId)
				for key, value in pairs(op.attributes or {}) do
					if isProtectedNexusMetadata(key) then
						nativePanic("UNSUPPORTED_PROPERTY", tostring(key) .. " is protected Nexus metadata")
					end
					inst:SetAttribute(tostring(key), value)
				end
				table.insert(affected, tostring(op.targetId))
				opCounts.modified = opCounts.modified + 1
			elseif kind == "rename" then
				local inst = nativeTarget(idMap, op.targetId)
				if not isSafeNativeName(tostring(op.name or "")) then
					nativePanic("INVALID_OPERATION", "Invalid rename target")
				end
				inst.Name = tostring(op.name)
				table.insert(affected, tostring(op.targetId))
				opCounts.modified = opCounts.modified + 1
			elseif kind == "transform" then
				local inst = nativeTarget(idMap, op.targetId)
				applyNativeTransform(inst, op)
				table.insert(affected, tostring(op.targetId))
				opCounts.modified = opCounts.modified + 1
			elseif kind == "resize" then
				local inst = nativeTarget(idMap, op.targetId)
				if not inst:IsA("BasePart") then
					nativePanic("INVALID_OPERATION", "Only BaseParts can be resized")
				end
				local size = nativeVector3(op.size, 0.05, 2048)
				if not size then
					nativePanic("INVALID_PROPERTY_VALUE", "Invalid resize size")
				end
				inst.Size = size
				table.insert(affected, tostring(op.targetId))
				opCounts.modified = opCounts.modified + 1
			elseif kind == "add_instance" then
				local parentInst = nativeTarget(idMap, op.parentId)
				validateNoProtectedNexusAttributes(op.instance or {})
				local newInst = createNativeInstances(op.instance, nil, idMap)
				newInst.Parent = parentInst
				table.insert(affected, tostring(op.instance and op.instance.id or ""))
				opCounts.added = opCounts.added + 1
			elseif kind == "move_instance" then
				local inst = nativeTarget(idMap, op.targetId)
				local newParent = nativeTarget(idMap, op.newParentId)
				if inst == root then
					nativePanic("INVALID_OPERATION", "Managed root cannot be moved")
				end
				inst.Parent = newParent
				table.insert(affected, tostring(op.targetId))
				opCounts.modified = opCounts.modified + 1
			elseif kind == "duplicate_instance" then
				local inst = nativeTarget(idMap, op.targetId)
				local clone = inst:Clone()
				rewriteDuplicateIds(clone, tostring(op.targetId), tostring(op.newIdPrefix or "copy"))
				clone.Parent = inst.Parent
				applyNativeTransform(clone, { translation = op.translation or { x = 0, y = 0, z = 0 } })
				for _, desc in ipairs(clone:GetDescendants()) do
					local id = desc:GetAttribute("NexusInstanceId")
					if id then
						idMap[tostring(id)] = desc
					end
				end
				idMap[tostring(clone:GetAttribute("NexusInstanceId") or op.newIdPrefix)] = clone
				table.insert(affected, tostring(op.newIdPrefix))
				opCounts.duplicated = opCounts.duplicated + 1
				opCounts.added = opCounts.added + 1
			elseif kind == "remove_instance" then
				local inst = nativeTarget(idMap, op.targetId)
				if inst == root then
					nativePanic("INVALID_OPERATION", "Managed root cannot be removed")
				end
				inst:Destroy()
				table.insert(affected, tostring(op.targetId))
				opCounts.removed = opCounts.removed + 1
			elseif kind == "set_tags" then
				local inst = nativeTarget(idMap, op.targetId)
				for _, tag in ipairs(op.remove or {}) do
					if Services.CollectionService:HasTag(inst, tostring(tag)) then
						Services.CollectionService:RemoveTag(inst, tostring(tag))
					end
				end
				for _, tag in ipairs(op.add or {}) do
					Services.CollectionService:AddTag(inst, tostring(tag))
				end
				table.insert(affected, tostring(op.targetId))
				opCounts.modified = opCounts.modified + 1
			elseif kind == "transform_model" then
				applyNativeTransform(root, op)
				table.insert(affected, "root")
				opCounts.modified = opCounts.modified + 1
			else
				nativePanic("INVALID_OPERATION", "Unsupported NativeModelPatch operation: " .. kind)
			end
			opCounts.applied = opCounts.applied + 1
		end
		local counts = nativeModelSummary(root)
		if counts.instances > NATIVE_MODEL_LIMITS.maxInstances or counts.parts > NATIVE_MODEL_LIMITS.maxBaseParts then
			nativePanic("INSTANCE_LIMIT_EXCEEDED", "Native model limits exceeded")
		end
		root:SetAttribute("NexusRevision", "rev_" .. stableHash(modelId .. ":" .. tostring(command and command.id or "") .. ":" .. tostring(os.clock())))
		root:SetAttribute("NexusLastCommandId", command and tostring(command.id or "") or "")
		root:SetAttribute("NexusLastPatchIdempotencyKey", idempotencyKey)
	end)

	if not applyOk then
		root:Destroy()
		rollback.Name = originalName
		rollback.Parent = parent
		return {
			ok = false,
			success = false,
			code = "PATCH_APPLICATION_FAILED",
			error = tostring(applyErr),
			snapshots = snapshots,
		}
	end
	rollback:Destroy()
	local countsAfter, boundsAfter = nativeModelSummary(root)
	return {
		ok = true,
		success = true,
		type = "apply_native_model_patch",
		commandId = command and tostring(command.id or "") or "",
		modelId = modelId,
		rootPath = fullPath(root),
		previousRevision = previousRevision,
		newRevision = nativeRevision(root),
		operations = opCounts,
		affectedInstanceIds = affected,
		countsAfter = {
			instances = countsAfter.instances,
			parts = countsAfter.parts,
			constraints = countsAfter.constraints,
		},
		boundsAfter = boundsAfter,
		warnings = {},
		history = { recorded = true },
		snapshots = snapshots,
	}
end
end
-- END src/commands/nativeModel.lua

-- BEGIN src/commands/importedAsset.lua
local ImportedAsset
do
ImportedAsset = {
	MAX_DESCENDANTS = 10000,
	MAX_DEPTH = 64,
	RECEIPTS_SETTING = "nexusrbxImportedAssetReceipts",
	RECEIPT_ORDER_SETTING = "nexusrbxImportedAssetReceiptOrder",
}

function ImportedAsset.failure(commandType, assetId, code, message, warnings)
	return {
		ok = false,
		type = commandType,
		assetId = tostring(assetId or ""),
		code = code,
		message = message,
		warnings = warnings or {},
	}
end

function ImportedAsset.settingTable(key)
	local ok, value = pcall(function()
		return plugin:GetSetting(key)
	end)
	if ok and type(value) == "table" then
		return value
	end
	return {}
end

function ImportedAsset.getStoredReceipt(idempotencyKey)
	if tostring(idempotencyKey or "") == "" then
		return nil
	end
	local receipts = ImportedAsset.settingTable(ImportedAsset.RECEIPTS_SETTING)
	return receipts[tostring(idempotencyKey)]
end

function ImportedAsset.storeReceipt(idempotencyKey, receipt)
	if tostring(idempotencyKey or "") == "" or type(receipt) ~= "table" then
		return
	end
	local key = tostring(idempotencyKey)
	local receipts = ImportedAsset.settingTable(ImportedAsset.RECEIPTS_SETTING)
	local order = ImportedAsset.settingTable(ImportedAsset.RECEIPT_ORDER_SETTING)
	if not receipts[key] then
		table.insert(order, key)
	end
	receipts[key] = receipt
	while #order > 50 do
		local oldKey = table.remove(order, 1)
		receipts[oldKey] = nil
	end
	pcall(function()
		plugin:SetSetting(ImportedAsset.RECEIPTS_SETTING, receipts)
		plugin:SetSetting(ImportedAsset.RECEIPT_ORDER_SETTING, order)
	end)
end

function ImportedAsset.cleanName(value, fallback)
	local text = tostring(value or ""):gsub("[%c]", ""):gsub("^%s+", ""):gsub("%s+$", "")
	if text == "" then
		text = fallback or "NexusImportedAsset"
	end
	if #text > 100 then
		text = string.sub(text, 1, 100)
	end
	return text
end

function ImportedAsset.uniqueChildName(parent, desiredName)
	local base = ImportedAsset.cleanName(desiredName, "NexusImportedAsset")
	if not parent:FindFirstChild(base) then
		return base
	end
	for index = 2, 500 do
		local candidate = string.format("%s (%d)", base, index)
		if not parent:FindFirstChild(candidate) then
			return candidate
		end
	end
	return base .. " (" .. tostring(Services.HttpService:GenerateGUID(false)) .. ")"
end

function ImportedAsset.isAllowedTarget(path)
	local parts = splitPath(path)
	local root = parts[1]
	if root ~= "Workspace" and root ~= "ReplicatedStorage" and root ~= "ServerStorage" then
		return false
	end
	for _, part in ipairs(parts) do
		if part == "." or part == ".." then
			return false
		end
	end
	return #parts >= 1
end

function ImportedAsset.safeIsA(inst, className)
	local ok, result = pcall(function()
		return inst:IsA(className)
	end)
	return ok and result == true
end

function ImportedAsset.countTreeDepth(inst, depth)
	local maxDepth = depth or 0
	for _, child in ipairs(inst:GetChildren()) do
		maxDepth = math.max(maxDepth, ImportedAsset.countTreeDepth(child, (depth or 0) + 1))
	end
	return maxDepth
end

function ImportedAsset.belongsToRoot(value, root)
	return typeof(value) == "Instance" and (value == root or value:IsDescendantOf(root))
end

function ImportedAsset.scanAndSanitizeRoot(root, requestedAssetType)
	local scan = {
		totalDescendants = 0,
		scriptsRemoved = 0,
		remoteObjectsRemoved = 0,
		bindableObjectsRemoved = 0,
		behaviouralObjectsFlagged = 0,
		invalidReferencesFound = 0,
		meshParts = 0,
		parts = 0,
		models = 0,
		constraints = 0,
		sounds = 0,
		tools = 0,
		prompts = 0,
		clickDetectors = 0,
		packages = 0,
	}
	local warnings = {}
	local blocked = {}
	local descendants = root:GetDescendants()
	scan.totalDescendants = #descendants
	if scan.totalDescendants > ImportedAsset.MAX_DESCENDANTS then
		return nil, "ASSET_TREE_TOO_LARGE", "The asset contains too many descendants.", scan, warnings
	end
	if ImportedAsset.countTreeDepth(root, 0) > ImportedAsset.MAX_DEPTH then
		return nil, "ASSET_TREE_TOO_DEEP", "The asset tree is too deeply nested.", scan, warnings
	end
	if root:IsA("MeshPart") then
		scan.meshParts = scan.meshParts + 1
	elseif root:IsA("BasePart") then
		scan.parts = scan.parts + 1
	elseif root:IsA("Model") then
		scan.models = scan.models + 1
	end
	for _, inst in ipairs(descendants) do
		if ImportedAsset.safeIsA(inst, "LuaSourceContainer") or SCRIPT_CLASSES[inst.ClassName] then
			scan.scriptsRemoved = scan.scriptsRemoved + 1
			table.insert(blocked, inst)
		elseif inst:IsA("RemoteEvent") or inst:IsA("RemoteFunction") or ImportedAsset.safeIsA(inst, "UnreliableRemoteEvent") then
			scan.remoteObjectsRemoved = scan.remoteObjectsRemoved + 1
			table.insert(blocked, inst)
		elseif inst:IsA("BindableEvent") or inst:IsA("BindableFunction") then
			scan.bindableObjectsRemoved = scan.bindableObjectsRemoved + 1
			table.insert(blocked, inst)
		end
		if inst:IsA("MeshPart") then
			scan.meshParts = scan.meshParts + 1
		elseif inst:IsA("BasePart") then
			scan.parts = scan.parts + 1
		elseif inst:IsA("Model") then
			scan.models = scan.models + 1
		end
		if inst:IsA("Tool") then
			scan.tools = scan.tools + 1
			scan.behaviouralObjectsFlagged = scan.behaviouralObjectsFlagged + 1
		elseif inst.ClassName == "HopperBin" or inst:IsA("Humanoid") or inst:IsA("AnimationController") then
			scan.behaviouralObjectsFlagged = scan.behaviouralObjectsFlagged + 1
		elseif inst:IsA("Sound") then
			scan.sounds = scan.sounds + 1
			scan.behaviouralObjectsFlagged = scan.behaviouralObjectsFlagged + 1
		elseif inst:IsA("ProximityPrompt") then
			scan.prompts = scan.prompts + 1
			scan.behaviouralObjectsFlagged = scan.behaviouralObjectsFlagged + 1
		elseif inst:IsA("ClickDetector") then
			scan.clickDetectors = scan.clickDetectors + 1
			scan.behaviouralObjectsFlagged = scan.behaviouralObjectsFlagged + 1
		elseif inst.ClassName == "TouchTransmitter" then
			scan.behaviouralObjectsFlagged = scan.behaviouralObjectsFlagged + 1
		elseif inst.ClassName == "PackageLink" or inst.Name == "PackageLink" then
			scan.packages = scan.packages + 1
			scan.behaviouralObjectsFlagged = scan.behaviouralObjectsFlagged + 1
		end
		if ImportedAsset.safeIsA(inst, "Constraint") then
			scan.constraints = scan.constraints + 1
			local okAttachment0, attachment0 = pcall(function()
				return inst.Attachment0
			end)
			local okAttachment1, attachment1 = pcall(function()
				return inst.Attachment1
			end)
			if (okAttachment0 and attachment0 and not ImportedAsset.belongsToRoot(attachment0, root)) or (okAttachment1 and attachment1 and not ImportedAsset.belongsToRoot(attachment1, root)) then
				scan.invalidReferencesFound = scan.invalidReferencesFound + 1
			end
		end
	end
	for _, inst in ipairs(blocked) do
		if inst and inst.Parent then
			inst:Destroy()
		end
	end
	if scan.scriptsRemoved > 0 then table.insert(warnings, string.format("Removed %d script object(s).", scan.scriptsRemoved)) end
	if scan.remoteObjectsRemoved > 0 then table.insert(warnings, string.format("Removed %d networking object(s).", scan.remoteObjectsRemoved)) end
	if scan.bindableObjectsRemoved > 0 then table.insert(warnings, string.format("Removed %d bindable object(s).", scan.bindableObjectsRemoved)) end
	if scan.behaviouralObjectsFlagged > 0 then table.insert(warnings, string.format("Flagged %d behavioural object(s) for review.", scan.behaviouralObjectsFlagged)) end
	if scan.invalidReferencesFound > 0 then table.insert(warnings, string.format("Found %d constraint reference(s) outside the imported tree.", scan.invalidReferencesFound)) end
	local remainingVisuals = root:IsA("BasePart") and 1 or 0
	for _, inst in ipairs(root:GetDescendants()) do
		if inst:IsA("BasePart") then
			remainingVisuals = remainingVisuals + 1
		end
	end
	if remainingVisuals == 0 then
		return nil, "NO_USABLE_CONTENT", "No usable visual content remained after sanitization.", scan, warnings
	end
	if requestedAssetType == "Mesh" and scan.meshParts == 0 then
		return nil, "UNSUPPORTED_ASSET_TYPE", "The loaded asset did not contain a compatible mesh.", scan, warnings
	end
	return true, nil, nil, scan, warnings
end

function ImportedAsset.targetCFrame(placement)
	local mode = tostring((placement or {}).mode or "camera_focus")
	if mode == "explicit_position" and type(placement.position) == "table" then
		local pos = placement.position
		return CFrame.new(Vector3.new(tonumber(pos.x) or 0, tonumber(pos.y) or 0, tonumber(pos.z) or 0))
	end
	if mode == "camera_focus" then
		local camera = Services.Workspace.CurrentCamera
		if camera then
			local cameraFrame = camera.CFrame
			local target = cameraFrame.Position + cameraFrame.LookVector * 24
			if target.Y < 3 then target = Vector3.new(target.X, 3, target.Z) end
			return CFrame.new(target)
		end
	end
	return CFrame.new(0, 3, 0)
end

function ImportedAsset.pivotRoot(root, placement)
	local target = ImportedAsset.targetCFrame(placement)
	if root:IsA("Model") then
		root:PivotTo(target)
	elseif root:IsA("BasePart") then
		root.CFrame = target
	else
		local primary = root:FindFirstChildWhichIsA("BasePart", true)
		if primary then
			local delta = target.Position - primary.Position
			for _, inst in ipairs(root:GetDescendants()) do
				if inst:IsA("BasePart") then
					inst.CFrame = inst.CFrame + delta
				end
			end
		end
	end
	return target
end

function ImportedAsset.applyPhysics(root, anchoredPolicy, collisionPolicy)
	local rootPart = nil
	if root:IsA("BasePart") then
		rootPart = root
	elseif root:IsA("Model") then
		rootPart = root.PrimaryPart or root:FindFirstChildWhichIsA("BasePart", true)
	else
		rootPart = root:FindFirstChildWhichIsA("BasePart", true)
	end
	local function applyPart(part)
		if anchoredPolicy == "anchor_all" then
			part.Anchored = true
		elseif anchoredPolicy == "anchor_root" and part == rootPart then
			part.Anchored = true
		end
		if collisionPolicy == "disable_all" then
			part.CanCollide = false
		elseif collisionPolicy == "enable_baseparts" then
			part.CanCollide = true
		end
	end
	if root:IsA("BasePart") then applyPart(root) end
	for _, inst in ipairs(root:GetDescendants()) do
		if inst:IsA("BasePart") then applyPart(inst) end
	end
end

function ImportedAsset.insertTrustedRobloxAsset(payload, commandType)
	payload = payload or {}
	local assetId = tostring(payload.assetId or payload.robloxAssetId or "")
	local idempotencyKey = tostring(payload.idempotencyKey or "")
	local replay = ImportedAsset.getStoredReceipt(idempotencyKey)
	if replay then
		replay.replayed = true
		replay.code = "COMMAND_ALREADY_APPLIED"
		return replay
	end
	if not assetId:match("^[1-9]%d*$") then
		return ImportedAsset.failure(commandType, assetId, "INVALID_ASSET_ID", "assetId must be a positive integer.")
	end
	local assetType = tostring(payload.assetType or payload.expectedAssetType or "Model")
	if commandType == "insert_creator_store_asset" and assetType ~= "Model" and assetType ~= "Mesh" then
		return ImportedAsset.failure(commandType, assetId, "UNSUPPORTED_ASSET_TYPE", "Only Model and Mesh Creator Store assets can be imported.")
	end
	if commandType == "insert_uploaded_roblox_model" and assetType ~= "Model" then
		return ImportedAsset.failure(commandType, assetId, "ASSET_TYPE_MISMATCH", "Uploaded Roblox insertion only supports Model assets.")
	end
	local targetParentPath = tostring(payload.targetParentPath or "Workspace/NexusImports")
	if not ImportedAsset.isAllowedTarget(targetParentPath) then
		return ImportedAsset.failure(commandType, assetId, "INVALID_TARGET_PATH", "Imports can only target Workspace, ReplicatedStorage, or ServerStorage.")
	end
	if commandType == "insert_creator_store_asset" then
		local allowFreeAssets = false
		pcall(function()
			allowFreeAssets = Services.AssetService.AllowInsertFreeAssets == true
		end)
		if not allowFreeAssets then
			return ImportedAsset.failure(commandType, assetId, "THIRD_PARTY_ASSETS_DISABLED", "Enable Allow Loading Third Party Assets in Studio Experience Settings.", {
				"Roblox Studio blocked public Creator Store asset loading for this experience.",
			})
		end
	end
	local loadedOk, loadedOrErr = pcall(function()
		return Services.AssetService:LoadAssetAsync(tonumber(assetId))
	end)
	if not loadedOk then
		local message = tostring(loadedOrErr or "")
		local lower = string.lower(message)
		local code = "ASSET_LOAD_FAILED"
		if string.find(lower, "permission") or string.find(lower, "not allowed") or string.find(lower, "third") then
			code = commandType == "insert_creator_store_asset" and "THIRD_PARTY_ASSETS_DISABLED" or "ASSET_NOT_ACCESSIBLE"
			message = commandType == "insert_creator_store_asset" and "Enable Allow Loading Third Party Assets in Studio Experience Settings." or "The uploaded Roblox model is not accessible from this Studio session."
		elseif string.find(lower, "not found") or string.find(lower, "access") then
			code = "ASSET_NOT_ACCESSIBLE"
			message = "The Roblox asset is not accessible from this Studio session."
		else
			message = "The Roblox asset could not be loaded."
		end
		return ImportedAsset.failure(commandType, assetId, code, message)
	end
	local loadedRoot = loadedOrErr
	if typeof(loadedRoot) ~= "Instance" then
		return ImportedAsset.failure(commandType, assetId, "ASSET_LOAD_FAILED", "The Roblox asset returned an invalid object.")
	end
	loadedRoot.Parent = nil
	local scanOk, scanCode, scanMessage, scan, warnings = ImportedAsset.scanAndSanitizeRoot(loadedRoot, assetType)
	if not scanOk then
		loadedRoot:Destroy()
		return ImportedAsset.failure(commandType, assetId, scanCode or "SANITIZATION_FAILED", scanMessage or "Roblox asset import sanitization failed.", warnings)
	end
	local anchoredPolicy = tostring(payload.anchoredPolicy or payload.anchoringMode or "anchor_all")
	if anchoredPolicy ~= "preserve" and anchoredPolicy ~= "anchor_all" and anchoredPolicy ~= "anchor_root" then
		loadedRoot:Destroy()
		return ImportedAsset.failure(commandType, assetId, "INVALID_ANCHORED_POLICY", "Invalid anchoredPolicy.", warnings)
	end
	local collisionPolicy = tostring(payload.collisionPolicy or payload.collisionMode or "disable_all")
	if collisionPolicy == "disable" then collisionPolicy = "disable_all" end
	if collisionPolicy == "visual_default" then collisionPolicy = "enable_baseparts" end
	if collisionPolicy ~= "preserve" and collisionPolicy ~= "disable_all" and collisionPolicy ~= "enable_baseparts" then
		loadedRoot:Destroy()
		return ImportedAsset.failure(commandType, assetId, "INVALID_COLLISION_POLICY", "Invalid collisionPolicy.", warnings)
	end
	ImportedAsset.applyPhysics(loadedRoot, anchoredPolicy, collisionPolicy)
	local targetExisted = resolvePath(targetParentPath) ~= nil
	local parentPath = targetParentPath
	if commandType == "insert_creator_store_asset" then
		parentPath = targetParentPath .. "/ImportedAsset"
	end
	local parent = ensureParent(parentPath, true)
	if not parent then
		loadedRoot:Destroy()
		return ImportedAsset.failure(commandType, assetId, "INVALID_TARGET_PATH", "Could not resolve the import destination.", warnings)
	end
	local requestedName = ImportedAsset.cleanName(payload.requestedName, ImportedAsset.cleanName(payload.assetName, "NexusImportedAsset_" .. assetId))
	local insertedName = ImportedAsset.uniqueChildName(parent, requestedName)
	loadedRoot.Name = insertedName
	local placementCFrame = nil
	local placementOk = pcall(function()
		Services.ChangeHistoryService:SetWaypoint("NexusRBX import start")
		loadedRoot.Parent = parent
		placementCFrame = ImportedAsset.pivotRoot(loadedRoot, payload.placement or {})
		Services.ChangeHistoryService:SetWaypoint("NexusRBX import complete")
	end)
	if not placementOk then
		if loadedRoot then loadedRoot:Destroy() end
		if not targetExisted then
			local target = resolvePath(targetParentPath)
			if target and #target:GetChildren() == 0 then target:Destroy() end
		end
		return ImportedAsset.failure(commandType, assetId, "PLACEMENT_FAILED", "The sanitized asset could not be placed in Studio.", warnings)
	end
	local insertedPath = fullPath(loadedRoot)
	local receipt = {
		success = true,
		ok = true,
		operation = commandType,
		type = commandType,
		assetId = assetId,
		assetName = ImportedAsset.cleanName(payload.assetName, requestedName),
		insertedName = insertedName,
		insertedPath = insertedPath,
		insertedRootPath = insertedPath,
		insertedRootClass = loadedRoot.ClassName,
		sanitizationMode = "strict",
		scan = scan,
		warnings = warnings,
		placement = {
			mode = tostring((payload.placement or {}).mode or "camera_focus"),
			pivot = {
				x = placementCFrame and placementCFrame.Position.X or 0,
				y = placementCFrame and placementCFrame.Position.Y or 0,
				z = placementCFrame and placementCFrame.Position.Z or 0,
			},
		},
		creatorMetadata = payload.sourceMetadata or {},
		uploadId = payload.uploadId,
		insertionId = payload.insertionId,
		sourceHash = payload.expectedSourceSha256,
		history = { recorded = true },
		historyRecorded = true,
		affectedPaths = { insertedPath },
		removed = {
			scripts = scan.scriptsRemoved or 0,
			remotes = scan.remoteObjectsRemoved or 0,
			bindables = scan.bindableObjectsRemoved or 0,
			total = (scan.scriptsRemoved or 0) + (scan.remoteObjectsRemoved or 0) + (scan.bindableObjectsRemoved or 0),
		},
		counts = {
			instances = (scan.totalDescendants or 0) + 1,
			baseParts = (scan.parts or 0) + (scan.meshParts or 0),
			},
			anchoredPolicy = anchoredPolicy,
			collisionPolicy = collisionPolicy,
		}
		ImportedAsset.storeReceipt(idempotencyKey, receipt)
		return receipt
	end
end
-- END src/commands/importedAsset.lua

-- BEGIN src/commands/animation.lua
local createAnimationSequence, animationSequenceHash
do
local R15_ANIMATION_PARTS = {
	"Head",
	"UpperTorso",
	"LowerTorso",
	"LeftUpperArm",
	"LeftLowerArm",
	"LeftHand",
	"RightUpperArm",
	"RightLowerArm",
	"RightHand",
	"LeftUpperLeg",
	"LeftLowerLeg",
	"LeftFoot",
	"RightUpperLeg",
	"RightLowerLeg",
	"RightFoot",
}

local R15_POSE_PARENT = {
	LowerTorso = "HumanoidRootPart",
	UpperTorso = "LowerTorso",
	Head = "UpperTorso",
	LeftUpperArm = "UpperTorso",
	LeftLowerArm = "LeftUpperArm",
	LeftHand = "LeftLowerArm",
	RightUpperArm = "UpperTorso",
	RightLowerArm = "RightUpperArm",
	RightHand = "RightLowerArm",
	LeftUpperLeg = "LowerTorso",
	LeftLowerLeg = "LeftUpperLeg",
	LeftFoot = "LeftLowerLeg",
	RightUpperLeg = "LowerTorso",
	RightLowerLeg = "RightUpperLeg",
	RightFoot = "RightLowerLeg",
}

local animationFailure, findR15Rig, resolveAnimationRig, quaternionCFrame, poseSignature, addPose, buildKeyframe

animationFailure = function(code, message, details)
	local result = details or {}
	result.ok = false
	result.success = false
	result.code = code
	result.error = tostring(message or "Animation command failed")
	result.retryable = false
	return result
end

findR15Rig = function(candidate)
	local current = candidate
	while current and current ~= game do
		if current:IsA("Model") then
			local humanoid = current:FindFirstChildOfClass("Humanoid")
			local valid = humanoid == nil or humanoid.RigType == Enum.HumanoidRigType.R15
			if valid and current:FindFirstChild("HumanoidRootPart", true) then
				for _, partName in ipairs(R15_ANIMATION_PARTS) do
					local part = current:FindFirstChild(partName, true)
					if not part or not part:IsA("BasePart") then
						valid = false
						break
					end
				end
				if valid then return current end
			end
		end
		current = current.Parent
	end
	return nil
end

resolveAnimationRig = function(payload)
	local requestedPath = tostring(payload.rigPath or "")
	if requestedPath ~= "" then
		return findR15Rig(resolvePath(requestedPath)), requestedPath
	end
	local selected = Services.Selection:Get()
	local candidate = selected[1]
	return findR15Rig(candidate), candidate and fullPath(candidate) or ""
end

quaternionCFrame = function(value)
	if type(value) ~= "table" or #value ~= 4 then return CFrame.new() end
	local x = tonumber(value[1]) or 0
	local y = tonumber(value[2]) or 0
	local z = tonumber(value[3]) or 0
	local w = tonumber(value[4]) or 1
	local length = math.sqrt(x * x + y * y + z * z + w * w)
	if length <= 0.000001 then return CFrame.new() end
	x, y, z, w = x / length, y / length, z / length, w / length
	local xx, yy, zz = x * x, y * y, z * z
	local xy, xz, yz = x * y, x * z, y * z
	local xw, yw, zw = x * w, y * w, z * w
	return CFrame.new(
		0, 0, 0,
		1 - 2 * (yy + zz), 2 * (xy - zw), 2 * (xz + yw),
		2 * (xy + zw), 1 - 2 * (xx + zz), 2 * (yz - xw),
		2 * (xz - yw), 2 * (yz + xw), 1 - 2 * (xx + yy)
	)
end

poseSignature = function(pose, pieces)
	local components = { pose.CFrame:GetComponents() }
	local formatted = {}
	for index, component in ipairs(components) do
		formatted[index] = string.format("%.6f", component)
	end
	table.insert(pieces, table.concat({
		fullPath(pose),
		table.concat(formatted, ","),
		tostring(pose.Weight),
		tostring(pose.EasingStyle),
		tostring(pose.EasingDirection),
	}, "|"))
end

animationSequenceHash = function(sequence)
	if not sequence or not sequence:IsA("KeyframeSequence") then return nil end
	local pieces = { sequence.Name, tostring(sequence.Loop), tostring(sequence.Priority) }
	local keyframes = {}
	for _, child in ipairs(sequence:GetChildren()) do
		if child:IsA("Keyframe") then table.insert(keyframes, child) end
	end
	table.sort(keyframes, function(a, b)
		if a.Time == b.Time then return a.Name < b.Name end
		return a.Time < b.Time
	end)
	for _, keyframe in ipairs(keyframes) do
		table.insert(pieces, string.format("time:%.6f", keyframe.Time))
		local poses = {}
		for _, descendant in ipairs(keyframe:GetDescendants()) do
			if descendant:IsA("Pose") then table.insert(poses, descendant) end
		end
		table.sort(poses, function(a, b) return fullPath(a) < fullPath(b) end)
		for _, pose in ipairs(poses) do poseSignature(pose, pieces) end
	end
	return stableHash(table.concat(pieces, "\n"))
end

addPose = function(parent, name, transform, easingStyle, easingDirection)
	local pose = Instance.new("Pose")
	pose.Name = name
	pose.Weight = 1
	pose.CFrame = quaternionCFrame(transform and transform.rotation)
	pose.EasingStyle = Enum.PoseEasingStyle[easingStyle] or Enum.PoseEasingStyle.Cubic
	pose.EasingDirection = Enum.PoseEasingDirection[easingDirection] or Enum.PoseEasingDirection.InOut
	parent:AddSubPose(pose)
	return pose
end

buildKeyframe = function(frame)
	local keyframe = Instance.new("Keyframe")
	keyframe.Time = (tonumber(frame.timeMs) or 0) / 1000
	local rootPose = Instance.new("Pose")
	rootPose.Name = "HumanoidRootPart"
	rootPose.Weight = 0
	keyframe:AddPose(rootPose)
	local poses = { HumanoidRootPart = rootPose }
	for _, jointName in ipairs(R15_ANIMATION_PARTS) do
		local parentName = R15_POSE_PARENT[jointName]
		local parent = poses[parentName]
		if not parent then error("Missing R15 pose parent for " .. tostring(jointName)) end
		poses[jointName] = addPose(
			parent,
			jointName,
			(frame.joints or {})[jointName],
			tostring(frame.easingStyle or "Cubic"),
			tostring(frame.easingDirection or "InOut")
		)
	end
	return keyframe
end

createAnimationSequence = function(payload)
	local rig, requestedPath = resolveAnimationRig(payload)
	if not rig then
		return animationFailure(
			"r15_rig_required",
			"Select a complete R15 rig in Studio before applying this animation",
			{ requestedRigPath = requestedPath }
		)
	end
	local name = tostring(payload.name or "Nexus Animation")
	local animSaves = rig:FindFirstChild("AnimSaves")
	if animSaves and not animSaves:IsA("Folder") then
		return animationFailure("animation_folder_conflict", "The rig already has a non-Folder child named AnimSaves", {
			rigPath = fullPath(rig),
		})
	end
	local existing = animSaves and animSaves:FindFirstChild(name) or nil
	if existing and not existing:IsA("KeyframeSequence") then
		return animationFailure("animation_name_conflict", "An incompatible instance already uses this animation name", {
			path = fullPath(existing),
		})
	end
	if existing then
		local currentHash = animationSequenceHash(existing)
		local expectedHash = tostring(payload.expectedSequenceHash or "")
		if expectedHash == "" then
			return animationFailure("animation_sequence_hash_required", "Inspect the existing animation before replacing it", {
				path = fullPath(existing),
				currentSequenceHash = currentHash,
			})
		end
		if expectedHash ~= currentHash then
			return animationFailure("animation_sequence_conflict", "The existing animation changed after it was inspected", {
				path = fullPath(existing),
				expectedSequenceHash = expectedHash,
				currentSequenceHash = currentHash,
			})
		end
	end

	local rigPath = fullPath(rig)
	local animSavesPath = rigPath .. "/AnimSaves"
	local sequencePath = animSavesPath .. "/" .. name
	local snapshots = {}
	if not animSaves then table.insert(snapshots, snapshotInstance(animSavesPath)) end
	if existing then appendSnapshotTree(existing, snapshots) else table.insert(snapshots, snapshotInstance(sequencePath)) end

	local ok, sequenceOrError = pcall(function()
		if not animSaves then
			animSaves = Instance.new("Folder")
			animSaves.Name = "AnimSaves"
			animSaves.Parent = rig
		end
		if existing then existing:Destroy() end
		local sequence = Instance.new("KeyframeSequence")
		sequence.Name = name
		sequence.Loop = payload.loop == true
		sequence.Priority = Enum.AnimationPriority[tostring(payload.priority or "Action")] or Enum.AnimationPriority.Action
		sequence:SetAttribute("NexusGenerated", true)
		sequence:SetAttribute("NexusAnimationSchemaVersion", tonumber(payload.animationSchemaVersion) or 1)
		sequence:SetAttribute("NexusAnimationContentHash", tostring(payload.contentHash or ""))
		sequence:SetAttribute("NexusSourceAnimationHash", tostring(payload.sourceContentHash or ""))
		for _, frame in ipairs(payload.keyframes or {}) do sequence:AddKeyframe(buildKeyframe(frame)) end
		sequence.Parent = animSaves
		return sequence
	end)
	if not ok then
		return rollbackMutation(snapshots, "create_animation_sequence_failed", tostring(sequenceOrError), {
			path = sequencePath,
			rigPath = rigPath,
		})
	end
	local sequence = sequenceOrError
	return {
		ok = true,
		path = fullPath(sequence),
		rigPath = rigPath,
		className = sequence.ClassName,
		keyframeCount = #(payload.keyframes or {}),
		durationMs = tonumber(payload.durationMs) or 0,
		sequenceHash = animationSequenceHash(sequence),
		contentHash = tostring(payload.contentHash or ""),
		snapshots = snapshots,
	}
end
end
-- END src/commands/animation.lua

-- BEGIN src/commands/registry.lua
local pullOnce, executeCommand, ack, TOOL_HANDLERS, getPluginAttestation, getStoredCommandReceipt, storeCommandReceipt, reconcileStoredCommandReceipt
do
local MUTATING_COMMANDS = {
	apply_artifact = true,
	create_script = true,
	write_script = true,
	patch_script = true,
	rename_script = true,
	move_script = true,
	duplicate_script = true,
	delete_script = true,
	format_script = true,
	replace_in_files = true,
	create_instance = true,
	update_properties = true,
	apply_asset_reference = true,
	update_attributes = true,
	update_tags = true,
	rename_instance = true,
	move_instance = true,
	duplicate_instance = true,
	delete_instance = true,
	batch_operations = true,
	build_native_model = true,
	insert_creator_store_asset = true,
	insert_uploaded_roblox_model = true,
	create_animation_sequence = true,
	apply_native_model_patch = true,
	restore_snapshot = true,
	undo_last_batch = true,
}

local executedCommandCount = 0
local COMMAND_RECEIPTS_SETTING, COMMAND_RECEIPT_ORDER_SETTING, COMMAND_RECEIPT_LIMIT =
	"nexusrbxCommandReceiptsV2", "nexusrbxCommandReceiptOrderV2", 50

-- Keep handlers for structured responses to commands queued by a newer server,
-- but do not advertise operations this plugin cannot actually execute.
local UNAVAILABLE_COMMANDS = {
	format_script = true,
	run_test_service = true,
	run_play_test = true,
	stop_play_test = true,
}

TOOL_HANDLERS = {
	apply_artifact = applyArtifact,
	insert_creator_store_asset = function(payload)
		return ImportedAsset.insertTrustedRobloxAsset(payload, "insert_creator_store_asset")
	end,
	insert_uploaded_roblox_model = function(payload)
		return ImportedAsset.insertTrustedRobloxAsset(payload, "insert_uploaded_roblox_model")
	end,
	create_animation_sequence = createAnimationSequence,
	get_project_manifest = inspectPlace,
	list_children = listChildren,
	inspect_place = inspectPlace,
	inspect_instances = inspectInstances,
	search_project = searchProject,
	search_source = searchSource,
	read_script = readScript,
	read_scripts = readScript,
	read_instance = readInstance,
	read_properties = readProperties,
	get_selection = getSelectionTool,
	get_studio_context = getStudioContext,
	get_change_history = function()
		return { snapshots = localSnapshots, snapshotCount = #localSnapshots }
	end,
	get_output_logs = collectOutput,
	collect_output = collectOutput,
	build_native_model = buildNativeModel,
	inspect_native_model = inspectNativeModel,
	apply_native_model_patch = applyNativeModelPatch,
	create_script = createScript,
	write_script = writeScript,
	patch_script = patchScript,
	rename_script = renameInstanceTool,
	move_script = moveInstanceTool,
	duplicate_script = duplicateInstanceTool,
	delete_script = deleteScript,
	format_script = function(payload)
		return structuredUnsupported("format_script", "Formatting Luau source requires a formatter outside this Studio plugin runtime.")
	end,
	replace_in_files = replaceInFiles,
	create_instance = createInstanceTool,
	update_properties = updateProperties,
	apply_asset_reference = applyAssetReference,
	update_attributes = updateAttributes,
	update_tags = updateTags,
	rename_instance = renameInstanceTool,
	move_instance = moveInstanceTool,
	duplicate_instance = duplicateInstanceTool,
	delete_instance = deleteInstanceTool,
	parse_luau = parseLuau,
	run_project_validation = runProjectValidation,
	collect_diagnostics = collectDiagnostics,
	run_test_service = function()
		return structuredUnsupported("run_test_service", "Running TestService from a plugin is not safely supported by this bridge.")
	end,
	run_play_test = function()
		return structuredUnsupported("run_play_test", "Starting play tests from this plugin bridge is not supported.")
	end,
	stop_play_test = function()
		return structuredUnsupported("stop_play_test", "Stopping play tests from this plugin bridge is not supported.")
	end,
	create_snapshot = createSnapshotTool,
	restore_snapshot = restoreSnapshots,
	undo_last_batch = function()
		return restoreSnapshots({ snapshots = lastBatchSnapshots })
	end,
	run_smoke_check = runSmokeCheck,
}

-- Pairing must describe the handlers this *loaded bundle* can actually run.
-- Deriving this from TOOL_HANDLERS prevents an old generated artifact from
-- advertising a command just because it copied a version/protocol string.
getPluginAttestation = function()
	local supportedCommands = {}
	for commandType, handler in pairs(TOOL_HANDLERS) do
		if type(handler) == "function" and not UNAVAILABLE_COMMANDS[commandType] then
			table.insert(supportedCommands, commandType)
		end
	end
	table.sort(supportedCommands)

	local capabilities = {}
	for capability, enabled in pairs(PLUGIN_CAPABILITIES or {}) do
		capabilities[capability] = enabled == true
	end

	return {
		pluginVersion = PLUGIN_VERSION,
		protocolVersion = STUDIO_PROTOCOL_VERSION,
		buildId = PLUGIN_BUILD_ID,
		supportedCommands = supportedCommands,
		capabilities = capabilities,
	}
end

local function isMutatingCommand(commandType)
	return MUTATING_COMMANDS[tostring(commandType or "")] == true
end

local function batchOperations(payload)
	local snapshots = {}
	local results = {}
	local failureCode = nil
	local previousBatch = lastBatchSnapshots
	lastBatchSnapshots = snapshots
	local function rejectUnsupportedBatchOperation(index, opType, message)
		local result = structuredUnsupported(opType, message)
		result.code = "STUDIO_TOOL_UNSUPPORTED"
		result.retryable = false
		result.error.code = "STUDIO_TOOL_UNSUPPORTED"
		failureCode = result.code
		table.insert(results, {
			index = index,
			type = opType,
			ok = false,
			error = result.error.message,
			result = result,
		})
		error(result.error.message)
	end
	local ok, err = pcall(function()
		for index, op in ipairs(payload.operations or {}) do
			local opType = tostring(op.type or "")
			if opType == "apply_artifact" or opType == "apply_asset_reference" or opType == "batch_operations" then
				rejectUnsupportedBatchOperation(index, opType, "Nested or artifact batch operation is not supported")
			end
			local handler = TOOL_HANDLERS[opType]
			if type(handler) ~= "function" or UNAVAILABLE_COMMANDS[opType] then
				rejectUnsupportedBatchOperation(index, opType, "Unsupported batch operation: " .. opType)
			end
			local result = handler(op.payload or {})
			if type(result) == "table" and result.snapshots then
				for _, snap in ipairs(result.snapshots) do
					table.insert(snapshots, snap)
				end
			end
			if type(result) == "table" and result.ok == false then
				local resultError = result.error or result.message or "Batch operation failed"
				if type(resultError) == "table" then
					resultError = resultError.message or resultError.code or "Batch operation failed"
				end
				table.insert(results, { index = index, type = opType, ok = false, error = tostring(resultError), result = result })
				error(tostring(resultError))
			end
			table.insert(results, { index = index, type = opType, ok = true, result = result })
		end
	end)
	if not ok then
		local atomic = payload.atomic ~= false
		local rollback = nil
		if atomic then
			rollback = restoreSnapshots({ snapshots = snapshots, force = true })
		end
		if #snapshots == 0 then
			lastBatchSnapshots = previousBatch
		end
			local rolledBack = atomic and type(rollback) == "table" and rollback.ok == true
			return {
				ok = false,
				code = atomic and not rolledBack and "rollback_failed" or failureCode or "batch_operation_failed",
				error = tostring(err),
				atomic = atomic,
			rolledBack = rolledBack,
			rollback = rollback,
			results = results,
			snapshots = snapshots,
		}
	end
	return { ok = true, results = results, snapshots = snapshots, snapshotCount = #snapshots }
end

TOOL_HANDLERS.batch_operations = batchOperations

getStoredCommandReceipt = function(operationId)
	if tostring(operationId or "") == "" then return nil end
	local ok, receipts = pcall(function()
		return plugin:GetSetting(COMMAND_RECEIPTS_SETTING)
	end)
	if not ok or type(receipts) ~= "table" then return nil end
	local receipt = receipts[tostring(operationId)]
	return type(receipt) == "table" and receipt or nil
end

-- Persist the mutation outcome before attempting its network acknowledgment.
-- A bounded journal lets a redelivered operation reconcile its prior result
-- without ever invoking the Studio mutation twice.
storeCommandReceipt = function(command, status, result, errorMessage)
	if type(command) ~= "table" or not isMutatingCommand(command.type) then return true end
	local operationId = tostring(command.operationId or "")
	local idempotencyKey = tostring(command.idempotencyKey or "")
	if operationId == "" or idempotencyKey == "" then return false end

	local existing = getStoredCommandReceipt(operationId)
	if existing and tostring(existing.idempotencyKey or "") ~= idempotencyKey then
		return false
	end
	local settingsOk, receipts, order = pcall(function()
		local storedReceipts = plugin:GetSetting(COMMAND_RECEIPTS_SETTING)
		local storedOrder = plugin:GetSetting(COMMAND_RECEIPT_ORDER_SETTING)
		return type(storedReceipts) == "table" and storedReceipts or {},
			type(storedOrder) == "table" and storedOrder or {}
	end)
	if not settingsOk then return false end
	if receipts[operationId] == nil then table.insert(order, operationId) end
	receipts[operationId] = {
		journalVersion = 1,
		operationId = operationId,
		idempotencyKey = idempotencyKey,
		commandId = command.id or command.commandId,
		commandType = command.type,
		status = status,
		result = result,
		error = errorMessage,
		recordedAt = os.time(),
	}
	while #order > COMMAND_RECEIPT_LIMIT do
		local expiredOperationId = table.remove(order, 1)
		receipts[expiredOperationId] = nil
	end
	return pcall(function()
		plugin:SetSetting(COMMAND_RECEIPTS_SETTING, receipts)
		plugin:SetSetting(COMMAND_RECEIPT_ORDER_SETTING, order)
	end)
end

ack = function(commandOrId, status, result, errorMessage)
	local token = getToken()
	if not token then
		return false
	end
	local command = type(commandOrId) == "table" and commandOrId or nil
	local commandId = command and (command.id or command.commandId) or commandOrId
	if not commandId or tostring(commandId) == "" then
		return false
	end
	local receiptResult = result
	if command and tonumber(command.lifecycleVersion) == 2 then
		if type(receiptResult) ~= "table" then
			receiptResult = {}
		end
		local lease = type(command.lease) == "table" and command.lease or {}
		receiptResult.leaseFence = receiptResult.leaseFence or lease.fence or command.leaseFence
		receiptResult.lifecycleVersion = 2
		receiptResult.operationId = receiptResult.operationId or command.operationId
		receiptResult.idempotencyKey = receiptResult.idempotencyKey or command.idempotencyKey
	end
	local requestOptions = { idempotent = true }
	if command then
		-- Semantic operation keys can include long manifest/session coordinates.
		-- Keep the HTTP header short and transport-safe while remaining stable for
		-- every retry of this command receipt.
		requestOptions.idempotencyKey = tostring(commandId) .. ":studio-ack:" .. tostring(status)
	end
	if command and tonumber(command.lifecycleVersion) == 2
		and (status == "succeeded" or status == "failed") then
		storeCommandReceipt(command, status, receiptResult, errorMessage)
	end
	local ok = request("POST", "/api/studio/commands/" .. Services.HttpService:UrlEncode(tostring(commandId)) .. "/ack", {
		status = status,
		result = receiptResult,
		error = errorMessage,
	}, token, requestOptions)
	return ok == true
end

function reportCommandProgress(command, progress)
	local token = getToken()
	local commandId = command and (command.id or command.commandId)
	if not token or not commandId or tostring(commandId) == "" then
		return false
	end
	local payload = type(progress) == "table" and progress or {}
	local requestOptions = {
		idempotent = true,
		maxAttempts = 1,
		idempotencyKey = tostring(commandId)
			.. ":studio-progress:"
			.. tostring(payload.phase or "applying")
			.. ":"
			.. tostring(payload.operation or "operation")
			.. ":"
			.. tostring(payload.completed or 0),
	}
	local ok = request(
		"POST",
		"/api/studio/commands/" .. Services.HttpService:UrlEncode(tostring(commandId)) .. "/progress",
		payload,
		token,
		requestOptions
	)
	return ok == true
end

reconcileStoredCommandReceipt = function(command)
	local stored = getStoredCommandReceipt(command and command.operationId)
	if not stored then return false, false end
	if tostring(stored.idempotencyKey or "") ~= tostring(command.idempotencyKey or "") then
		local conflict = {
			ok = false,
			success = false,
			verified = false,
			code = "OPERATION_ID_CONFLICT",
			operationId = command.operationId,
			idempotencyKey = command.idempotencyKey,
			error = {
				code = "OPERATION_ID_CONFLICT",
				message = "This operationId was already used with a different idempotencyKey",
				retryable = false,
			},
		}
		return true, ack(command, "failed", conflict, conflict.error.message)
	end

	local status, result, errorMessage = stored.status, stored.result, stored.error
	if status == "started" then
		status = "failed"
		result = {
			ok = false,
			success = false,
			verified = false,
			outcome = "studio_state_uncertain",
			code = "OPERATION_OUTCOME_UNCERTAIN",
			operationId = command.operationId,
			idempotencyKey = command.idempotencyKey,
			error = {
				code = "OPERATION_OUTCOME_UNCERTAIN",
				message = "Studio restarted or lost connection after execution began; the mutation will not be replayed",
				retryable = false,
			},
		}
		errorMessage = result.error.message
	end
	if status ~= "succeeded" and status ~= "failed" then return false, false end
	local confirmed = ack(command, status, result, errorMessage)
	setBridgeState(confirmed and "live" or "reconciling", confirmed and "prior operation reconciled" or "stored result confirmation pending")
	setLast(confirmed and "Reconciled a previously executed Studio operation" or "Stored Studio result is waiting for website confirmation")
	return true, confirmed
end

local function commandStartedMs()
	if type(nowMs) == "function" then
		return nowMs()
	end
	return math.floor(os.clock() * 1000)
end

-- Commands whose success can be proven by re-reading the place after the write.
local DELETE_COMMANDS = {
	delete_script = true,
	delete_instance = true,
}

local SCRIPT_WRITE_COMMANDS = {
	write_script = true,
	create_script = true,
	patch_script = true,
}

local function currentScriptHashAt(path)
	if type(path) ~= "string" or path == "" then
		return nil, nil, { code = "invalid_path", method = "resolvePath" }
	end
	local inst = resolvePath(path)
	if not inst then
		return nil, nil, { code = "target_not_found", method = "resolvePath" }
	end
	if SCRIPT_CLASSES and SCRIPT_CLASSES[inst.ClassName]
		and type(readScriptSource) == "function" and type(stableHash) == "function" then
		local ok, source, readEvidence = readScriptSource(inst)
		return inst, ok and stableHash(source) or nil, readEvidence
	end
	return inst, nil, { code = "not_script", className = tostring(inst.ClassName or "") }
end

-- Re-inspect the place after a mutating command and return semantic evidence
-- for the exact requested post-state. A path existing is never sufficient for
-- property, attribute, tag, source, artifact, or native-model writes.
local function verifyCommandOutcome(command, payload, result)
	local commandType = command.type or ""
	if not isMutatingCommand(commandType) then
		return true, nil, { commandType = commandType, acknowledged = true }
	end

	local checks = {}
	local evidence = { commandType = commandType, checks = checks }
	local function addCheck(kind, path, ok, details)
		local check = details or {}
		check.kind = kind
		check.path = path or ""
		check.ok = ok == true
		table.insert(checks, check)
		return check.ok
	end
	local function valuesMatch(expected, actual)
		if type(expected) == "number" and type(actual) == "number" then
			return math.abs(expected - actual) <= 0.00001
		end
		if type(expected) ~= type(actual) then
			return false
		end
		if type(expected) ~= "table" then
			return expected == actual
		end
		for key, expectedValue in pairs(expected) do
			local actualValue = actual[key]
			if key == "type" and actualValue == nil then
				actualValue = actual["$type"]
			elseif key == "$type" and actualValue == nil then
				actualValue = actual.type
			end
			if not valuesMatch(expectedValue, actualValue) then
				return false
			end
		end
		return true
	end
	local function instanceProperty(inst, key, useNativeEncoding)
		if not inst then
			return nil
		end
		if useNativeEncoding then
			local ok, value = pcall(function()
				return inst[key]
			end)
			return ok and nativeTypedValue(value) or nil
		end
		return safePropertyValue(inst, key)
	end
	local function checkProperties(inst, path, properties, kind, useNativeEncoding, operationIndex)
		local count = 0
		for key, expected in pairs(properties or {}) do
			count = count + 1
			local actual = instanceProperty(inst, key, useNativeEncoding)
			addCheck(kind, path, valuesMatch(expected, actual), {
				key = tostring(key),
				expected = expected,
				actual = actual,
				operationIndex = operationIndex,
				reason = actual == nil and "unreadable" or nil,
			})
		end
		return count
	end
	local function checkAttributes(inst, path, attributes, kind, operationIndex)
		local count = 0
		for key, expected in pairs(attributes or {}) do
			count = count + 1
			local actual = inst and inst:GetAttribute(tostring(key)) or nil
			addCheck(kind, path, valuesMatch(expected, actual), {
				key = tostring(key),
				expected = expected,
				actual = actual,
				operationIndex = operationIndex,
			})
		end
		return count
	end
	local function tagSetMatches(inst, requested)
		if not inst then
			return false, {}
		end
		local actual = Services.CollectionService:GetTags(inst)
		local expectedSet = {}
		local actualSet = {}
		for _, tag in ipairs(requested or {}) do
			expectedSet[tostring(tag)] = true
		end
		for _, tag in ipairs(actual) do
			actualSet[tostring(tag)] = true
		end
		for tag in pairs(expectedSet) do
			if not actualSet[tag] then
				return false, actual
			end
		end
		for tag in pairs(actualSet) do
			if not expectedSet[tag] then
				return false, actual
			end
		end
		return true, actual
	end
	local function verifyNativeModelIdentity(root, path, modelId, expectedRevision)
		local actualModelId = root and tostring(root:GetAttribute("NexusModelId") or "") or ""
		local revision = root and nativeRevision(root) or nil
		local managed = root and (root:GetAttribute("NexusManaged") == true or root:GetAttribute("NexusGenerated") == true)
		local ok = root ~= nil
			and root:IsA("Model")
			and managed == true
			and actualModelId == tostring(modelId or "")
			and revision ~= nil
			and (expectedRevision == nil or expectedRevision == "" or revision == expectedRevision)
		addCheck("native_model", path, ok, {
			modelId = tostring(modelId or ""),
			actualModelId = actualModelId,
			revision = revision,
			expectedRevision = expectedRevision,
		})
		return ok, revision
	end

	if DELETE_COMMANDS[commandType] then
		local target = result.path or payload.path
		addCheck("instance_absence", target, type(target) == "string" and target ~= "" and resolvePath(target) == nil, {
			reason = resolvePath(target) and "still_present" or nil,
		})
		if commandType == "delete_script" then
			evidence.baselineSourceHash = result.previousHash or payload.expectedSourceHash
			evidence.previousSourceHash = result.previousHash or payload.expectedSourceHash
		end
	elseif SCRIPT_WRITE_COMMANDS[commandType] then
		local target = result.path or payload.path
		local inst, currentHash = currentScriptHashAt(target)
		local expectedHash = result.sourceHash or (type(payload.source) == "string" and stableHash(payload.source) or nil)
		addCheck("script_source", target, inst ~= nil and currentHash ~= nil and expectedHash ~= nil and currentHash == expectedHash, {
			expectedHash = expectedHash,
			actualHash = currentHash,
			reason = not inst and "missing" or (currentHash ~= expectedHash and "hash_mismatch" or nil),
		})
		evidence.readbackHash = currentHash
		evidence.currentSourceHash = currentHash
		evidence.baselineSourceHash = result.previousHash or payload.expectedSourceHash
		evidence.previousSourceHash = result.previousHash or payload.expectedSourceHash
	elseif commandType == "apply_asset_reference" then
		local target = result.path or payload.path
		local inst = resolvePath(target)
		local property = tostring(payload.property or "")
		local expectedClassName = tostring(payload.className or "")
		local robloxAssetId = tostring(payload.robloxAssetId or "")
		local expected = "rbxassetid://" .. robloxAssetId
		local actual = inst and safePropertyValue(inst, property) or nil
		local exact = inst ~= nil and inst.ClassName == expectedClassName and actual == expected
		addCheck("asset_reference", target, exact, {
			key = property,
			property = property,
			className = inst and inst.ClassName or nil,
			expected = expected,
			actual = actual,
			robloxAssetId = robloxAssetId,
			reason = inst == nil and "missing" or (not exact and "asset_reference_mismatch" or nil),
		})
		evidence.assetReference = {
			path = target,
			className = inst and inst.ClassName or nil,
			property = property,
			robloxAssetId = robloxAssetId,
			expected = expected,
			actual = actual,
		}
	elseif commandType == "update_properties" then
		local target = result.path or payload.path
		local inst = resolvePath(target)
		if checkProperties(inst, target, payload.properties, "property", false, nil) == 0 then
			addCheck("property", target, false, { reason = "no_requested_properties" })
		end
	elseif commandType == "update_attributes" then
		local target = result.path or payload.path
		local inst = resolvePath(target)
		if checkAttributes(inst, target, payload.attributes or payload.values, "attribute", nil) == 0 then
			addCheck("attribute", target, false, { reason = "no_requested_attributes" })
		end
	elseif commandType == "update_tags" then
		local target = result.path or payload.path
		local inst = resolvePath(target)
		if payload.set ~= nil then
			local ok, actual = tagSetMatches(inst, payload.set)
			addCheck("tag_set", target, ok, { expected = payload.set or {}, actual = actual })
		else
			local count = 0
			for _, tag in ipairs(payload.add or {}) do
				count = count + 1
				addCheck("tag", target, inst ~= nil and Services.CollectionService:HasTag(inst, tostring(tag)), {
					tag = tostring(tag),
					expectedPresent = true,
				})
			end
			for _, tag in ipairs(payload.remove or {}) do
				count = count + 1
				addCheck("tag", target, inst ~= nil and not Services.CollectionService:HasTag(inst, tostring(tag)), {
					tag = tostring(tag),
					expectedPresent = false,
				})
			end
			if count == 0 then
				addCheck("tag", target, false, { reason = "no_requested_tags" })
			end
		end
	elseif commandType == "create_instance" then
		local target = result.path or payload.path
		local inst = resolvePath(target)
		addCheck("instance_identity", target, inst ~= nil and inst.ClassName == tostring(payload.className or "Folder"), {
			expectedClassName = tostring(payload.className or "Folder"),
			actualClassName = inst and inst.ClassName or nil,
		})
		checkProperties(inst, target, payload.properties, "property", false, nil)
		checkAttributes(inst, target, payload.attributes, "attribute", nil)
		for _, tag in ipairs(payload.tags or {}) do
			addCheck("tag", target, inst ~= nil and Services.CollectionService:HasTag(inst, tostring(tag)), {
				tag = tostring(tag),
				expectedPresent = true,
			})
		end
	elseif commandType == "apply_artifact" then
		local files = result.managedFiles or {}
		for _, file in ipairs(files) do
			if type(file) == "table" then
				local p = file.lastResolvedStudioPath or file.canonicalPath or file.path
				if type(p) == "string" and p ~= "" then
					local expected = file.lastAppliedSourceHash or file.resultingHash or file.sourceHash
					local expectedClassName = tostring(file.className or "")
					local inst, currentHash, sourceRead = nil, nil, nil
					local readbackAttempts = 0
					local readbackWaitMs = 0
					local readFailureCounts = {}
					for attempt = 1, 12 do
						readbackAttempts = attempt
						-- Retry the complete identity + source read-back. Caching the first path
						-- resolution would turn any initial lookup miss into a guaranteed failure
						-- for the whole retry window. currentScriptHashAt remains fail-closed for
						-- non-scripts and unreadable editor source.
						inst, currentHash, sourceRead = currentScriptHashAt(p)
						local classMatches = inst ~= nil and SCRIPT_CLASSES[inst.ClassName]
							and (expectedClassName == "" or inst.ClassName == expectedClassName)
						if expected ~= nil and classMatches and currentHash == expected then
							break
						end
						local attemptReason = expected == nil and "missing_expected_hash"
							or (sourceRead and sourceRead.code)
						if attemptReason == nil then
							if currentHash ~= expected then
								attemptReason = "source_hash_mismatch"
							end
						end
						if attemptReason ~= nil then
							readFailureCounts[attemptReason] = (readFailureCounts[attemptReason] or 0) + 1
						end
						if expected == nil then
							break
						end
						if attempt < 12 then
							-- Studio's editor buffer may trail an UpdateSourceAsync write for several
							-- seconds. Re-resolve and re-read with a bounded exponential delay; never
							-- substitute the handler's claimed hash for this authoritative read-back.
							local delaySeconds = math.min(0.05 * (2 ^ (attempt - 1)), 1)
							local waitedSeconds = task.wait(delaySeconds)
							readbackWaitMs = readbackWaitMs
								+ math.floor((tonumber(waitedSeconds) or delaySeconds) * 1000 + 0.5)
						end
					end
					local actualClassName = inst and inst.ClassName or nil
					local failureReason = nil
					if expected == nil then
						failureReason = "missing_expected_hash"
					elseif not inst then
						failureReason = "target_not_found"
					elseif not SCRIPT_CLASSES[actualClassName]
						or (expectedClassName ~= "" and actualClassName ~= expectedClassName) then
						failureReason = "class_mismatch"
					elseif currentHash == nil then
						failureReason = "source_unreadable"
					elseif currentHash ~= expected then
						failureReason = "source_hash_mismatch"
					end
					local classMatches = inst ~= nil and SCRIPT_CLASSES[actualClassName]
						and (expectedClassName == "" or actualClassName == expectedClassName)
					addCheck("artifact_file", p, classMatches and expected ~= nil and currentHash == expected, {
						fileId = file.fileId,
						expectedHash = expected,
						actualHash = currentHash,
						expectedClassName = expectedClassName,
						actualClassName = actualClassName or "",
						targetFound = inst ~= nil,
						classMatches = classMatches == true,
						sourceReadable = currentHash ~= nil,
						readbackAttempts = readbackAttempts,
						readbackWaitMs = readbackWaitMs,
						readbackMaxAttempts = 12,
						sourceRead = sourceRead or {},
						readFailureCounts = readFailureCounts,
						reason = failureReason,
					})
				end
			end
		end
		local uiEvidence = {}
		for _, uiRoot in ipairs(result.uiRoots or {}) do
			local path = tostring(uiRoot.path or "")
			local root = resolvePath(path)
			local actualTreeHash = root and UiArtifact.treeHash(root) or nil
			local expectedTreeHash = tostring(uiRoot.treeHash or "")
			local actualNodeIds = {}
			if root then
				for _, descendant in ipairs(root:GetDescendants()) do
					local nodeId = tostring(descendant:GetAttribute("NexusNodeId") or "")
					if nodeId ~= "" then
						table.insert(actualNodeIds, nodeId)
					end
				end
			end
			table.sort(actualNodeIds)
			local nodeIdsMatch = #actualNodeIds == #(uiRoot.nodeIds or {})
			if nodeIdsMatch then
				for index, expectedNodeId in ipairs(uiRoot.nodeIds or {}) do
					if actualNodeIds[index] ~= expectedNodeId then
						nodeIdsMatch = false
						break
					end
				end
			end
			local actualArtifactId = root and tostring(root:GetAttribute(AGENT_ARTIFACT_ID_ATTRIBUTE) or "") or ""
			local actualRootId = root and tostring(root:GetAttribute("NexusRootId") or "") or ""
			local actualDesignId = root and tostring(root:GetAttribute("NexusDesignId") or "") or ""
			local actualRevision = root and tostring(root:GetAttribute("NexusRevision") or "") or ""
			local storedTreeHash = root and tostring(root:GetAttribute("NexusTreeHash") or "") or ""
			local rootVerified = root ~= nil
				and root.ClassName == "ScreenGui"
				and actualArtifactId == tostring(uiRoot.artifactId or "")
				and actualRootId == tostring(uiRoot.rootId or "")
				and actualDesignId == tostring(uiRoot.designId or "")
				and actualRevision == tostring(uiRoot.documentRevision or "")
				and #actualNodeIds == tonumber(uiRoot.nodeCount or -1)
				and nodeIdsMatch
				and expectedTreeHash ~= ""
				and actualTreeHash == expectedTreeHash
				and storedTreeHash == expectedTreeHash
			local details = {
				rootId = uiRoot.rootId,
				designId = uiRoot.designId,
				documentRevision = uiRoot.documentRevision,
				documentTreeHash = uiRoot.documentTreeHash,
				expectedTreeHash = expectedTreeHash,
				actualTreeHash = actualTreeHash,
				storedTreeHash = storedTreeHash,
				expectedNodeCount = uiRoot.nodeCount,
				actualNodeCount = #actualNodeIds,
				nodeIdsMatch = nodeIdsMatch,
				sourceHashes = uiRoot.sourceHashes or {},
				actualArtifactId = actualArtifactId,
				actualRootId = actualRootId,
				actualDesignId = actualDesignId,
				actualRevision = actualRevision,
			}
			addCheck("artifact_ui_root", path, rootVerified, details)
			table.insert(uiEvidence, details)
		end
		if #uiEvidence > 0 then
			evidence.uiRoots = uiEvidence
		end
		for _, op in ipairs(payload.operations or {}) do
			if op.type == "delete" then
				local path = tostring(op.path or "")
				addCheck("artifact_delete", path, path ~= "" and resolvePath(path) == nil, { fileId = op.id })
			elseif op.type == "rename" then
				local fromPath = tostring(op.fromPath or "")
				local toPath = tostring(op.toPath or "")
				addCheck("path_transition", toPath, toPath ~= "" and resolvePath(toPath) ~= nil and (fromPath == toPath or resolvePath(fromPath) == nil), {
					previousPath = fromPath,
				})
			end
		end
		-- Legacy artifacts return one row per changed script rather than the
		-- managed-file manifest used by schema v2.
		if #checks == 0 then
			for _, file in ipairs(result.files or {}) do
				local path = file.path
				local inst, currentHash = currentScriptHashAt(path)
				local expected = file.sourceHash or file.resultingHash
				addCheck("artifact_file", path, inst ~= nil and expected ~= nil and currentHash == expected, {
					expectedHash = expected,
					actualHash = currentHash,
				})
			end
		end
		if #checks == 0 then
			addCheck("artifact_file", "", false, { reason = "no_artifact_readback_targets" })
		end
	elseif commandType == "replace_in_files" then
		for _, file in ipairs(result.files or {}) do
			local inst, currentHash = currentScriptHashAt(file.path)
			addCheck("replace_file", file.path, inst ~= nil and file.sourceHash ~= nil and currentHash == file.sourceHash, {
				expectedHash = file.sourceHash,
				actualHash = currentHash,
			})
		end
		if #checks == 0 then
			addCheck("replace_file", "", false, { reason = "no_changed_files_to_verify" })
		end
	elseif commandType == "rename_script" or commandType == "move_script"
		or commandType == "rename_instance" or commandType == "move_instance" then
		local target = result.path
		local previous = result.previousPath or payload.path
		addCheck("path_transition", target, type(target) == "string" and target ~= "" and resolvePath(target) ~= nil
			and (previous == target or resolvePath(previous) == nil), { previousPath = previous })
	elseif commandType == "duplicate_script" or commandType == "duplicate_instance" then
		local target = result.path or payload.newPath
		local sourcePath = result.sourcePath or payload.path
		local targetInst = resolvePath(target)
		local sourceInst = resolvePath(sourcePath)
		addCheck("instance_identity", target, targetInst ~= nil and sourceInst ~= nil and targetInst ~= sourceInst
			and targetInst.ClassName == sourceInst.ClassName, {
			sourcePath = sourcePath,
			expectedClassName = sourceInst and sourceInst.ClassName or nil,
			actualClassName = targetInst and targetInst.ClassName or nil,
		})
	elseif commandType == "insert_creator_store_asset" or commandType == "insert_uploaded_roblox_model" then
		local target = result.insertedRootPath or result.insertedPath
		local inst = resolvePath(target)
		addCheck("imported_asset", target, inst ~= nil and tostring(inst.ClassName) == tostring(result.insertedRootClass or ""), {
			assetId = tostring(result.assetId or payload.assetId or ""),
			expectedClassName = result.insertedRootClass,
			actualClassName = inst and inst.ClassName or nil,
		})
	elseif commandType == "create_animation_sequence" then
		local target = result.path
		local sequence = resolvePath(target)
		local actualHash = sequence and animationSequenceHash(sequence) or nil
		local expectedHash = result.sequenceHash
		local keyframeCount = 0
		if sequence and sequence:IsA("KeyframeSequence") then
			for _, child in ipairs(sequence:GetChildren()) do
				if child:IsA("Keyframe") then keyframeCount = keyframeCount + 1 end
			end
		end
		local verified = sequence ~= nil
			and sequence:IsA("KeyframeSequence")
			and expectedHash ~= nil
			and actualHash == expectedHash
			and keyframeCount == tonumber(result.keyframeCount or -1)
			and tostring(sequence:GetAttribute("NexusAnimationContentHash") or "") == tostring(payload.contentHash or "")
		addCheck("animation_sequence", target, verified, {
			expectedHash = expectedHash,
			actualHash = actualHash,
			expectedKeyframeCount = result.keyframeCount,
			actualKeyframeCount = keyframeCount,
			className = sequence and sequence.ClassName or nil,
		})
		evidence.readbackHash = actualHash
	elseif commandType == "build_native_model" then
		local target = result.insertedRootPath
		local modelId = payload.spec and payload.spec.modelId or result.modelId
		local _, revision = verifyNativeModelIdentity(resolvePath(target), target, modelId, nil)
		evidence.readbackRevision = revision
	elseif commandType == "apply_native_model_patch" then
		local target = result.rootPath or payload.modelPath
		local root = resolvePath(target)
		local identityOk, revision = verifyNativeModelIdentity(root, target, payload.modelId or result.modelId, result.newRevision)
		evidence.readbackRevision = revision
		local idMap = identityOk and nativeTargetMap(root) or {}
		for index, op in ipairs((payload.patch or {}).operations or {}) do
			local kind = tostring(op.op or op.type or "")
			local inst = idMap[tostring(op.targetId or "")]
			local operationOk = identityOk
			local details = {
				operationIndex = index,
				operationType = kind,
				targetId = op.targetId,
				modelId = tostring(payload.modelId or result.modelId or ""),
			}
			if kind == "set_properties" then
				local before = #checks
				checkProperties(inst, target, op.properties, "native_operation", true, index)
				operationOk = inst ~= nil and #checks > before
			elseif kind == "set_attributes" then
				local before = #checks
				checkAttributes(inst, target, op.attributes, "native_operation", index)
				operationOk = inst ~= nil and #checks > before
			elseif kind == "rename" then
				operationOk = inst ~= nil and inst.Name == tostring(op.name or "")
				details.expectedName = op.name
				details.actualName = inst and inst.Name or nil
			elseif kind == "resize" then
				local actual = inst and nativeTypedValue(inst.Size) or nil
				local expected = op.size
				if type(expected) == "table" and expected["$type"] == nil and expected.type == nil then
					expected = { ["$type"] = "Vector3", x = expected.x, y = expected.y, z = expected.z }
				end
				operationOk = inst ~= nil and valuesMatch(expected, actual)
				details.expected = expected
				details.actual = actual
			elseif kind == "add_instance" then
				local spec = op.instance or {}
				inst = idMap[tostring(spec.id or "")]
				operationOk = inst ~= nil and inst.ClassName == tostring(spec.className or "") and inst.Name == tostring(spec.name or inst.Name)
				details.targetId = spec.id
				details.expectedClassName = spec.className
				details.actualClassName = inst and inst.ClassName or nil
			elseif kind == "move_instance" then
				local parentInst = idMap[tostring(op.newParentId or "")]
				operationOk = inst ~= nil and parentInst ~= nil and inst.Parent == parentInst
				details.newParentId = op.newParentId
			elseif kind == "duplicate_instance" then
				inst = idMap[tostring(op.newIdPrefix or "")]
				operationOk = inst ~= nil
				details.targetId = op.newIdPrefix
			elseif kind == "remove_instance" then
				operationOk = idMap[tostring(op.targetId or "")] == nil
			elseif kind == "set_tags" then
				operationOk = inst ~= nil
				for _, tag in ipairs(op.add or {}) do
					operationOk = operationOk and Services.CollectionService:HasTag(inst, tostring(tag))
				end
				for _, tag in ipairs(op.remove or {}) do
					operationOk = operationOk and not Services.CollectionService:HasTag(inst, tostring(tag))
				end
			elseif kind == "transform" then
				operationOk = inst ~= nil and revision == result.newRevision
			elseif kind == "transform_model" then
				operationOk = root ~= nil and revision == result.newRevision
			else
				operationOk = false
				details.reason = "unsupported_verification_operation"
			end
			-- Property/attribute operations already emitted one exact semantic check
			-- per requested key. Emit a failure if they had no keys; other operation
			-- kinds receive one command-bound check here.
			if kind == "set_properties" or kind == "set_attributes" then
				if not operationOk then
					addCheck("native_operation", target, false, details)
				end
			else
				addCheck("native_operation", target, operationOk, details)
			end
		end
	elseif commandType == "restore_snapshot" or commandType == "undo_last_batch" then
		local snapshots = commandType == "undo_last_batch" and lastBatchSnapshots or (payload.snapshots or localSnapshots)
		for _, snap in ipairs(snapshots or {}) do
			local inst = resolvePath(snap.path)
			local actualHash = snapshotStateHash(inst)
			local ok = snap.existed == false and inst == nil
				or snap.existed ~= false and inst ~= nil and (not snap.preHash or actualHash == snap.preHash)
			addCheck("snapshot_restore", snap.path, ok, {
				expectedHash = snap.preHash,
				actualHash = actualHash,
				expectedPresent = snap.existed ~= false,
			})
		end
		if #checks == 0 then
			addCheck("snapshot_restore", "", false, { reason = "no_snapshots_to_verify" })
		end
	elseif commandType == "batch_operations" then
		for index, op in ipairs(payload.operations or {}) do
			local row = (result.results or {})[index]
			local childResult = row and row.result or nil
			local childVerified, childChecks = false, nil
			if row and row.ok == true and type(childResult) == "table" then
				childVerified, childChecks = verifyCommandOutcome({ type = op.type }, op.payload or {}, childResult)
			end
			addCheck("batch_operation", "", childVerified == true, {
				operationIndex = index,
				operationType = op.type,
				checks = childChecks,
			})
		end
		if #checks == 0 then
			addCheck("batch_operation", "", false, { reason = "empty_batch" })
		end
	else
		addCheck("instance_identity", result.path or payload.path or "", false, {
			reason = "missing_command_specific_verifier",
			commandType = commandType,
		})
	end

	local verified = true
	for _, check in ipairs(checks) do
		if not check.ok then
			verified = false
			break
		end
	end
	return verified, checks, evidence
end

executeCommand = function(command)
	local commandType = command.type or "apply_artifact"
	local handler = TOOL_HANDLERS[commandType]
	if type(handler) ~= "function" then
		local unsupportedMessage = string.format(
			"Unsupported Studio command: %s (plugin %s). Reinstall the latest NexusRBXStudioBridge.plugin.lua via Plugins > Manage Plugins.",
			tostring(commandType),
			PLUGIN_VERSION
		)
		handler = function()
			local result = structuredUnsupported(commandType, unsupportedMessage)
			result.code = "STUDIO_TOOL_UNSUPPORTED"
			result.retryable = false
			result.error.code = "STUDIO_TOOL_UNSUPPORTED"
			return result
		end
	end
	executedCommandCount = executedCommandCount + 1
	setProgress({
		runId = command.runId,
		stepId = command.stepId,
		executedCount = executedCommandCount,
	})
	setActive((command.label or commandType) .. " (" .. commandType .. ")")
	if string.find(commandType, "read") or string.find(commandType, "inspect") or string.find(commandType, "manifest") or string.find(commandType, "search") or string.find(commandType, "get_") then
		setAgentPhase("reading")
	elseif isMutatingCommand(commandType) then
		setAgentPhase("writing")
	else
		setAgentPhase("thinking")
	end
	local payload = command.payload or {}
	payload._reportProgress = function(progress)
		pcall(function()
			reportCommandProgress(command, progress)
		end)
	end
	local started = commandStartedMs()
	-- This is the final mutation boundary. Re-read live game identity immediately
	-- before invoking a write handler; approval-time checks are not sufficient
	-- because the user can switch places while the prompt is open.
	if isMutatingCommand(commandType) then
		local targetOk, targetResult = validateCommandStudioTarget(command, "before_mutation", command._approvedStudioAttestation)
		if not targetOk then
			return targetResult
		end
	end
	local result = handler(payload, command)
	if type(result) ~= "table" then
		result = { output = result }
	end
	local affected = {}
	local affectedSeen = {}
	local function addAffectedPath(candidate)
		local path = type(candidate) == "string" and candidate or nil
		if path and path ~= "" and not affectedSeen[path] then
			affectedSeen[path] = true
			table.insert(affected, path)
		end
	end
	addAffectedPath(result.path)
	addAffectedPath(result.previousPath)
	if result.files then
		for _, file in ipairs(result.files) do
			if type(file) == "table" and file.path then
				addAffectedPath(file.path)
			end
		end
	end
	if result.managedFiles then
		for _, file in ipairs(result.managedFiles) do
			if type(file) == "table" and file.canonicalPath then
				addAffectedPath(file.canonicalPath)
			end
		end
	end
	if result.uiRoots then
		for _, uiRoot in ipairs(result.uiRoots) do
			if type(uiRoot) == "table" and uiRoot.path then
				addAffectedPath(uiRoot.path)
			end
		end
	end
	local snapshots = result.snapshots
	local snapshotIds = {}
	if type(snapshots) == "table" then
		for _, snap in ipairs(snapshots) do
			if type(snap) == "table" and snap.id then
				table.insert(snapshotIds, snap.id)
			end
		end
	end
	result.success = result.ok ~= false
	result.ok = result.ok ~= false
	result.commandId = command.id
	result.runId = command.runId
	result.stepId = command.stepId
	result.operation = commandType
	result.operationId = command.operationId
	result.idempotencyKey = command.idempotencyKey
	result.affectedPaths = result.affectedPaths or affected
	result.previousHashes = result.previousHashes or {}
	result.resultingHashes = result.resultingHashes or {}
	result.warnings = result.warnings or {}
	result.diagnostics = result.diagnostics or {}
	result.output = result.output or {}
	result.duration = math.max(0, commandStartedMs() - started)
	result.snapshotIds = result.snapshotIds or snapshotIds
	result.retryable = result.retryable == true
	result.targetAttestation = currentStudioTargetAttestation(true)

	if (commandType == "get_project_manifest" or commandType == "inspect_place") and result.ok ~= false then
		setManifestInfo({
			revision = result.revision,
			itemCount = result.totalInstances or result.count,
			indexedAt = os.time(),
			staleAfter = 300,
		})
	end

	if result.ok ~= false and isMutatingCommand(commandType) then
		setAgentPhase("verifying")
	end

	if result.ok ~= false then
		local okVerify, verified, checks, verificationEvidence = pcall(verifyCommandOutcome, command, payload, result)
		if okVerify then
			result.verified = verified
			if checks then
				result.verificationChecks = checks
			end
			if isMutatingCommand(commandType) then
				verificationEvidence = type(verificationEvidence) == "table" and verificationEvidence or {}
				verificationEvidence.commandType = commandType
				verificationEvidence.checks = checks or {}
				verificationEvidence.affectedPaths = result.affectedPaths
				verificationEvidence.snapshotIds = result.snapshotIds
				result.verification = {
					verified = verified == true,
					source = "studio_readback",
					evidence = verificationEvidence,
				}
			end
			if verified == false then
				local failedPath
				for _, check in ipairs(checks or {}) do
					if not check.ok then
						failedPath = check.path
						break
					end
				end
				result.ok = false
				result.success = false
				result.retryable = true
				result.code = "apply_unverified"
				if type(result.verification) == "table" then
					result.verification.code = "STUDIO_READBACK_CHECK_FAILED"
					result.verification.message = "At least one Studio post-state check failed."
				end
				result.error = {
					code = "apply_unverified",
					message = "Command reported success but the change could not be verified in Studio"
						.. (failedPath and (" (" .. tostring(failedPath) .. ")") or ""),
					retryable = true,
				}
			end
		else
			-- A verifier exception makes the mutation outcome ambiguous. Fail closed
			-- so the backend cannot persist an apparent success without read-back.
			local verificationMessage = tostring(verified)
			local failedCheck = {
				kind = "instance_identity",
				path = result.path or payload.path or "",
				ok = false,
				reason = "verification_error",
			}
			result.verified = false
			result.verificationChecks = { failedCheck }
			result.verificationError = verificationMessage
			result.verification = {
				verified = false,
				source = "studio_readback",
				evidence = {
					commandType = commandType,
					checks = { failedCheck },
					affectedPaths = result.affectedPaths,
					snapshotIds = result.snapshotIds,
				},
				code = "STUDIO_READBACK_VERIFIER_FAILED",
				message = verificationMessage,
			}
			result.ok = false
			result.success = false
			result.retryable = true
			result.code = "apply_unverified"
			result.error = {
				code = "apply_unverified",
				message = "Command applied but Studio post-state verification failed: " .. verificationMessage,
				retryable = true,
			}
		end
	end

	-- Stamp the post-write fingerprint on each snapshot this command produced so a
	-- later restore can tell whether the user edited the instance since the agent
	-- wrote it (see restoreSnapshots' keep-my-edits logic).
	if result.ok ~= false and isMutatingCommand(commandType) and type(result.snapshots) == "table" then
		for _, snap in ipairs(result.snapshots) do
			if type(snap) == "table" and snap.path then
				local okHash, hashValue = pcall(function()
					return snapshotStateHash(resolvePath(snap.path))
				end)
				if okHash then
					snap.postHash = hashValue
				end
			end
		end
	end

	if result.ok == false and type(result.error) ~= "table" then
		result.error = {
			code = tostring(result.code or "studio_command_failed"),
			message = tostring(result.error or "Studio command failed"),
			retryable = result.retryable,
		}
	end
	return result
end

local function finalizeCommandOutcome(command, applyOk, resultOrError)
	local commandType = command.type or "command"
	local snapshotCount = (type(resultOrError) == "table" and #(resultOrError.snapshots or {})) or 0
	local duration = type(resultOrError) == "table" and resultOrError.duration or nil

	if applyOk and type(resultOrError) == "table" and resultOrError.ok == false then
		local rawError = resultOrError.error
		local message
		if type(rawError) == "table" then
			message = tostring(rawError.message or rawError.code or "Studio command failed")
		else
			message = tostring(rawError or "Studio command failed")
		end
		if not ack(command, "failed", resultOrError, message) then
			resultOrError.outcome = isMutatingCommand(commandType) and "studio_state_uncertain" or "failed_unconfirmed"
			resultOrError.receiptPending = true
			setBridgeState("reconciling", "result confirmation pending")
			setLast(commandType .. " finished locally; website confirmation is pending")
			pushActivity({ commandType = commandType, status = "uncertain", duration = duration, snapshotCount = snapshotCount, detail = message })
			showToast("Confirming " .. commandType .. " result", "info")
			return "uncertain"
		end
		setLast(commandType .. " failed: " .. message)
		pushActivity({
			commandType = commandType,
			status = "failed",
			duration = duration,
			snapshotCount = snapshotCount,
			detail = message,
		})
		showToast(commandType .. " failed", "error")
		return "failed"
	end

	if applyOk then
		if not ack(command, "succeeded", resultOrError, nil) then
			if type(resultOrError) == "table" then
				resultOrError.outcome = "applied_unconfirmed"
				resultOrError.receiptPending = true
			end
			setBridgeState("reconciling", "applied; result confirmation pending")
			setLast(commandType .. " applied in Studio; website confirmation is pending")
			pushActivity({ commandType = commandType, status = "uncertain", duration = duration, snapshotCount = snapshotCount, detail = "Applied in Studio; result confirmation pending" })
			showToast("Confirming " .. commandType .. " result", "info")
			return "uncertain"
		end
		local extra = ""
		if type(resultOrError) == "table" and resultOrError.validation then
			local v = resultOrError.validation
			if (v.failures or 0) > 0 then
				extra = (" - %d/%d file(s) flagged"):format(v.failures, v.total or 0)
			end
		end
		if snapshotCount > 0 then
			extra = extra .. (" (" .. snapshotCount .. " snapshot(s))")
		end
		setLast(("%s succeeded%s"):format(commandType, extra))
		pushActivity({
			commandType = commandType,
			status = "succeeded",
			duration = duration,
			snapshotCount = snapshotCount,
			detail = extra ~= "" and extra or nil,
			verified = type(resultOrError) == "table" and resultOrError.verified,
			affectedPaths = type(resultOrError) == "table" and resultOrError.affectedPaths or nil,
		})
		setAgentPhase("done")
		return "succeeded"
	end

	local message = tostring(resultOrError)
	if not ack(command, "failed", {
		outcome = isMutatingCommand(commandType) and "studio_state_uncertain" or "failed",
		operationId = command.operationId,
		idempotencyKey = command.idempotencyKey,
	}, message) then
		setBridgeState("reconciling", "result confirmation pending")
		setLast(commandType .. " stopped with an uncertain Studio result; website confirmation is pending")
		pushActivity({ commandType = commandType, status = "uncertain", duration = duration, detail = message })
		showToast("Confirming " .. commandType .. " result", "info")
		return "uncertain"
	end
	setLast(commandType .. " failed: " .. message)
	pushActivity({
		commandType = commandType,
		status = "failed",
		duration = duration,
		detail = message,
	})
	showToast(commandType .. " failed", "error")
	return "failed"
end

-- Queue of commands claimed by the poll loop but not yet executed. Polling
-- (which keeps the backend session alive) is decoupled from execution so a long
-- apply or an approval prompt can never stall the connection.
local commandQueue, queuedCommandIds, activeCommandId = {}, {}, nil
local executorBusy, executorStartedAt, EXECUTOR_WATCHDOG_MS = false, 0, 30 * 60 * 1000

function pendingCommandCount()
	return #commandQueue
end

function isExecutorBusy()
	return executorBusy == true
end

-- Poll the backend exactly once and enqueue any claimed command. This never
-- executes work itself, so it returns quickly and the session heartbeat implicit
-- in every poll stays fresh even while the executor is busy.
pullOnce = function(waitMs)
	local token = getToken()
	if not token then
		setBridgeState("unpaired")
		return { authFailed = false, idle = true, hadCommand = false, error = false }
	end

	local pollWait = math.clamp(tonumber(waitMs) or 2000, 500, 24000)
	setPollingPulse(true)
	local ok, data, statusCode = request(
		"GET",
		"/api/studio/commands/next?waitMs=" .. tostring(pollWait),
		nil,
		token
	)
	setPollingPulse(false)

	if statusCode == 401 or statusCode == 403 then
		recordStudioFreshness("poll", false, "authentication expired", getLastLatencyMs())
		handleSessionExpired()
		return { authFailed = true, idle = false, hadCommand = false, error = true }
	end

	if not ok then
		recordStudioFreshness("poll", false, tostring(data), getLastLatencyMs())
		setBridgeState("degraded", "poll failed")
		setLast(tostring(data))
		return { authFailed = false, idle = false, hadCommand = false, error = true }
	end
	recordStudioFreshness("poll", true, nil, getLastLatencyMs())

	if statusCode == 204 or not data or not data.command then
		if not executorBusy and #commandQueue == 0 then
			local compatibility, detail = getStudioCompatibilityStatus()
			if compatibility == "degraded" then
				setBridgeState("degraded", detail and ("Unavailable: " .. tostring(detail)) or "Some Studio features are unavailable")
			else
				local targetReady, targetDetail = getStudioTargetReadiness()
				if targetReady == false then
					setBridgeState("target_changed", targetDetail)
				else
					setBridgeState("live")
				end
			end
			setActive("none")
			setAgentPhase("idle")
		end
		return { authFailed = false, idle = true, hadCommand = false, error = false }
	end

	local command = data.command
	command.id = command.id or command.commandId
	if not command.id then
		setBridgeState("degraded", "invalid command envelope")
		setLast("Studio command envelope did not include a command ID")
		return { authFailed = false, idle = false, hadCommand = false, error = true }
	end
	if tonumber(command.lifecycleVersion) == 2 then
		local fence = type(command.lease) == "table" and tonumber(command.lease.fence) or tonumber(command.leaseFence)
		if not fence or fence < 1 then
			setBridgeState("degraded", "invalid command lease")
			setLast("Reliable Studio command did not include a valid lease fence")
			return { authFailed = false, idle = false, hadCommand = false, error = true }
		end
		if queuedCommandIds[command.id] or activeCommandId == command.id then
			ack(command, "received", { duplicate = true }, nil)
			return { authFailed = false, idle = false, hadCommand = true, error = false }
		end
		if isMutatingCommand(command.type) then
			local reconciled, confirmed = reconcileStoredCommandReceipt(command)
			if reconciled then
				return { authFailed = false, idle = false, hadCommand = true, error = confirmed ~= true }
			end
		end
		-- A durable received receipt is the acceptance boundary. Never execute a
		-- reliable command when that receipt could not be persisted server-side.
		if not ack(command, "received", { stage = "received" }, nil) then
			setBridgeState("degraded", "receipt failed")
			setLast("Command receipt could not be saved; execution was deferred safely")
			return { authFailed = false, idle = false, hadCommand = false, error = true }
		end
	end
	queuedCommandIds[command.id] = true
	table.insert(commandQueue, command)
	setBridgeState("working", "queued " .. tostring(command.type or "command"))
	return { authFailed = false, idle = false, hadCommand = true, error = false }
end

-- Execute a single command from the queue (approval gate + run + ack). Called on
-- its own loop so it can block for as long as needed without pausing polling.
function processNextCommand()
	if executorBusy then
		if executorStartedAt > 0 and (commandStartedMs() - executorStartedAt) > EXECUTOR_WATCHDOG_MS then
			-- Safety net: the executor is a synchronous pcall, so this should be
			-- unreachable, but never let a wedged flag permanently block work.
			executorBusy = false
			executorStartedAt = 0
		else
			return false
		end
	end
	if #commandQueue == 0 then
		return false
	end

	local command = table.remove(commandQueue, 1)
	queuedCommandIds[command.id] = nil
	activeCommandId = command.id
	executorBusy = true
	executorStartedAt = commandStartedMs()
	setBusy(true)
	setBridgeState("working", command.label or command.type)

	local finished, outcome = pcall(function()
		if isMutatingCommand(command.type) then
			local targetOk, approvalAttestation = validateCommandStudioTarget(command, "before_approval", nil)
			if not targetOk then
				return finalizeCommandOutcome(command, true, approvalAttestation)
			end
			command._approvedStudioAttestation = approvalAttestation
		end
		if getApprovalModeEnabledExport() and isMutatingCommand(command.type) then
			setBridgeState("working", "awaiting approval")
			local approved = waitForApproval(command)
			if not approved then
				return finalizeCommandOutcome(command, true, {
					ok = false,
					success = false,
					code = "STUDIO_APPROVAL_DECLINED",
					operationId = command.operationId,
					idempotencyKey = command.idempotencyKey,
					error = { code = "STUDIO_APPROVAL_DECLINED", message = "declined in Studio", retryable = false },
				})
			end
		end
		if tonumber(command.lifecycleVersion) == 2 then
			if not ack(command, "started", { stage = "started" }, nil) then
				setLast("Command start receipt could not be saved; execution was deferred safely")
				setBridgeState("degraded", "start receipt failed")
				return "deferred"
			end
			if isMutatingCommand(command.type) and not storeCommandReceipt(command, "started", {
				outcome = "execution_started",
				operationId = command.operationId,
				idempotencyKey = command.idempotencyKey,
			}) then
				setLast("The local operation journal could not be saved; execution was deferred safely")
				setBridgeState("degraded", "operation journal unavailable")
				return "deferred"
			end
		end

		local recording = beginRecording("NexusRBX " .. tostring(command.type or "command"))
		local applyOk, resultOrError = pcall(function()
			return executeCommand(command)
		end)
		if applyOk then
			finishRecording(recording, type(resultOrError) == "table" and resultOrError.ok ~= false)
		else
			finishRecording(recording, false)
		end
		return finalizeCommandOutcome(command, applyOk, resultOrError)
	end)
	if not finished then
		local fatalMessage = "Studio command executor crashed: " .. tostring(outcome)
		local crashResult = {
			ok = false,
			success = false,
			verified = false,
			retryable = true,
			code = "STUDIO_EXECUTOR_CRASH",
			commandId = command.id,
			runId = command.runId,
			stepId = command.stepId,
			operation = command.type,
			operationId = command.operationId,
			idempotencyKey = command.idempotencyKey,
			error = {
				code = "STUDIO_EXECUTOR_CRASH",
				message = fatalMessage,
				retryable = true,
			},
		}
		local ackCallOk, ackConfirmed = pcall(function()
			return ack(command, "failed", crashResult, fatalMessage)
		end)
		local receiptConfirmed = ackCallOk and ackConfirmed == true
		if receiptConfirmed then
			setBridgeState("degraded", "command executor recovered from a crash")
		else
			setBridgeState("reconciling", "executor crash receipt pending")
		end
		setLast(fatalMessage)
		pushActivity({
			commandType = command.type or "command",
			status = receiptConfirmed and "failed" or "uncertain",
			detail = fatalMessage,
		})
		outcome = receiptConfirmed and "failed" or "uncertain"
	end

	executorBusy = false
	executorStartedAt = 0
	activeCommandId = nil
	setActive("none")
	setBusy(false)
	if #commandQueue == 0 and outcome ~= "uncertain" and outcome ~= "deferred" then
		local compatibility, detail = getStudioCompatibilityStatus()
		if compatibility == "degraded" then
			setBridgeState("degraded", detail and ("Unavailable: " .. tostring(detail)) or "Some Studio features are unavailable")
		else
			local targetReady, targetDetail = getStudioTargetReadiness()
			if targetReady == false then
				setBridgeState("target_changed", targetDetail)
			else
				setBridgeState("live")
			end
		end
	end
	return finished ~= false
end
end
-- END src/commands/registry.lua

-- BEGIN src/Main.server.lua
do
	local override = plugin:GetSetting("nexusrbxBackendUrl")
	if type(override) == "string" and string.find(string.lower(override), "railway.app", 1, true) then
		plugin:SetSetting("nexusrbxBackendUrl", nil)
	end
end

-- Command delivery stays closed until the backend has acknowledged this exact
-- bundle. Network failures are treated as a connection repair, never as proof
-- that the plugin is obsolete.
local compatibilityHandshakeReady = false
local compatibilityStatus = "unknown"
local compatibilityDetail = nil

local function studioAttestationPayload()
	local attestation = getPluginAttestation()
	local target = currentStudioTargetAttestation(true)
	local payload = {
		connectorId = target.connectorId,
		sessionId = target.sessionId,
		targetId = target.targetId,
		placeName = target.placeName,
		placeId = target.placeId,
		universeId = target.universeId,
		placeSignature = target.placeSignature,
		targetGeneration = target.targetGeneration,
		placeChanged = target.placeChanged == true,
		attestedAt = target.attestedAt,
		pluginVersion = attestation.pluginVersion,
		protocolVersion = attestation.protocolVersion,
		buildId = attestation.buildId,
		supportedCommands = attestation.supportedCommands,
		capabilities = attestation.capabilities,
	}

	local enabledCapabilities = {}
	for capability, enabled in pairs(attestation.capabilities or {}) do
		if enabled == true then
			table.insert(enabledCapabilities, tostring(capability))
		end
	end
	table.sort(enabledCapabilities)
	local commands = table.clone(attestation.supportedCommands or {})
	table.sort(commands)
	local fingerprintInput = table.concat({
		payload.pluginVersion,
		payload.protocolVersion,
		payload.buildId,
		table.concat(commands, ","),
		table.concat(enabledCapabilities, ","),
	}, "|")
	local hash = 2166136261
	for index = 1, #fingerprintInput do
		hash = bit32.bxor(hash, string.byte(fingerprintInput, index))
		hash = (hash * 16777619) % 4294967296
	end
	payload.attestationFingerprint = string.format("%08x", hash)
	return payload
end

local function resetCompatibilityHandshake()
	compatibilityHandshakeReady = false
	compatibilityStatus = "unknown"
	compatibilityDetail = nil
end

function getStudioCompatibilityStatus()
	return compatibilityStatus, compatibilityDetail
end

local function compatibilityFromHeartbeat(heartbeat)
	if type(heartbeat) ~= "table" then
		return nil
	end
	if type(heartbeat.compatibility) == "table" then
		return heartbeat.compatibility
	end
	if type(heartbeat.details) == "table" and type(heartbeat.details.compatibility) == "table" then
		return heartbeat.details.compatibility
	end
	return nil
end

local function applyCompatibility(heartbeat)
	local compatibility = compatibilityFromHeartbeat(heartbeat)
	if not compatibility then
		return false
	end
	compatibilityStatus = tostring(compatibility.status or "unknown")
	local missingCommand = type(compatibility.missingCommands) == "table" and compatibility.missingCommands[1] or nil
	local missingCapability = type(compatibility.missingCapabilities) == "table" and compatibility.missingCapabilities[1] or nil
	local reasonCode = type(compatibility.reasonCodes) == "table" and compatibility.reasonCodes[1] or nil
	compatibilityDetail = missingCommand or missingCapability or reasonCode

	if compatibilityStatus == "compatible" or compatibilityStatus == "degraded" then
		local targetReady, targetDetail = getStudioTargetReadiness()
		if targetReady == false then
			-- A compatible build is not sufficient to open command delivery. The
			-- authenticated heartbeat must also resume the exact target generation.
			compatibilityHandshakeReady = false
			setBridgeState("target_stale", targetDetail)
			setLast(targetDetail or "Restoring Studio target generation")
			return true
		end
		compatibilityHandshakeReady = true
		if compatibilityStatus == "degraded" then
			setBridgeState("degraded", compatibilityDetail and ("Unavailable: " .. tostring(compatibilityDetail)) or "Some Studio features are unavailable")
			setLast(compatibilityDetail and ("Connected with limited features: " .. tostring(compatibilityDetail)) or "Connected with limited Studio features")
		else
			-- Compatible must leave CONNECTING. Previously only degraded/live
			-- poll paths updated the pill, so a healthy handshake could stick on
			-- "CONNECTING" / "Restoring Studio connection" forever.
			setBridgeState("live")
			setLast("Studio connection ready")
		end
		return true
	end

	compatibilityHandshakeReady = false
	if compatibilityStatus == "update_required" then
		setBridgeState("error")
		setLast("This Studio plugin release is no longer supported. Reinstall NexusRBXStudioBridge.plugin.lua.")
	else
		setBridgeState("connecting")
		local reason = compatibilityDetail and tostring(compatibilityDetail) or compatibilityStatus
		setLast("Restoring Studio connection (" .. reason .. ")")
	end
	return true
end

local function pairStudio()
	if pairButton:GetAttribute("NexusEnabled") ~= true then
		return
	end
	local code = string.upper((codeBox.Text or ""):gsub("%s+", ""))
	if code == "" then
		setStatus("enter pairing code")
		codeBox:CaptureFocus()
		return
	end

	setBusy(true)
	setStatus("pairing...")
	local ok, dataOrError = request("POST", "/api/studio/pair/claim", {
		code = code,
		studio = studioAttestationPayload(),
	}, nil)

	setBusy(false)
	if not ok then
		local message = tostring(dataOrError or "Pairing failed")
		setStatus("pair failed")
		setLast(message)
		showToast(message, "error")
		codeBox:CaptureFocus()
		return
	end

	setToken(dataOrError.token)
	plugin:SetSetting("nexusrbxStudioSessionId", dataOrError.sessionId)
	updateStudioServerTarget(dataOrError)
	resetCompatibilityHandshake()
	-- Pairing already returns the authoritative compatibility contract. Apply it
	-- immediately so reconnect does not wait on a later ping that can leave the
	-- UI stuck in CONNECTING while the session is actually usable.
	if not applyCompatibility(dataOrError) then
		setBridgeState("connecting")
		setLast("Studio paired · finishing secure handshake")
	elseif compatibilityHandshakeReady then
		setLast("Studio paired and ready")
	end
	codeBox.Text = ""
	setStatus("connected")
	pushActivity({
		commandType = "pair",
		status = "succeeded",
		detail = "Secure Studio connection established",
	})
	showToast("Studio paired", "success")
	refreshControls()
	task.spawn(function()
		bootstrapStudioConversation(true)
		refreshStudioSelection()
	end)
end

pairButton.MouseButton1Click:Connect(pairStudio)

codeBox.FocusLost:Connect(function(enterPressed)
	if enterPressed then
		pairStudio()
	end
end)

pullButton.MouseButton1Click:Connect(function()
	if pullButton:GetAttribute("NexusEnabled") == true then
		if not compatibilityHandshakeReady then
			setLast("Restoring Studio connection")
			showToast("Restoring Studio connection", "info")
			return
		end
		local result = pullOnce(2000)
		setHealth(os.time(), getLastLatencyMs())
		if result and result.error and not result.authFailed then
			showToast("Pull failed", "error")
		elseif result and result.idle then
			showToast("Up to date", "info")
		end
	end
end)

restoreButton.MouseButton1Click:Connect(function()
	if restoreButton:GetAttribute("NexusEnabled") == true then
		showRestoreConfirmation()
	end
end)

cancelRestoreButton.MouseButton1Click:Connect(hideRestoreConfirmation)

confirmRestoreButton.MouseButton1Click:Connect(function()
	local force = confirmRestoreButton:GetAttribute("ForceRestore") == true
	hideRestoreConfirmation()
	if #localSnapshots == 0 then
		setLast("no local snapshots to restore")
		return
	end
	local recording = beginRecording("NexusRBX restore local snapshots")
	local callOk, resultOrError = pcall(function()
		return restoreSnapshots({ snapshots = localSnapshots, force = force })
	end)
	local result = callOk and type(resultOrError) == "table" and resultOrError or nil
	local hardFailure = not callOk or not result or #(result.errors or {}) > 0
	finishRecording(recording, not hardFailure)
	if not hardFailure then
		local kept = tonumber(result.kept) or 0
		local keptText = kept > 0 and (", %d kept (you edited them)"):format(kept) or ""
		setLast(("local restore complete: %d restored, %d removed%s"):format(result.restored or 0, result.removed or 0, keptText))
		pushActivity({
			commandType = "restore_all",
			status = kept > 0 and "partial" or "succeeded",
			detail = tostring(#localSnapshots) .. " snapshots" .. keptText,
		})
		showToast(kept > 0 and ("Restored; kept %d of your edits"):format(kept) or "Snapshots restored", "success")
	else
		local message
		if not callOk then
			message = tostring(resultOrError)
		elseif result and result.errors and result.errors[1] then
			message = tostring(result.errors[1].message or "Snapshot restore incomplete")
		else
			message = tostring(result and result.error or "Snapshot restore incomplete")
		end
		setLast("local restore failed: " .. message)
		pushActivity({ commandType = "restore_all", status = "failed", detail = message })
		showToast("Restore failed", "error")
	end
	updateSnapshotLabel()
end)

playtestLogsButton.MouseButton1Click:Connect(function()
	if playtestLogsButton:GetAttribute("NexusEnabled") == false then
		return
	end
	setButtonEnabled(playtestLogsButton, false, "Reading output...")
	local ok, result = pcall(function()
		return collectOutput({ maxMessages = 200 })
	end)
	setButtonEnabled(playtestLogsButton, true, "Check playtest output")
	if not ok or type(result) ~= "table" then
		playtestStrip.Visible = true
		playtestStrip.Text = "Could not read output logs."
		return
	end
	local summary = result.summary or {}
	local errors = tonumber(summary.errors) or 0
	local warnings = tonumber(summary.warnings) or 0
	local total = tonumber(summary.total) or 0
	local lines = {}
	if errors > 0 or warnings > 0 then
		table.insert(lines, ("<b>%d error(s), %d warning(s)</b> of %d message(s)"):format(errors, warnings, total))
	else
		table.insert(lines, ("No errors or warnings in %d message(s)."):format(total))
	end
	-- Show the last few error/warning lines for quick triage.
	local shown = 0
	local messages = result.output or {}
	for i = #messages, 1, -1 do
		local entry = messages[i]
		if entry and (entry.level == "error" or entry.level == "warning") then
			local prefix = entry.level == "error" and '<font color="#D64550">ERR</font> ' or '<font color="#D39127">WARN</font> '
			table.insert(lines, prefix .. tostring(entry.message):sub(1, 160))
			shown = shown + 1
			if shown >= 5 then
				break
			end
		end
	end
	playtestStrip.Visible = true
	playtestStrip.Text = table.concat(lines, "\n")
	pushActivity({
		commandType = "get_output_logs",
		status = errors > 0 and "failed" or "succeeded",
		detail = ("%d errors, %d warnings"):format(errors, warnings),
	})
end)

disconnectButton.MouseButton1Click:Connect(function()
	if disconnectButton:GetAttribute("NexusEnabled") ~= true then
		return
	end
	local token = getToken()
	if not token then
		setStatus("not paired")
		setLast("already disconnected")
		return
	end
	setStatus("disconnecting...")
	pcall(function()
		request("POST", "/api/studio/session/disconnect", {}, token)
	end)
	plugin:SetSetting("nexusrbxStudioToken", nil)
	plugin:SetSetting("nexusrbxStudioSessionId", nil)
	plugin:SetSetting("nexusrbxActiveChatId", nil)
	clearStudioServerTarget()
	resetCompatibilityHandshake()
	codeBox.Text = ""
	setProgress({})
	setActive("none")
	setStatus("not paired")
	setLast("disconnected")
	showToast("Studio disconnected", "info")
	refreshControls()
end)

Services.Selection.SelectionChanged:Connect(function()
	refreshStudioSelection()
end)

toggleButton.Click:Connect(function()
	widget.Enabled = not widget.Enabled
end)

local function shouldAutoPull()
	local setting = plugin:GetSetting("nexusrbxAutoPull")
	return setting ~= false
end

-- Poll loop: continuously long-polls for commands and enqueues them. Polling is
-- read-only for session credentials; the heartbeat loop owns liveness touches.
task.spawn(function()
	local idleWaitMs = 2000
	local failureBackoff = 0

	while true do
		if not getToken() then
			task.wait(2)
			continue
		end
		if not shouldAutoPull() then
			task.wait(2)
			continue
		end
		if not compatibilityHandshakeReady then
			task.wait(0.5)
			continue
		end
		-- Only claim one command at a time. While the executor is busy the ping
		-- loop keeps the session alive, so we don't over-claim commands that could
		-- be stranded as "delivered" if Studio closes mid-queue.
		if isExecutorBusy() or pendingCommandCount() > 0 then
			task.wait(0.25)
			continue
		end

		local result = pullOnce(idleWaitMs)
		setHealth(os.time(), getLastLatencyMs())

		if result.authFailed then
			idleWaitMs = 2000
			failureBackoff = 0
			task.wait(2)
		elseif result.error then
			failureBackoff = math.min(failureBackoff > 0 and (failureBackoff * 2) or 2, 30)
			idleWaitMs = 2000
			task.wait(failureBackoff)
		elseif result.hadCommand then
			-- More work likely waiting; poll again quickly to pipeline.
			idleWaitMs = 2000
			failureBackoff = 0
			task.wait(0.2)
		elseif result.idle then
			failureBackoff = 0
			idleWaitMs = math.min(idleWaitMs + 2000, 24000)
			task.wait(0.25)
		else
			task.wait(1)
		end
	end
end)

-- Executor loop: drains the command queue one command at a time. Runs
-- independently of polling so long applies / approval prompts can never freeze
-- the connection.
task.spawn(function()
	while true do
		if getToken() and compatibilityHandshakeReady and pendingCommandCount() > 0 then
			local ok = pcall(processNextCommand)
			if ok then
				task.wait(0.1)
			else
				task.wait(0.5)
			end
		else
			task.wait(0.2)
		end
	end
end)

-- Heartbeat loop: one request keeps the session live and returns collaborator
-- plus companion health summaries. The backend throttles persistence.
task.spawn(function()
	local failureCount = 0
	local activeWorkspaceProjectId = ""
	local activeWorkspaceRevision = ""
	while true do
		if getToken() then
			local studio = studioAttestationPayload()
			local ok, latency, authExpired, heartbeat = pingSession(
				getToken(),
				studio.placeSignature,
				studio
			)
			if type(heartbeat) == "table" then
				updateStudioServerTarget(heartbeat)
			end
			recordStudioFreshness("heartbeat", ok, authExpired and "authentication expired" or (ok and nil or "heartbeat request failed"), latency)
			local hadCompatibility = applyCompatibility(heartbeat)
			if ok then
				failureCount = 0
				setHealth(os.time(), latency)
				if studio.placeChanged == true then
					task.spawn(function()
						bootstrapStudioConversation(true)
						refreshStudioSelection()
					end)
				end
				if type(heartbeat) == "table" then
					local workspace = type(heartbeat.workspace) == "table" and heartbeat.workspace or {}
					local nextProjectId = tostring(workspace.activeProjectId or "")
					local nextRevision = tostring(workspace.revision or "")
					local projectIdentityChanged = activeWorkspaceProjectId ~= "" and nextProjectId ~= "" and (
						nextProjectId ~= activeWorkspaceProjectId
					)
					local projectChanged = activeWorkspaceProjectId ~= "" and nextProjectId ~= "" and (
						nextProjectId ~= activeWorkspaceProjectId or nextRevision ~= activeWorkspaceRevision
					)
					activeWorkspaceProjectId = nextProjectId
					activeWorkspaceRevision = nextRevision
					if projectChanged then
						task.spawn(function() bootstrapStudioConversation(true, projectIdentityChanged) end)
					end
					refreshStudioSelection()
					updateCollaborators(heartbeat.collaborators)
					if type(heartbeat.mcp) == "table" then
						setMcpCompanionStatus(heartbeat.mcp)
					end
				end
			elseif authExpired then
				failureCount = 0
				resetCompatibilityHandshake()
				local replaced = type(heartbeat) == "table" and heartbeat.code == "STUDIO_SESSION_REPLACED"
				handleSessionExpired(replaced and "replaced" or nil)
			else
				failureCount = math.min(failureCount + 1, 8)
				if not compatibilityHandshakeReady and not hadCompatibility then
					compatibilityStatus = "repairing"
					setBridgeState("connecting")
					setLast("Restoring Studio connection")
				end
				local healthOk, healthLatency = pingHealth()
				if healthOk then
					setHealth(os.time(), healthLatency)
				end
			end
			if failureCount > 0 then
				local delay = math.min(0.75 * (2 ^ (failureCount - 1)), 30) + (math.random() * 0.35)
				task.wait(delay)
			else
				task.wait(compatibilityHandshakeReady and 15 or 1)
			end
		else
			failureCount = 0
			task.wait(1)
		end
	end
end)

updateSnapshotLabel()
publishStudioConnectionDiagnostics(currentStudioTargetAttestation(true))
if getToken() then
	setBridgeState("connecting")
	task.spawn(function()
		bootstrapStudioConversation(true)
		refreshStudioSelection()
	end)
else
	setBridgeState("unpaired")
end
